import{b as n}from"./index-DBEAxp3b.js";import{d as y,t as p}from"./index-DBEAxp3b.js";const e=[n("chau-luc-that",1,["Chia được đất với nước trên quả cầu, và nói được vì sao chia như thế.","Tell land from water on the globe, and say why the line falls where it does."],[["Quả đất có chỗ khô, có chỗ ướt. Chỗ khô lớn gọi là châu lục.","The Earth has dry parts and wet parts. A big dry one is a continent."],["Có sáu châu lục lớn. Châu Á là to nhất, và cũng đông người nhất — cứ mười người trên đời thì sáu người ở đây.","There are six continents. Asia is the biggest and the most crowded: six of every ten people alive live on it."],["Nước thì ngược lại: bốn đại dương thật ra nối liền nhau thành một khối duy nhất, chỉ là người ta chia ra rồi đặt tên cho dễ nói. Đổ một chai nước xuống biển Nha Trang, về lý thuyết nó đi được tới Bắc Cực.","Water is the other way round: the four oceans are really one connected body, cut up and named only so we can talk about them. Tip a bottle into the sea at Nha Trang and, in principle, it can reach the Arctic."]],["Đất thì bị nước chia thành từng mảng rời nhau, còn nước thì không bị gì chia cả. Nên châu lục là những mảnh, còn đại dương là một tấm.","Land is broken by water into separate pieces; water is broken by nothing. So continents are fragments, and the ocean is one sheet."],['Bẫy: nghe tên "Thái Bình Dương" là tên riêng nên tưởng nó cũng là một mảng như châu Á. Cứ hỏi lại một câu: đứng lên đó được không?','The trap: a proper name like "the Pacific" makes it sound like a piece the way Asia is. Ask one question back: could you stand on it?'],["Hỏi bố mẹ: nhà mình ở châu nào, và bố mẹ đã đi qua mấy châu rồi?","Ask at home: which continent do we live on, and how many has anyone in this house set foot on?"]),n("dai-duong",1,["Gọi đúng tên bốn đại dương và biết cái nào rộng nhất.","Name the four oceans and know which is widest."],[["Ba phần tư quả đất là nước. Chỉ một phần tư là đất.","Three quarters of the Earth is water. Only a quarter is land."],["Thái Bình Dương rộng hơn cả sáu châu lục cộng lại. Máy bay bay ngang nó mất mười mấy tiếng mà dưới cánh không thấy gì ngoài nước.","The Pacific is wider than all six continents put together. A plane crossing it flies for a dozen hours with nothing but water below."],["Biển Đông của mình là một phần của Thái Bình Dương. Nên con cá bắt được ở Phú Quốc và con cá bắt được ngoài khơi Nhật Bản đang bơi trong cùng một khối nước — chỉ là ở hai góc rất xa nhau của nó.","Our East Sea is part of the Pacific. So a fish caught off Phu Quoc and a fish caught off Japan swim in the same body of water — just in two very distant corners of it."]],["Nước tự nó chảy về chỗ thấp và nối vào nhau; chỉ có đất mới ngăn được nước. Chỗ nào đất không ngăn thì biển này thành biển kia.","Water runs to the low place and joins itself; only land can hold it apart. Wherever land does not, one sea becomes the next."],["Bẫy: tưởng biển và đại dương là hai thứ khác nhau. Biển chỉ là một góc của đại dương, thường nông hơn và gần bờ hơn.","The trap: thinking a sea and an ocean are different things. A sea is only a corner of an ocean, usually shallower and nearer the land."],["Hỏi bố mẹ: con cá trên mâm cơm tối nay từ biển nào lên?","Ask at home: which sea did the fish on tonight’s table come out of?"]),n("dong-nam-a",2,["Kể được ba nước giáp Việt Nam, và nói được vì sao cả vùng cùng ăn cơm.","Name the three countries next to Vietnam, and say why the whole region eats rice."],[["Việt Nam giáp đất liền với đúng ba nước: Trung Quốc, Lào, Cam-pu-chia.","Vietnam has a land border with exactly three countries: China, Laos and Cambodia."],["Cả vùng Đông Nam Á đều nóng, ẩm, mưa nhiều. Kiểu trời ấy hợp với đúng một thứ cây: lúa nước.","All Southeast Asia is hot, damp and rainy. That sky suits exactly one crop: wet rice."],["Nên nước nào trong vùng cũng ăn cơm, cũng có nước mắm hoặc mắm cá, cũng có nón che nắng che mưa. Giống nhau không phải vì bắt chước nhau, mà vì cùng phải trả lời một câu hỏi mà trời đặt ra.","So every country here eats rice, has a fish sauce of some kind, and a hat against sun and rain. The likeness is not copying: it is the same answer to the same question the sky asked."],['Thử nghĩ ngược lại: nếu vùng này lạnh và khô như Mông Cổ thì bữa cơm nhà mình bây giờ sẽ là thịt và sữa, chứ không phải cơm và rau — và cái nón lá thì chẳng ai nghĩ ra làm gì, vì có nắng gắt với mưa rào đâu mà che. Rất nhiều thứ mình tưởng là "văn hoá của mình" thật ra là câu trả lời cho một câu hỏi mà trời đã đặt ra từ trước khi có ai ở đây.',"Turn it round: if this region were cold and dry like Mongolia, dinner at your house would be meat and milk, not rice and greens — and nobody would have thought of the conical hat at all, with no fierce sun or sudden downpour to keep off. A great deal of what we call our culture is an answer to a question the sky asked before anyone arrived."]],["Cây mọc theo trời chứ không theo biên giới. Người ăn theo cây mọc được. Nên bản đồ món ăn giống bản đồ khí hậu hơn là giống bản đồ nước.","Plants follow the sky, not borders. People eat what will grow. So the map of food looks more like the map of climate than the map of countries."],["Bẫy: tưởng nước nào gần nhau thì giống nhau. Nhật với Việt Nam cách nhau không xa mà ăn khác hẳn — vì Nhật có mùa đông thật.","The trap: assuming neighbours are alike. Japan is not far from Vietnam and eats quite differently — because Japan has a real winter."],["Hỏi bố mẹ: nhà mình có món nào mà nước bên cạnh cũng có món gần giống thế không?","Ask at home: is there a dish we make that a neighbouring country makes a close cousin of?"]),n("vi-do-nong",3,["Đọc được vĩ độ, và đoán được nóng lạnh chỉ từ con số ấy.","Read a latitude, and guess hot or cold from that number alone."],[["Vĩ độ là số đo xa xích đạo bao nhiêu. Xích đạo là 0, hai cực là 90.","Latitude counts how far you are from the equator. The equator is 0, the poles are 90."],["Gần 0 thì nóng, gần 90 thì lạnh. Hà Nội ở vĩ độ 21, Sài Gòn ở 10, Luân Đôn ở 51.","Near 0 is hot, near 90 is cold. Hanoi sits at 21, Saigon at 10, London at 51."],["Lý do không phải là cực xa Mặt Trời hơn — chênh lệch ấy nhỏ tới mức chẳng đáng kể. Lý do là góc chiếu: ở xích đạo nắng rọi gần như thẳng đứng, ở cực thì nắng rọi xiên.","The reason is not that the poles are further from the Sun — that difference is too small to matter. The reason is angle: at the equator sunlight comes almost straight down, at the poles it slants in."],["Cầm cái đèn pin rọi thẳng xuống tờ giấy: vệt sáng nhỏ và gắt. Nghiêng đèn đi: vệt sáng dài ra, loang ra, và nhạt hẳn. Cùng bấy nhiêu ánh sáng, trải trên nhiều giấy hơn, thì mỗi chỗ được ít hơn. Toàn bộ chuyện nóng lạnh trên quả đất nằm trong cái vệt đèn pin ấy.","Shine a torch straight down on paper: a small fierce patch. Tilt it: the patch stretches, spreads and goes pale. The same light over more paper means less anywhere. The entire story of hot and cold on Earth is in that torch beam."]],["Nóng không phải do gần hay xa nguồn sáng, mà do bao nhiêu ánh sáng rơi trên mỗi mét đất. Góc chiếu quyết định điều đó.","Heat is not about being near or far from the light, but about how much light lands on each square metre. The angle decides that."],["Bẫy mà rất nhiều người lớn cũng mắc: tưởng mùa hè là vì Trái Đất đến gần Mặt Trời hơn. Thật ra tháng Bảy Trái Đất đang ở XA Mặt Trời nhất trong năm — mùa hè là chuyện của độ nghiêng, không phải khoảng cách.","A trap plenty of adults fall into: believing summer comes from being nearer the Sun. In fact the Earth is at its FURTHEST in July — summer is a matter of tilt, not distance."],["Hỏi bố mẹ: buổi trưa và buổi chiều, cái bóng của mình cái nào dài hơn — và cái nào thì nắng gắt hơn?","Ask at home: at noon and at four o’clock, which shadow is longer — and which sunlight burns more?"]),n("bon-mua-ro",3,["Giải thích được vì sao Hà Nội có mùa đông mà Sài Gòn thì không.","Explain why Hanoi has a winter and Saigon does not."],[["Trục Trái Đất nghiêng, không đứng thẳng. Cả bốn mùa sinh ra từ chỗ nghiêng ấy.","The Earth’s axis is tilted, not upright. All four seasons come out of that tilt."],["Nửa năm nửa cầu bắc ngả về phía Mặt Trời — đó là mùa hè ở đây, và cùng lúc là mùa đông ở Úc.","For half the year the northern half leans towards the Sun — summer here, and at the very same moment winter in Australia."],["Nhưng gần xích đạo thì ngả kiểu gì cũng gần như nhau, vì nắng vẫn rọi khá thẳng quanh năm. Nên ở đó không có bốn mùa, chỉ có mùa mưa và mùa khô.","But near the equator the lean changes little, because the sunlight stays fairly straight all year. So there are no four seasons there, only a wet season and a dry one."],["Nước mình dài hơn 1600 cây số nên chứa cả hai kiểu: Hà Nội ở vĩ độ 21 thì tháng Giêng rét dưới 10 độ, Sài Gòn ở vĩ độ 10 thì tháng nào cũng trên 25. Cùng một nước, cùng một ngày, mà một đầu mặc áo bông còn đầu kia mặc áo cộc.","Our country runs over 1,600 kilometres, so it holds both: Hanoi at latitude 21 drops below 10 degrees in January, while Saigon at latitude 10 never leaves the mid-twenties. One country, one day, padded coats at one end and shirtsleeves at the other."]],["Mùa không phải do gần xa Mặt Trời mà do góc nghiêng của trục. Chỗ nào góc ấy đổi nhiều thì có bốn mùa; chỗ nào đổi ít thì không.","Seasons come from the tilt of the axis, not from distance to the Sun. Where that angle swings a lot there are four seasons; where it barely swings there are none."],['Bẫy: nghĩ "nước nào cũng có bốn mùa, chỉ khác mức độ". Cả một vành đai quanh xích đạo thật sự không có mùa đông theo bất kỳ nghĩa nào.',"The trap: thinking every country has four seasons, just milder ones. A whole belt around the equator has no winter in any sense at all."],["Hỏi ông bà: hồi nhỏ ở quê, tháng nào là tháng rét nhất, và rét ấy khác bây giờ thế nào?","Ask a grandparent: growing up in the village, which month was coldest, and how did that cold differ from now?"]),n("mua-nhieu-nhat",2,["Đọc được con số lượng mưa, và biết nước mình thuộc hàng nào.","Read a rainfall figure, and know where our country sits."],[["Lượng mưa đo bằng mi-li-mét: hứng nước mưa cả năm vào một cái thùng, xem dâng cao bao nhiêu.","Rainfall is measured in millimetres: catch a year of rain in a tub and see how high it stands."],["Việt Nam khoảng 1800 tới 2000 mi-li-mét — tức là gần hai mét nước dâng lên. Còn sa mạc Sa-ha-ra thì dưới 100.","Vietnam gets 1,800 to 2,000 millimetres — nearly two metres of standing water. The Sahara desert gets under a hundred."],["Chính con số ấy quyết định gần hết mọi thứ khác: đủ nước thì trồng được lúa nước, trồng được lúa nước thì nuôi được đông người, đông người thì mọc ra làng, ra chợ, ra nghề. Một con số về trời, kéo theo cả cách sống.","That one number decides nearly everything else: enough water grows wet rice, wet rice feeds many people, many people make villages, markets and trades. A number about the sky, dragging a whole way of life behind it."]],["Cây không hỏi mình muốn gì; nó chỉ mọc được khi đủ nước và đủ ấm. Người thì phải sống theo cái cây mọc được.","A plant does not ask what you want; it grows only where there is enough water and warmth. People then live off whatever grows."],["Bẫy: nghĩ mưa nhiều là xui. Mưa nhiều đúng lúc là cả một vụ mùa; mưa nhiều sai lúc mới là lụt. Cùng một con số, hai kết cục.","The trap: thinking heavy rain is bad luck. Heavy rain at the right time is a harvest; heavy rain at the wrong time is a flood. Same number, two outcomes."],["Hỏi bố mẹ: năm nay mưa nhiều hay ít hơn mọi năm, và bố mẹ biết điều đó bằng cách nào?","Ask at home: has this year been wetter or drier than usual, and how do you know?"]),n("song-lon-tg",2,["Nói được vì sao có núi thì mới có sông.","Say why there are no rivers without mountains."],[["Nước chỉ đi một chiều: xuống chỗ thấp hơn.","Water only ever goes one way: to the lower place."],["Mưa rơi trên núi, gom lại thành suối, suối gom thành sông, sông tìm đường thấp nhất mà ra biển.","Rain falls on the hills, gathers into streams, streams into a river, and the river takes the lowest road to the sea."],["Sông Mê Kông bắt đầu tận cao nguyên Tây Tạng, chảy qua sáu nước rồi mới tới đồng bằng Nam Bộ. Suốt đường đi nó bào đá núi thành bùn và chở theo — nên khi ta đứng trên cánh đồng, ta đang đứng trên một ngọn núi đã bị chở về đây.","The Mekong starts on the Tibetan plateau, runs through six countries and only then reaches the southern delta. All the way it grinds mountain rock into silt and carries it — so standing in a paddy field, you stand on a mountain that was delivered here."]],["Sông không phải một vật, nó là một đường đi: đường ngắn nhất mà nước tìm được từ cao xuống thấp. Đổi địa hình thì đổi luôn dòng sông.","A river is not a thing, it is a route: the shortest road water can find from high to low. Change the land and the river changes with it."],["Bẫy: tưởng sông và núi là hai thứ đối nhau. Chúng là một cặp — không có chỗ cao thì nước đứng yên thành đầm, không thành sông được.","The trap: taking rivers and mountains for opposites. They are a pair — with no high ground the water stands still as marsh and never becomes a river."],["Hỏi bố mẹ: con sông gần nhà mình chảy về hướng nào, và cuối cùng nó đổ ra đâu?","Ask at home: which way does the nearest river run, and where does it finally empty?"]),n("cao-hon-1000",3,["Đoán được trời lạnh đi bao nhiêu khi lên cao.","Work out how much colder it gets as you climb."],[["Càng lên cao càng lạnh. Cứ 100 mét thì lạnh đi khoảng nửa độ.","The higher you go the colder it gets — about half a degree for every 100 metres."],["Fansipan cao 3143 mét. Chân núi 25 độ thì trên đỉnh chỉ còn khoảng 9 độ, dù cùng một buổi trưa.","Fansipan is 3,143 metres. If the foot is 25 degrees, the summit is about 9 — on the same afternoon."],["Everest cao 8849 mét, gần gấp ba Fansipan. Trên đó lạnh dưới âm 30 độ và không khí loãng tới mức không thở nổi nếu không tập nhiều năm.","Everest is 8,849 metres, nearly three times Fansipan. Up there it is below minus 30 and the air is so thin that breathing takes years of training."],["Vì sao lên cao lại lạnh, dù gần Mặt Trời hơn? Vì không khí không được hâm nóng từ trên xuống mà từ dưới lên: mặt đất hút nắng, nóng lên, rồi mới hâm lớp khí sát nó. Càng xa cái bếp ấy thì càng lạnh — và cái bếp nằm ở dưới chân, không phải ở trên trời.","Why colder when you are nearer the Sun? Because air is not warmed from above but from below: the ground soaks up sunlight, heats up, and warms the layer touching it. The further from that stove the colder — and the stove is underfoot, not overhead."]],["Không khí trong suốt nên nắng đi xuyên qua mà không hâm nóng nó mấy. Đất thì chặn nắng lại nên nóng lên. Mặt đất mới là cái lò sưởi của bầu trời.","Air is transparent, so sunlight passes through it barely warming it. The ground stops the light and heats up. The land is the sky’s radiator."],['Bẫy: nghĩ đỉnh núi lạnh vì "có tuyết". Ngược lại — có tuyết là VÌ lạnh. Lẫn nguyên nhân với kết quả là kiểu nhầm hay gặp nhất khi học tự nhiên.',"The trap: thinking a peak is cold because there is snow. The other way round — snow is there BECAUSE it is cold. Swapping cause and effect is the commonest slip in learning about nature."],["Hỏi bố mẹ: đã ai trong nhà lên Sa Pa hay Đà Lạt chưa, và trên đó cần mặc thêm gì?","Ask at home: has anyone been up to Sa Pa or Da Lat, and what extra clothing did it need?"]),n("song-qua-viet",2,["Nói được đồng bằng nhà mình từ đâu mà có.","Say where the plain your family lives on came from."],[["Hai đồng bằng lớn của nước ta đều do sông đắp ra, không phải tự nhiên có.","Both of our great plains were laid down by rivers; neither was simply there."],["Sông Hồng đắp đồng bằng Bắc Bộ. Sông Mê Kông đắp đồng bằng Nam Bộ. Mỗi năm chúng bồi thêm một lớp mỏng.","The Red River built the northern delta. The Mekong built the southern one. Each year they add another thin layer."],["Phù sa là đất núi bị nước bào ra rồi chở đi. Tới cửa sông thì dòng chậm lại, bùn không trôi nổi nữa nên lắng xuống — nghìn năm như thế thì thành cánh đồng. Cà Mau bây giờ vẫn đang dài ra về phía biển vài chục mét mỗi năm.","Silt is mountain soil ground off and carried away. At the mouth the current slows, the mud can no longer stay afloat and settles — a thousand years of that makes a field. Ca Mau is still growing seaward by tens of metres a year."]],["Nước mang được bùn khi chảy nhanh và thả bùn ra khi chảy chậm. Đồng bằng chính là chỗ dòng sông chậm lại.","Water carries mud while it runs fast and drops it when it slows. A delta is simply the place where the river slowed down."],["Bẫy: nghĩ đất là thứ đứng yên, có sẵn từ đầu. Đất di chuyển — chậm thôi, nhưng đi cả nghìn cây số.","The trap: taking land for something fixed that was always there. Land travels — slowly, but for a thousand kilometres."],["Hỏi ông bà: hồi các cụ còn bé, bờ sông ở chỗ nào so với bây giờ?","Ask a grandparent: when they were small, where did the riverbank sit compared with now?"]),n("giap-bien",2,["Kể được cái được và cái mất của một tỉnh giáp biển.","Name what a coastal province gains and what it pays."],[["Bờ biển nước ta dài hơn 3200 cây số, nên chỗ nào cũng gần biển.","Our coast runs over 3,200 kilometres, so nowhere here is far from the sea."],["Giáp biển thì được cá, được muối, được cảng để buôn bán với cả thế giới — chỗ xa biển nhất nước cũng chỉ cách khoảng 500 cây số.","A coast brings fish, salt and harbours that trade with the whole world — and the most inland point in the country is only some 500 kilometres away."],["Nhưng cũng chính chỗ ấy đón bão trước, và khi nước biển dâng thì mặn xâm vào ruộng trước. Miền Tây bây giờ có những cánh đồng phải bỏ vì nước lợ. Không có vị trí nào chỉ toàn cái lợi — chọn chỗ đứng là chọn luôn cả rủi ro đi kèm.","And that same edge takes the typhoon first, and the salt into the fields first when the sea rises. In the Mekong Delta some fields have been abandoned to brackish water. No location is all advantage — choosing where to stand chooses the risk that comes with it."]],["Biển vừa là đường đi vừa là mặt giáp. Cái làm cho buôn bán dễ cũng làm cho bão và nước mặn vào dễ.","The sea is both a road and an exposed flank. What makes trade easy makes storms and salt easy too."],["Bẫy: nghĩ ở đâu tốt hơn ở đâu. Không nơi nào tốt hơn hẳn — chỉ có nơi nào hợp với việc gì, và trả giá bằng gì.","The trap: asking which place is better. No place is simply better — only better for something, and paid for with something."],["Hỏi bố mẹ: nhà mình cách biển bao xa, và có năm nào bão vào tới nhà không?","Ask at home: how far are we from the sea, and has a storm ever reached this house?"]),n("mien-bac-viet",1,["Chỉ được ba miền trên bản đồ và nói được cái khác nhau lớn nhất.","Point to the three regions on the map and name the biggest difference."],[["Nước mình dài hơn 1600 cây số, chia làm ba miền: Bắc, Trung, Nam.","Our country is more than 1,600 kilometres long, in three regions: north, centre, south."],["Miền Bắc có mùa đông thật, có rét. Miền Nam thì nóng quanh năm, chỉ chia mùa mưa với mùa khô.","The north has a real winter and real cold. The south is hot all year, split only into wet and dry."],["Đi tàu từ Hà Nội vào Sài Gòn mất hơn ba mươi tiếng. Trên đường ấy, giọng nói đổi dần, món ăn đổi dần, và cái áo trên người cũng phải cởi bớt dần.","The train from Hanoi to Saigon takes over thirty hours. Along the way the accent shifts, the food shifts, and one by one the layers come off."]],["Một nước dài theo chiều bắc–nam thì đi qua nhiều vĩ độ, mà vĩ độ quyết định nắng. Nên dài theo chiều ấy nghĩa là chứa nhiều kiểu trời trong một biên giới.","A country long from north to south crosses many latitudes, and latitude decides the sunlight. So being long that way means holding several skies inside one border."],["Bẫy: tưởng cùng một nước thì thời tiết giống nhau. Cùng một ngày tháng Giêng, ngoài Bắc 8 độ mà trong Nam 32 độ.","The trap: expecting one country to have one weather. On the same January day it can be 8 degrees in the north and 32 in the south."],["Hỏi bố mẹ: nhà mình ở miền nào, và có ai trong nhà từng sống ở miền khác không?","Ask at home: which region are we in, and has anyone here ever lived in another?"])],i=[n("ven-song-lon",3,["Giải thích được vì sao thành phố đầu tiên mọc bên sông chứ không mọc trên núi.","Explain why the first cities rose beside rivers and not on hills."],[["Trước khi có thành phố, ai cũng phải tự đi kiếm ăn cả ngày.","Before cities, everyone spent the whole day finding their own food."],["Sông lớn lụt mỗi năm, rút đi để lại một lớp phù sa. Phù sa nuôi lúa rất khoẻ.","A great river floods each year and pulls back leaving a layer of silt. Silt grows grain extremely well."],["Khi một người làm ruộng nuôi được ba người, thì hai người kia không phải ra đồng nữa. Họ đi làm việc khác: đúc đồng, xây nhà, chữa bệnh, cúng bái, ghi chép.","Once one farmer can feed three people, two of them need not go to the field. They do something else: cast bronze, build, heal, perform rites, keep records."],["Và đây là chỗ bất ngờ: chữ viết không ra đời để làm thơ. Những tấm đất sét cổ nhất mà người ta đào được ở Lưỡng Hà chỉ ghi có bấy nhiêu — bao nhiêu bao lúa, của ai, vào kho ngày nào. Thơ ca đến sau, cả nghìn năm sau.","And here is the surprise: writing was not invented for poetry. The oldest clay tablets dug up in Mesopotamia say only this — so many sacks of barley, whose, received on which day. Poetry came later, a thousand years later."]],['Mọi thứ gọi là "văn minh" đều mọc lên từ một chỗ dư ra: dư thức ăn thì mới dư người, dư người thì mới có ai đó làm việc không phải kiếm ăn.',"Everything we call civilisation grows out of a surplus: spare food makes spare people, and spare people are the ones who can do work that is not finding food."],["Bẫy: nghĩ người xưa chọn chỗ ở vì phong cảnh đẹp hay vì thiêng. Họ chọn vì chỗ ấy nuôi được nhiều miệng ăn hơn chỗ khác.","The trap: imagining ancient people chose a spot for beauty or holiness. They chose the spot that fed more mouths than the next one."],["Hỏi bố mẹ: làng gốc của nhà mình nằm cạnh sông nào, hay cạnh cái gì?","Ask at home: what river — or what else — was our family’s home village built beside?"]),n("truoc-cong-nguyen",3,["Đọc đúng một dòng thời gian có cả trước và sau Công nguyên.","Read a timeline correctly on both sides of year one."],[["Dòng thời gian có một vạch số 0, do người đời sau đặt ra.","A timeline has a zero mark, and later people chose where it goes."],["Sau vạch ấy thì đếm xuôi: 938, 1010, 1945 — số càng lớn càng gần mình.","After the mark you count forwards: 938, 1010, 1945 — the bigger the number, the nearer to us."],["Trước vạch ấy thì đếm ngược: 3000 TCN xưa hơn 500 TCN. Đây là chỗ hầu như ai cũng nhầm ít nhất một lần.","Before it you count backwards: 3000 BC is older than 500 BC. Almost everyone trips here at least once."],["Mẹo giữ cho khỏi lẫn: hình dung một cái thước, số 0 ở giữa. Đi sang phải là tiến tới hôm nay; đi sang trái là lùi về quá khứ, và đi càng xa sang trái thì số càng to. Giống hệt nhiệt độ dưới 0 độ: âm 20 lạnh hơn âm 5, dù 20 là số lớn hơn.","A trick to keep it straight: picture a ruler with zero in the middle. Rightwards is towards today; leftwards is into the past, and the further left, the bigger the number. Exactly like temperature below zero: minus 20 is colder than minus 5, even though 20 is the larger number."]],['Số trên dòng thời gian không đo "lớn bé", nó đo KHOẢNG CÁCH từ một cái mốc. Mà khoảng cách thì đo được về cả hai phía.',"A number on a timeline does not measure size, it measures DISTANCE from a mark. And distance can be measured in both directions."],["Bẫy: thấy 3000 lớn hơn 500 nên tưởng 3000 TCN gần đây hơn. Ngược hẳn.","The trap: 3000 is bigger than 500, so 3000 BC feels more recent. It is the exact opposite."],["Hỏi bố mẹ: ông bà sinh năm nào, và như thế là cách đây bao nhiêu năm?","Ask at home: what year was a grandparent born, and how many years ago does that make it?"]),n("nghe-tu-thoi-lam-ruong",2,["Nói được nghề nào sinh ra từ cái máy nào.","Say which trade was born from which machine."],[["Cày, dệt, gốm, rèn đã có hơn năm nghìn năm và tới nay vẫn còn người làm.","Ploughing, weaving, pottery and smithing are over five thousand years old."],["Lập trình, phi công, thợ điện, quay phim — cả bốn đều chưa đầy một trăm rưỡi năm.","Coding, flying, wiring, filming — none of these is a hundred and fifty years old."],["Nghề sinh ra từ công cụ. Có máy bay thì mới có phi công; có điện thì mới có thợ điện. Và cũng có nghề mất đi: người thắp đèn đường, người gọi công nhân dậy đi làm, người nối dây điện thoại — từng là nghề thật, nuôi cả nhà, giờ không còn ai làm nữa.","Trades are born from tools. No aeroplane, no pilot; no electricity, no electrician. And trades die too: the lamplighter, the knocker-up who woke workers, the telephone operator — real jobs that fed families, and nobody does them now."]],['Công cụ đi trước, nghề đi sau. Nên hỏi "sau này làm nghề gì" thật ra là hỏi "sau này người ta sẽ có cái máy gì".',"The tool comes first and the trade follows. So asking what job you will do is really asking what machine will exist by then."],["Bẫy: tưởng nghề nào mất đi cũng là mất mát. Người thắp đèn mất việc, nhưng cả thành phố có đèn suốt đêm. Thay đổi thường vừa mất vừa được, và hai bên không rơi vào cùng một người.","The trap: reading every vanished trade as a loss. The lamplighter lost his job, and the whole city gained light all night. Change usually costs and pays at once — and rarely to the same person."],["Hỏi ông bà: ngày xưa ở làng có nghề nào mà bây giờ không còn ai làm?","Ask a grandparent: was there a trade in the village that nobody does any more?"]),n("de-che-lon",3,["Phân biệt được một đế chế với một thành phố buôn bán.","Tell an empire apart from a trading city."],[["Đế chế là một nhà nước cai trị nhiều dân tộc khác tiếng nói.","An empire is one state ruling many peoples of different tongues."],["La Mã, Mông Cổ, Hán, Ottoman — đều rất rộng, đều giữ bằng quân đội, và đều tan.","Rome, the Mongols, the Han, the Ottomans — all vast, all held by armies, and all gone."],["Bên cạnh chúng là một thứ khác hẳn: thành phố buôn bán. Venice, Hội An, Malacca — nhỏ tí, không quân đội đáng kể, mà giàu, vì đứng đúng chỗ trên đường hàng đi qua.","Beside them stood something quite different: the trading city. Venice, Hoi An, Malacca — tiny, with no army worth the name, and rich, because they stood in the right spot on a road that goods travelled."],["Hai kiểu quyền lực ấy hỏng theo hai cách khác nhau. Đế chế sụp khi không nuôi nổi quân đội của chính mình. Thành phố buôn bán tàn khi con đường đổi hướng — Hội An lụi đi phần lớn vì cửa sông bị bồi cạn, tàu lớn không vào được nữa. Không ai đánh nó cả.","The two kinds of power fail in two ways. An empire collapses when it can no longer feed its own army. A trading city fades when the road moves — Hoi An declined largely because its river mouth silted up and big ships could no longer enter. Nobody attacked it."]],["Quyền lực bao giờ cũng phải được nuôi bằng cái gì đó: đế chế nuôi bằng thuế và đất chiếm được, thành phố buôn bán nuôi bằng vị trí. Cái nuôi nó mất đi thì nó mất theo.","Power always feeds on something: an empire on taxes and conquered land, a trading city on its position. When the food goes, the power goes."],["Bẫy: nghĩ to là mạnh. Mông Cổ rộng nhất lịch sử mà tan trong chưa đầy trăm năm; Venice bé tí mà đứng vững tám thế kỷ.","The trap: equating big with strong. The Mongol empire was the largest ever and broke up in under a century; tiny Venice lasted eight hundred years."],["Hỏi bố mẹ: Hội An bây giờ sống bằng nghề gì, và vì sao lại đổi?","Ask at home: what does Hoi An live on now, and why did that change?"]),n("di-duong-xa-duoc",2,["Tính được món hàng nào bõ chở đi một năm trời.","Work out which goods are worth a year on the road."],[["Chở hàng đi bộ hàng năm trời thì tốn ăn, tốn người, tốn lừa ngựa.","A year of carrying goods on foot costs food, people and pack animals."],["Nên chỉ thứ nhẹ mà đắt mới bõ. Một túi tiêu bằng cả thuyền gạo.","So only what is light and precious pays. One bag of pepper is worth a boatload of rice."],["Đó là lý do đường tơ lụa chở lụa, gốm, trà, hương liệu — không phải vì người xưa thích đồ xa xỉ, mà vì toán học của chuyến đi không cho phép chở thứ khác.","That is why the Silk Road carried silk, porcelain, tea and spice — not because the ancients loved luxuries, but because the arithmetic of the journey allowed nothing else."],["Và cũng chính vì thế mà người châu Âu đi tìm đường biển sang châu Á: gia vị qua tay bốn năm người buôn thì tới nơi đắt gấp mấy chục lần. Columbus vượt Đại Tây Dương năm 1492 là đang đi tìm đường mua tiêu rẻ hơn — ông tìm nhầm ra cả một châu lục.","And it is why Europeans went hunting for a sea route to Asia: spice passing through four or five merchants arrived tens of times dearer. Columbus crossing the Atlantic in 1492 was looking for cheaper pepper — and found a continent by mistake."]],["Giá vận chuyển tính trên cân nặng, còn giá bán tính trên giá trị. Nên đường càng dài thì hàng còn đi được càng phải nhẹ và càng phải đắt.","Transport is charged by weight while goods sell by value. So the longer the road, the lighter and dearer whatever can still travel it."],['Bẫy: nghĩ ngày xưa người ta buôn bán ít vì "chưa văn minh". Họ buôn xa không kém gì bây giờ — chỉ là danh mục hàng bị luật cân nặng cắt xuống còn vài thứ.',"The trap: assuming there was little long-distance trade because people were not yet advanced. They traded just as far — the law of weight simply cut the catalogue down to a few items."],["Hỏi bố mẹ: trong bếp nhà mình, thứ gia vị nào đến từ xa nhất?","Ask at home: which spice in our kitchen came the longest way?"]),n("nam-mo-duong-bien",4,["Kể được chuyện hạm đội lớn nhất thế giới bị chính triều đình mình đốt.","Tell how the largest fleet on Earth was burned by its own court."],[["Năm 1405, Trịnh Hòa dẫn hạm đội lớn nhất thế giới đi từ Trung Hoa.","In 1405 Zheng He led the largest fleet in the world out of China."],["Thuyền của ông dài gấp mấy lần thuyền Columbus, và ông đi sớm hơn Columbus gần chín mươi năm.","His ships were several times the length of Columbus’s, and he sailed nearly ninety years earlier."],["Ông tới được Ấn Độ, tới bờ đông châu Phi, mang về hươu cao cổ cho hoàng đế xem. Bảy chuyến, suốt ba mươi năm.","He reached India and the east coast of Africa, and brought a giraffe home for the emperor to see. Seven voyages across thirty years."],["Rồi triều đình đổi ý. Họ cho rằng đi biển tốn kém mà chẳng được gì, nên dừng hẳn: đốt thuyền, huỷ bản đồ, cấm đóng thuyền lớn. Cùng lúc ấy, ở đầu kia địa cầu, châu Âu bắt đầu mở ra biển.","Then the court changed its mind. It judged the voyages expensive and pointless, so it stopped: burned the ships, destroyed the charts, banned the building of large vessels. At that very moment, on the other side of the world, Europe was starting to put to sea."],["Bốn trăm năm sau, chính những con tàu châu Âu ấy quay lại gõ cửa châu Á bằng đại bác. Lịch sử không đi theo ai giỏi hơn, cũng không theo ai giàu hơn — nó đi theo ai tiếp tục. Và quyết định dừng lại, lúc ra quyết định, bao giờ cũng nghe rất hợp lý.","Four hundred years later those same European ships came back and knocked on Asia’s door with cannon. History does not follow whoever was better, nor whoever was richer — it follows whoever kept going. And the decision to stop, at the moment it is taken, always sounds entirely reasonable."]],["Một lợi thế không tự giữ được mình. Nó chỉ còn là lợi thế chừng nào còn có người tiếp tục đầu tư vào nó.","An advantage does not keep itself. It remains an advantage only while somebody keeps putting into it."],['Bẫy: đọc sử rồi nghĩ "sao họ ngu thế". Người ra quyết định năm ấy không nhìn thấy bốn trăm năm sau. Mình bây giờ cũng thế — và đó mới là bài học dùng được.',"The trap: reading history and thinking how stupid they were. The people deciding could not see four hundred years ahead. Neither can we — and that is the part of the lesson you can actually use."],["Hỏi bố mẹ: có việc gì nhà mình từng bỏ dở mà bây giờ tiếc không?","Ask at home: is there something this family started and stopped that we wish we had kept up?"]),n("chay-bang-hoi-nuoc",3,["Nói được máy hơi nước làm được điều gì mà trước đó không ai làm được.","Say what the steam engine could do that nothing before it could."],[["Trước máy hơi nước, muốn có sức thì phải có gió, có nước chảy, hoặc có cơ bắp.","Before steam, power meant wind, running water, or muscle."],["Cả ba thứ ấy đều kén chỗ: cối xay phải đặt chỗ có gió, guồng nước phải đặt cạnh suối.","All three are fussy about location: a windmill needs wind, a water wheel needs a stream."],["Máy hơi nước thì đốt than, đun nước, hơi nở ra đẩy pít-tông. Than thì chở đi đâu cũng được. Thế là lần đầu tiên trong lịch sử, sức mạnh trở thành thứ MANG THEO ĐƯỢC.","A steam engine burns coal, boils water, and the expanding steam pushes a piston. Coal can be carried anywhere. So for the first time in history, power became PORTABLE."],["Hệ quả thì lớn hơn cái máy rất nhiều: nhà máy thôi phải dựng cạnh sông, nên mọc lên ở chỗ có người; tàu hoả chạy được nên hàng đi xa mà rẻ; và cả một loại thành phố mới ra đời ở những nơi trước đó chẳng ai ở. Một cái pít-tông, mà vẽ lại bản đồ dân cư của cả châu lục.","The consequence dwarfs the machine: factories no longer had to stand beside a river, so they rose where the people were; railways made distance cheap; and a whole new kind of city appeared where nobody had lived. One piston, and the population map of a continent was redrawn."]],["Cái đổi thật sự không nằm ở chỗ máy khoẻ hơn người. Nó nằm ở chỗ sức mạnh không còn bị buộc vào một địa điểm.","The real change was not that the machine was stronger than a person. It was that power stopped being tied to a place."],['Bẫy: chỉ nhớ "máy hơi nước làm ra tàu hoả". Cái quan trọng hơn là nó gỡ nhà máy khỏi bờ sông — và chính chỗ ấy mới làm ra thành phố hiện đại.',"The trap: remembering only that steam made trains. The bigger thing is that it unhooked factories from riverbanks — and that is what made the modern city."],["Hỏi ông bà: hồi các cụ bé, trong nhà có cái máy nào không, và nó chạy bằng gì?","Ask a grandparent: was there any machine in the house when they were small, and what ran it?"]),n("sau-khi-co-may-in",3,["Nói được máy in đổi cái gì — và cái đó không phải là giấy.","Say what printing changed — and it was not paper."],[["Trước máy in, một cuốn sách phải chép tay, mất hàng tháng.","Before printing, a book was copied by hand over months."],["Nên sách đắt ngang một con bò. Cả một tỉnh có khi chỉ vài trăm cuốn.","So a book cost about what a cow cost. A whole province might hold a few hundred."],["Máy in làm sách rẻ đi hàng trăm lần. Nhưng thứ thay đổi không phải là giấy hay mực — mà là SỐ NGƯỜI ĐƯỢC PHÉP BIẾT.","Printing made books hundreds of times cheaper. But what changed was not paper or ink — it was HOW MANY PEOPLE WERE ALLOWED TO KNOW."],["Trong vòng một trăm năm sau đó, châu Âu có thêm bản đồ in hàng loạt, sách thuốc, sách nghề, và người thường biết đọc. Ai cũng kiểm tra được điều người khác nói. Đó là điều kiện để có khoa học — không phải thiên tài, mà là việc nhiều người cùng đọc được một thứ rồi cãi nhau về nó.","Within a century Europe had mass-printed maps, medical books, trade manuals, and ordinary readers. Anyone could check what anyone else claimed. That is the condition for science — not genius, but many people reading the same thing and arguing about it."]],["Kiến thức chỉ lớn lên được khi nó rẻ để sao chép và dễ để kiểm tra. Máy in làm được cả hai việc ấy cùng lúc.","Knowledge only grows when it is cheap to copy and easy to check. Printing did both at once."],["Bẫy: nghĩ phát minh quan trọng là phát minh khó nhất. Máy in về kỹ thuật không khó bằng đồng hồ cùng thời — nó quan trọng vì cái nó mở ra, không vì nó tinh xảo.","The trap: assuming the important invention is the hardest one. Printing was technically simpler than the clocks of its day — it mattered for what it opened, not for its cleverness."],["Hỏi bố mẹ: cuốn sách cũ nhất trong nhà mình là cuốn nào?","Ask at home: what is the oldest book in this house?"]),n("chua-day-tram-nam",2,["So được tuổi của một phát minh với tuổi của ông bà mình.","Compare the age of an invention with the age of your grandparents."],[["Bánh xe và chữ viết đã hơn năm nghìn tuổi.","The wheel and writing are more than five thousand years old."],["Máy tính, internet, vắc-xin hiện đại thì trẻ hơn ông bà con.","The computer, the internet and the modern vaccine are younger than your grandparents."],["Thứ mới nhất bao giờ cũng có vẻ quan trọng nhất, vì nó ồn ào nhất. Nhưng thứ cũ nhất mới là thứ mọi thứ khác đứng lên trên: không có chữ viết thì không truyền lại được cách làm ra máy tính, và mỗi đời lại phải bắt đầu từ con số không.","The newest thing always seems the most important because it makes the most noise. But the oldest is what everything else stands on: without writing there is no way to pass on how to build a computer, and every generation would start from nothing."]],["Phát minh không thay thế nhau, nó chồng lên nhau. Cái mới đứng trên vai cái cũ chứ không xoá cái cũ đi.","Inventions do not replace one another, they stack. The new stands on the shoulders of the old rather than erasing it."],['Bẫy: nghĩ đời mình đang sống là đời "hiện đại", còn đời trước là "ngày xưa". Ông bà con cũng từng thấy đời mình là hiện đại nhất.',"The trap: treating your own time as the modern one and everything before as the old days. Your grandparents also felt they lived at the newest moment there was."],["Hỏi ông bà: cái máy đầu tiên trong đời các cụ mà các cụ thấy kinh ngạc là cái gì?","Ask a grandparent: what was the first machine in their life that truly astonished them?"]),n("nam-the-gioi-20",3,["Đặt được năm mốc lớn của thế kỷ 20 lên một dòng thời gian.","Place five great marks of the twentieth century on one line."],[["Thế kỷ 20 là từ năm 1901 tới năm 2000.","The twentieth century runs from 1901 to 2000."],["1903 anh em nhà Wright bay được 12 giây. 1928 Fleming tìm ra thuốc kháng sinh.","In 1903 the Wright brothers flew for twelve seconds. In 1928 Fleming found antibiotics."],["1945 lập Liên Hợp Quốc. 1969 người đặt chân lên Mặt Trăng. 1989 có World Wide Web.","In 1945 the United Nations was founded. In 1969 a person stood on the Moon. In 1989 came the World Wide Web."],["Từ chuyến bay 12 giây tới bước chân trên Mặt Trăng chỉ có 66 năm. Có những người sống đủ lâu để thấy cả hai — hồi bé xem ngựa kéo xe, về già xem tivi tường thuật người đi trên Mặt Trăng. Bốn đời người nối nhau, mà thế giới đổi nhiều hơn cả nghìn năm trước cộng lại.","From a twelve-second flight to a footprint on the Moon is sixty-six years. Some people lived to see both — horse-drawn carts as children, a live broadcast from the Moon in old age. Four lifetimes end to end, and the world changed more than in the thousand years before them."]],["Phát minh sinh ra phát minh, nên nhịp thay đổi không đều mà nhanh dần. Mỗi thứ mới lại làm cho thứ tiếp theo dễ hơn.","Inventions breed inventions, so change does not come at a steady pace but an accelerating one. Each new thing makes the next one easier."],["Bẫy: nghĩ tốc độ ấy là chuyện đương nhiên của mọi thời. Suốt hai nghìn năm trước đó, đời ông và đời cháu gần như giống hệt nhau.","The trap: assuming that pace is normal for all times. For the two thousand years before, a grandfather’s life and a grandson’s were nearly identical."],["Hỏi ông bà: năm 1969 các cụ đang ở đâu, và có nghe tin người lên Mặt Trăng không?","Ask a grandparent: where were they in 1969, and did the news of the Moon reach them?"]),n("truoc-khi-len-mat-trang",4,["Đặt hai dòng thời gian cạnh nhau và thấy hai nơi sống ở hai thời khác nhau.","Lay two timelines side by side and see two places living in different eras."],[["Năm 1957, vệ tinh đầu tiên bay lên trời.","In 1957 the first satellite went into orbit."],["Cũng năm ấy, phần lớn làng quê Việt Nam chưa có điện, và đất nước đang có chiến tranh.","That same year most Vietnamese villages had no electricity, and the country was at war."],["Cùng một quả đất, cùng một năm, mà hai nơi đang sống ở hai thời khác hẳn nhau. Điều này không phải chuyện của quá khứ: ngay bây giờ, trên đời vẫn có chỗ chưa có nước sạch trong khi chỗ khác đã có xe tự lái.","One planet, one year, and two places living in two different eras. This is not a fact about the past: right now there are places without clean water while others have self-driving cars."],['Nên khi đọc câu "thế kỷ 20 là thế kỷ của máy bay và máy tính", phải hỏi thêm: của ai? Với ông bà mình, thế kỷ 20 phần lớn là đèn dầu, gánh nước và mùa màng. Cả hai câu đều đúng, và bỏ mất câu thứ hai là bỏ mất phần lớn loài người.',"So when you read that the twentieth century was the century of aeroplanes and computers, ask: whose? For your grandparents it was mostly oil lamps, carried water and harvests. Both sentences are true, and dropping the second one drops most of humanity."]],["Thời gian thì trôi đều cho mọi người, nhưng thay đổi thì không đến đều. Nó đến trước ở chỗ có tiền và có đường sá, đến sau ở chỗ khác.","Time passes evenly for everyone, but change does not arrive evenly. It reaches money and roads first, and elsewhere later."],["Bẫy: đọc sử thế giới rồi tưởng cả thế giới cùng sống một kiểu vào một năm. Chưa bao giờ có chuyện đó.","The trap: reading world history and picturing the whole world living the same way in a given year. That has never once been the case."],["Hỏi ông bà: nhà mình có điện từ năm nào, và trước đó tối đến thì làm gì?","Ask a grandparent: what year did this family get electricity, and what did evenings look like before that?"])],a=[n("hang-tram-la-7",2,["Nói được cùng một chữ số đứng chỗ khác thì đáng khác bao nhiêu.","Say how much the same digit changes worth when it changes column."],[["Số 7 trong 703 và số 7 trong 370 là cùng một hình vẽ.","The 7 in 703 and the 7 in 370 are the same mark."],["Nhưng cái đầu đáng bảy trăm, cái sau chỉ đáng bảy chục. Chênh nhau mười lần.","But the first is worth seven hundred and the second only seventy. Ten times apart."],["Vị trí mới là thứ mang giá trị, không phải hình dáng con số. Đây là phát minh lớn nhất trong lịch sử cách viết số: chỉ mười ký hiệu mà viết được số lớn bao nhiêu cũng được, vì mỗi bước sang trái là gấp mười.","Position carries the value, not the shape of the mark. This is the great invention in the history of writing numbers: ten symbols that can write any number at all, because each step left multiplies by ten."]],["Chỗ đứng thay cho việc phải nghĩ ra ký hiệu mới. Không có luật vị trí thì mỗi lượng lớn hơn lại cần một chữ riêng, và bảng chữ số sẽ dài vô tận.","Position does the work that new symbols would otherwise have to do. Without it, every larger amount would need its own mark, and the list would never end."],["Bẫy: đọc số dài từ trái sang phải mà không để ý số chữ số. Nhìn 1712 rồi tưởng chữ số 7 là hàng trăm — đúng, nhưng phải đếm mới chắc, chứ không phải đoán theo chỗ nó nằm trong mắt.","The trap: reading a long number left to right without counting its digits. You may guess that the 7 in 1712 is hundreds — it is, but only counting proves it, not where it happens to sit in your eye."],["Hỏi bố mẹ: giá một món đồ trong nhà, chữ số đầu tiên là hàng gì?","Ask at home: on the price of something here, what column is the first digit in?"]),n("so-0-giu-cho",2,["Giải thích được số 0 trong 305 đang làm việc gì.","Explain what the zero in 305 is doing for a living."],[['Trong 305, số 0 không có nghĩa là "không có gì".','In 305 the zero does not mean "nothing".'],["Nó giữ cho số 3 đứng đúng hàng trăm. Bỏ nó đi thì 305 thành 35 — sai đi mười lần.","It keeps the 3 standing in the hundreds column. Drop it and 305 becomes 35 — ten times wrong."],["Người La Mã không có số 0 nên viết số rất dài, và làm tính thì gần như không nổi: thử nhân MCMXLVIII với XII mà xem. Số 0 đi từ Ấn Độ sang, qua thế giới Ả Rập rồi mới tới châu Âu — và nó làm cả toán học đổi khác.","Rome had no zero, so numbers ran long and arithmetic was near impossible: try multiplying MCMXLVIII by XII. Zero travelled from India through the Arab world into Europe — and it changed all of mathematics."]],["Muốn cột hàng có nghĩa thì mọi cột đều phải được điền, kể cả cột rỗng. Số 0 là cách viết ra một cái cột rỗng.","For columns to mean anything, every column must be filled — including the empty ones. Zero is how you write down an empty column."],['Bẫy: nghĩ số 0 là "không có gì" nên viết thế nào cũng được. Trong một con số, số 0 là một thông tin thật, và bỏ nó là làm hỏng số.',"The trap: treating zero as nothing much, so it hardly matters. Inside a number a zero is real information, and dropping it breaks the number."],["Hỏi bố mẹ: viết số tiền lên giấy mà quên một số 0 thì chuyện gì xảy ra?","Ask at home: what happens if you write an amount of money and leave out one zero?"]),n("lon-hon-1000",1,["So hai số nhanh mà không cần đọc hết.","Compare two numbers fast without reading all of them."],[["Đếm chữ số trước đã: bốn chữ số luôn lớn hơn ba chữ số.","Count the digits first. Four digits always beats three."],["Chỉ khi hai số cùng số chữ số mới phải so từ trái sang phải.","Only when both have the same number of digits do you compare left to right."],["So hàng lớn trước; gặp chỗ khác nhau đầu tiên là xong, không cần đọc nốt. 3512 với 3489: hàng nghìn bằng nhau, hàng trăm 5 lớn hơn 4 — dừng ở đó.","Compare the biggest column first; the first place they differ settles it and the rest need not be read. 3512 against 3489: thousands tie, hundreds are 5 against 4 — stop there."]],["Vì mỗi hàng đáng gấp mười tất cả các hàng nhỏ hơn cộng lại, nên hàng lớn hơn không bao giờ bị hàng nhỏ hơn lật ngược.","Because each column is worth ten of everything below it combined, a higher column can never be overturned by the lower ones."],["Bẫy: đọc từ phải sang, hoặc so từng chữ số một cách rời rạc. 89 với 100 — nhìn chữ số 8 và 9 to hơn 1 và 0 nên dễ chọn nhầm.","The trap: reading from the right, or comparing digits one by one out of context. In 89 against 100 the 8 and 9 look bigger than 1 and 0, and the wrong answer is easy to pick."],["Hỏi bố mẹ: hai tờ tiền trong ví, tờ nào lớn hơn — và nhìn cái gì để biết ngay?","Ask at home: of two notes in the purse, which is larger — and what tells you at a glance?"]),n("duoi-khong",3,["Đặt được số âm lên trục số và hiểu số 0 chỉ là một cái mốc.","Put negatives on the number line and see that zero is only a mark."],[["Số âm sinh ra khi cần đếm về phía ngược lại.","Negative numbers appear when you need to count the other way."],["Dưới 0 độ, nợ tiền, dưới mực nước biển, lùi mấy bước — tất cả đều là số âm.","Below zero degrees, money owed, below sea level, steps backwards — all negatives."],["Số 0 không phải điểm nhỏ nhất trên đời. Nó chỉ là cái mốc người ta chọn, và trục số chạy tiếp về cả hai phía. Chọn mốc ở đâu là tuỳ việc: mốc 0 của nhiệt độ là điểm nước đóng băng, mốc 0 của độ cao là mặt biển.","Zero is not the smallest thing there is. It is a mark we chose, and the line runs on both ways. Where you put it depends on the job: zero temperature is where water freezes, zero height is sea level."],['Và vì thế, cộng một số âm chính là trừ. Trả nợ 20 nghìn thì con số trong ví đi xuống, dù việc ấy là việc tốt — phép toán không biết tốt xấu, nó chỉ biết chiều. Trừ một số âm thì ngược lại: xoá đi một khoản nợ tức là làm cho mình giàu lên, nên trừ âm thành cộng. Chỗ này nghe như một luật học thuộc, mà thật ra chỉ là câu "bớt đi một cái thiếu thì còn lại nhiều hơn" viết bằng ký hiệu.','And so adding a negative is subtracting. Paying off a debt of 20,000 moves the number in your purse down, even though it is the right thing to do — arithmetic knows nothing of right and wrong, only of direction. Subtracting a negative runs the other way: cancelling a debt makes you richer, so minus a minus is a plus. That sounds like a rule to memorise, and it is only the sentence "take away a shortfall and more is left" written in symbols.']],["Số âm không phải một loại số lạ. Nó là số bình thường, kèm thêm một chiều — và chiều thì luôn phải đo từ một mốc nào đó.","A negative is not an exotic kind of number. It is an ordinary number with a direction attached — and direction is always measured from some mark."],["Bẫy: nghĩ âm 20 lớn hơn âm 5 vì 20 lớn hơn 5. Ngược lại: âm 20 lạnh hơn, thấp hơn, nợ nhiều hơn.","The trap: thinking minus 20 is more than minus 5 because 20 is more than 5. The reverse: minus 20 is colder, lower and deeper in debt."],["Hỏi bố mẹ: có bao giờ nhà mình phải vay tiền để mua thứ gì lớn không, và trả trong bao lâu?","Ask at home: has this family ever borrowed for something large, and how long did paying it back take?"]),n("la-so-am",2,["Nhìn ra tình huống nào ngoài đời là số âm.","Spot which everyday situations are negatives."],[["Nợ 20 nghìn và có 20 nghìn cùng một độ lớn, khác nhau ở chiều.","Owing 20,000 and having 20,000 are the same size, opposite in direction."],["Lùi ba bước, hụt năm điểm, dưới không độ — đều là cùng một ý.","Three steps back, five points short, below zero — all the same idea."],['Nhận ra được điều ấy thì số âm thôi là thứ trong sách. Nó là cách viết gọn cho một câu rất đời thường: "thiếu bấy nhiêu" hay "ngược lại bấy nhiêu".','Once you see that, negatives stop being a schoolbook thing. They are shorthand for a very ordinary sentence: "short by this much" or "this much the other way".']],["Cùng một độ lớn có thể mang hai chiều. Toán tách hai thứ đó ra: con số nói độ lớn, dấu nói chiều.","One size can carry two directions. Mathematics separates them: the number says how much, the sign says which way."],['Bẫy: nghĩ số âm là "số xấu". Trong bản đồ độ cao, âm chỉ là dưới mặt biển — Hà Lan có cả một tỉnh nằm ở số âm và sống rất tốt.',"The trap: reading a negative as a bad number. On a height map, negative just means below sea level — the Netherlands has whole provinces there, doing fine."],["Hỏi bố mẹ: tủ lạnh nhà mình ngăn đá để mấy độ?","Ask at home: what temperature is our freezer set to?"]),n("hon-nua-phan-tram",3,["Đổi một tỉ lệ bất kỳ về phần trăm để so được với thứ khác cỡ.","Turn any ratio into a percentage so unlike sizes can be compared."],[['Phần trăm nghĩa đen là "trên một trăm".','Per cent means literally "out of a hundred".'],["Nên hơn một nửa tức là hơn 50. Đơn giản thế thôi.","So more than half means more than 50. That simple."],["Người ta nghĩ ra phần trăm vì nó cho so hai thứ khác cỡ. 12 trên 20 và 30 trên 50 nhìn chẳng giống nhau chút nào, mà cả hai đều là 60%.","Percentages were invented because they let unlike sizes be compared. 12 out of 20 and 30 out of 50 look nothing alike, yet both are 60%."],["Đó cũng là lý do điểm số, lãi suất, tỉ lệ đỗ, độ pin đều nói bằng phần trăm: đưa hết về cùng một mẫu số 100 thì so được bằng mắt, không phải tính.","It is why marks, interest rates, pass rates and battery levels all speak in percentages: put everything over the same hundred and the eye can compare without arithmetic."]],["So hai phân số khác mẫu số thì khó; ép chúng về cùng một mẫu số thì dễ. Phần trăm chỉ là quy ước chọn sẵn mẫu số ấy là 100.","Comparing fractions with different bottoms is hard; forcing them onto one bottom is easy. A percentage is just the agreement that the bottom is always 100."],['Bẫy: cộng phần trăm của hai thứ khác cỡ. Lớp A đỗ 80% với 10 em, lớp B đỗ 40% với 40 em — nói chung là "đỗ 60%" thì sai, vì hai lớp không bằng nhau.',"The trap: averaging percentages of unequal groups. Class A passes 80% of 10 pupils, class B 40% of 40 — saying the average is 60% is wrong, because the classes are not the same size."],["Hỏi bố mẹ: pin điện thoại còn bao nhiêu phần trăm, và như thế là còn dùng được mấy tiếng?","Ask at home: what percentage is the phone battery on, and how many hours does that buy?"]),n("cung-mot-luong",2,["Nhận ra phân số, phần trăm và tỉ số là ba bộ áo của một lượng.","See fraction, percentage and ratio as three outfits on one amount."],[["Một phần tư viết được nhiều kiểu: 1/4, 2/8, hay 25%.","A quarter can be written several ways: 1/4, or 2/8, or 25%."],["Ba cách viết cho đúng một lượng. Chọn cách nào là tuỳ chỗ dùng.","Three ways of writing one amount. Which you use depends on the situation."],["Cắt bánh thì nói 1/4 tiện hơn; giảm giá thì nói 25% tiện hơn; pha nước chấm thì nói tỉ lệ 1 phần này 3 phần kia tiện hơn. Nhìn ra được chúng là một là lúc con hết sợ phân số.","Cutting a cake, 1/4 is handier; a discount, 25%; mixing a dipping sauce, one part to three. Seeing that they are one thing is the moment fractions stop being frightening."]],["Nhân hay chia cả tử lẫn mẫu cho cùng một số thì lượng không đổi — nên một lượng có vô số cách viết, và tất cả đều đúng.","Multiply or divide top and bottom by the same number and the amount is unchanged — so one amount has endless spellings, all of them correct."],['Bẫy: nghĩ 2/8 "bé hơn" 1/4 vì con số trông nhỏ hơn. Chúng bằng nhau tuyệt đối; chỉ có cách viết là khác.',"The trap: feeling 2/8 is smaller than 1/4 because the pieces look smaller. They are exactly equal; only the spelling differs."],["Hỏi bố mẹ: cắt cái bánh làm tám phần, ăn hai phần là ăn mấy phần tư?","Ask at home: cut a cake into eight and eat two — how many quarters is that?"]),n("ti-le-bang-nhau",3,["Giữ nguyên tỉ lệ khi nhân đôi hay chia đôi một công thức.","Hold a ratio steady when you double or halve a recipe."],[["Nhân hay chia cả hai vế cho cùng một số thì tỉ lệ không đổi.","Multiply or divide both sides by the same number and the ratio holds."],["2/4, 3/6, 5/10 đều là một nửa, dù ba cặp số chẳng cặp nào giống cặp nào.","2/4, 3/6 and 5/10 are all a half, though no two of the pairs look alike."],["Đây là luật đằng sau rất nhiều việc thật: nấu gấp đôi công thức, đọc bản đồ theo tỉ lệ, pha thuốc theo cân nặng, phóng to một bức ảnh mà không méo.","This is the law behind a lot of real work: doubling a recipe, reading a map scale, dosing medicine by body weight, enlarging a photo without distorting it."],["Chỗ hay sai nhất là cộng thay vì nhân. Công thức 2 gạo 1 nước, nấu gấp ba thì thành 6 và 3 — chứ không phải 5 và 4. Cộng thêm cùng một lượng vào hai vế thì tỉ lệ HỎNG, chỉ có nhân mới giữ được.","The commonest error is adding instead of multiplying. Two rice to one water, tripled, is 6 and 3 — not 5 and 4. Adding the same amount to both sides BREAKS the ratio; only multiplying preserves it."]],["Tỉ lệ nói về quan hệ giữa hai lượng, không về bản thân hai lượng. Nên phép nào tác động đều lên cả hai thì quan hệ ấy còn nguyên.","A ratio is about the relation between two amounts, not about the amounts themselves. So any operation applied evenly to both leaves the relation intact."],["Bẫy: cộng thay vì nhân. Nghe thì hiển nhiên, mà trong bếp thì hầu như ai cũng có lần nấu hỏng đúng vì chỗ này.","The trap: adding instead of multiplying. Obvious once said, and yet nearly everyone has ruined a pot exactly here."],["Hỏi bố mẹ: nhà mình nấu cơm mấy phần gạo mấy phần nước, và nấu gấp đôi thì làm sao?","Ask at home: how many parts rice to water do we cook, and what changes when we double it?"]),n("chia-cong-bang",3,["Nghĩ ra được một luật chia mà không cần ai đứng canh.","Invent a way of splitting that needs nobody to enforce it."],[["Hai đứa, một cái bánh. Chia thế nào cho khỏi cãi?","Two children, one cake. How do you split it fairly?"],["Cách cổ nhất và hay nhất: một đứa cắt, đứa kia chọn trước.","The oldest and best answer: one cuts, the other picks first."],["Đứa cắt tự khắc cắt cho thật đều — vì nếu cắt lệch thì nó chắc chắn được phần nhỏ. Không cần người lớn giám sát, không cần thước đo, không cần ai tin ai.","The cutter will cut evenly all by themselves — because an uneven cut guarantees them the smaller piece. No adult supervising, no ruler, no trust required."],["Đó là dấu hiệu của một luật hay: nó công bằng ngay cả khi hai bên đều đang cố giành phần hơn. Luật dở thì cần người canh; luật hay thì tự chạy. Từ chia bánh tới chia đất, chia ca trực, chia việc nhà — cứ tìm cách nào tự chạy được là tìm đúng.","That is the mark of a good rule: it stays fair even while both sides are trying to win. A bad rule needs a referee; a good one runs itself. From cake to land to rotas to housework — look for the version that runs itself."]],["Một cách chia là công bằng khi hai bên đều chịu nhận nó TRƯỚC lúc biết mình được phần nào. Thử nó bằng câu hỏi ấy là đủ.","A split is fair when both sides would accept it BEFORE knowing which share they get. Testing it with that question is enough."],["Bẫy: tưởng công bằng là phải có người lớn phân xử. Người lớn phân xử là cách chữa cháy; luật tự chạy mới là cách giải.","The trap: assuming fairness needs an adult to arbitrate. Arbitration is first aid; a self-enforcing rule is the cure."],["Hỏi bố mẹ: ở nhà mình chia việc nhà thế nào, và cách ấy có ai thấy thiệt không?","Ask at home: how do we divide the chores here, and does anyone feel short-changed?"]),n("chia-theo-can",3,["Biết lúc nào chia đều mới đúng, lúc nào chia theo nhu cầu mới đúng.","Know when an even split is right and when sharing by need is right."],[["Có thứ chia đều mới đúng: kẹo, lượt chơi, chỗ ngồi.","Some things are only fair split evenly: sweets, turns, seats."],["Có thứ chia theo nhu cầu mới đúng: thuốc, kính, thêm giờ làm bài.","Some are only fair given by need: medicine, glasses, extra time in an exam."],["Chia thuốc đều cho cả lớp thì đứa ốm vẫn ốm và đứa khoẻ thì thừa. Đưa hết thuốc cho một đứa nghe có vẻ thiên vị, mà lại là cách công bằng duy nhất.","Split the medicine evenly across the class and the ill child stays ill while the well ones get what they cannot use. Giving it all to one child sounds like favouritism, and is the only fair act available."],['"Bằng nhau" và "công bằng" không phải một từ. Người lớn cãi nhau về chính sách, về thuế, về học bổng — gần như lần nào cũng là đang cãi xem việc đang bàn thuộc loại nào trong hai loại này. Không có câu trả lời chung, chỉ có câu hỏi phải hỏi lại mỗi lần.','"Equal" and "fair" are not one word. Adults arguing about policy, tax or scholarships are nearly always arguing about which of these two kinds the case belongs to. There is no general answer, only a question to be asked again each time.']],["Chia đều là cách đúng khi mọi người cần như nhau. Khi nhu cầu khác nhau thật, chia đều lại tạo ra chênh lệch chứ không xoá nó.","An even split is right when needs are equal. Where needs genuinely differ, an even split creates a gap rather than closing one."],['Bẫy: dùng đúng một luật cho mọi việc. Đứa nào cũng đòi "phải bằng bạn" trong mọi chuyện thì có lúc chính nó thiệt — hôm nó ốm chẳng hạn.',"The trap: applying one rule to everything. A child who insists on identical treatment in all things will lose by it eventually — on the day they are the ill one."],["Hỏi bố mẹ: trong nhà có thứ gì mà mỗi người một khác chứ không chia đều không, và vì sao?","Ask at home: is there something here that is not split evenly, and why?"]),n("hua-duoc",2,["Phân biệt lời hứa nằm trong tay mình với lời hứa thay cho thời tiết.","Tell a promise inside your own hands from one made on the weather’s behalf."],[["Chỉ hứa được thứ nằm trong tay mình.","You can only promise what is in your own hands."],['"Mai con trả sách" là hứa được. "Con sẽ không bao giờ buồn" thì không.','"I will bring the book back tomorrow" can be promised. "I will never be sad" cannot.'],["Hứa thay cho cảm xúc, cho sức khoẻ, cho tương lai xa — là hứa thay cho thời tiết. Không giữ nổi, và mỗi lần không giữ được lại làm hỏng lòng tin cho những lời hứa thật.","Promising on behalf of feelings, health, or the far future is promising on behalf of the weather. Unkeepable — and each failure eats into the trust your real promises need."]],["Lời hứa là một dự đoán mà mình chịu trách nhiệm. Chỉ dự đoán được thứ mình điều khiển được.","A promise is a prediction you take responsibility for. You can only predict what you control."],["Bẫy: nghĩ hứa nhiều là tử tế. Hứa ít mà đúng thì đáng tin hơn hẳn — và người nghe cũng đỡ khổ hơn.","The trap: mistaking many promises for kindness. Few promises kept are worth far more, and are easier on whoever is listening."],["Hỏi bố mẹ: lời hứa nào hồi bé bố mẹ hứa mà không giữ được, và chuyện gì xảy ra sau đó?","Ask at home: what promise did you make as a child and fail to keep, and what happened next?"]),n("lam-mat-long-tin",3,["Hiểu vì sao lòng tin xây rất chậm mà đổ rất nhanh.","Understand why trust builds slowly and falls fast."],[["Phải đúng hẹn hàng chục lần mới xây được lòng tin.","Dozens of kept appointments to build trust."],["Một lần nói dối là gãy. Chênh lệch ấy nghe rất bất công.","One lie to break it. The imbalance sounds unjust."],["Nhưng nghĩ kỹ thì hợp lý: tin nhầm một người thì tốn hơn nhiều so với nghi oan một người. Nên bộ não người tiến hoá để cảnh giác — và không ai chọn được cái phản xạ ấy, kể cả người rất muốn tha thứ.","Yet it makes sense: trusting the wrong person costs far more than wrongly suspecting the right one. So the human brain evolved to be watchful — and nobody chooses that reflex, not even someone who badly wants to forgive."],["Điều dùng được: xây lại lòng tin thì không xin lỗi hay là xong. Xin lỗi chỉ mở được cánh cửa. Đi qua cửa thì phải bằng nhiều lần làm đúng, và bằng thời gian — đúng cái thứ mà lúc đang muốn được tha thứ thì mình thấy sốt ruột nhất.","The usable part: rebuilding trust is not done by a good apology. An apology opens the door. Walking through it takes many small kept promises and time — the very thing you feel least patient about while wanting to be forgiven."]],["Lòng tin là một dự đoán về tương lai, dựa trên bằng chứng quá khứ. Một bằng chứng ngược lại thì phá nhiều hơn một bằng chứng thuận xây được.","Trust is a prediction about the future built on past evidence. One piece of contrary evidence destroys more than one supporting piece builds."],['Bẫy: nghĩ "mình xin lỗi rồi mà nó vẫn giận, thế là nó nhỏ mọn". Không phải — nó đang đợi bằng chứng, và đợi là việc hợp lý.','The trap: thinking "I apologised and they are still cross, so they are petty". No — they are waiting for evidence, and waiting is the reasonable thing to do.'],["Hỏi bố mẹ: có ai bố mẹ từng hết tin rồi tin lại được không, và mất bao lâu?","Ask at home: has there been someone you stopped trusting and later trusted again, and how long did it take?"]),n("so-voi-chinh-minh",3,["Chọn được thước đo nói cho mình biết ngày mai nên làm gì.","Pick the measure that tells you what to do tomorrow."],[["So với chính mình hôm qua thì đo được cái mình học thêm.","Compared with yesterday, the measurement is what you learned."],["So với người khác thì phần lớn đang đo hoàn cảnh của họ.","Compared with someone else, you are mostly measuring their circumstances."],["Bạn ấy có thể bắt đầu sớm hơn ba năm, có người dạy, có thời gian, có sức khoẻ. Những thứ ấy nằm trong con số mà mình đang so, và không cái nào trong đó là việc mình làm được gì.","They may have started three years earlier, had a teacher, had time, had health. All of that sits inside the number you are comparing, and none of it is anything you can act on."],["Cả hai phép so đều cho ra một con số. Nhưng chỉ một cái nói được câu tiếp theo nên làm gì. Cái kia chỉ nói mình đang đứng thứ mấy — mà thứ hạng thì đổi mỗi lần đổi phòng, còn cái mình biết thì đi theo mình sang phòng khác.","Both comparisons yield a number. Only one of them says what to do next. The other says where you rank — and a rank changes every time the room changes, while what you know walks into the next room with you."]],["Thước đo tốt là thước đo trỏ vào một việc làm được. Thước đo trỏ vào hoàn cảnh của người khác thì không dùng vào đâu được.","A good measure points at an action you can take. A measure that points at someone else’s circumstances leads nowhere."],["Bẫy: bỏ hẳn việc so sánh. So sánh có ích thật — chỉ cần đổi mốc từ người khác sang chính mình tuần trước.","The trap: giving up comparison altogether. Comparison is useful — only move the reference point from another person to yourself last week."],["Hỏi bố mẹ: có việc gì bố mẹ làm giỏi hơn hẳn năm ngoái không, và làm sao biết?","Ask at home: is there something you do noticeably better than a year ago, and how do you know?"]),n("chi-thay-mot-phan",3,["Nhìn ra cái mạng xã hội cắt đi trước khi cho mình xem.","See what social media edits out before showing you anything."],[["Người ta đăng phần đã chọn lọc, không đăng phần còn lại.","People post the edited part, not the rest."],["Một tấm đẹp nhất trong hai trăm tấm. Một kết quả sau ba lần hỏng không kể.","The best of two hundred photos. The result after three failures nobody mentions."],["Nên khi so, mình đang lấy hậu trường của mình đọ với sân khấu của người khác. Cuộc so ấy thua từ trước khi bắt đầu — và nó không nói gì thật về ai cả, kể cả về người đăng.","So in comparing, you set your backstage against their stage. That contest is lost before it begins — and it says nothing true about anyone, including the person who posted."],['Điều này không phải lỗi của ai. Ai cũng đăng phần đẹp, kể cả mình. Nhưng biết cái máy đang làm gì thì lúc thấy nặng nề, mình gọi tên được: "đây là hậu trường đọ sân khấu", chứ không phải "mình kém".',"Nobody is at fault here. Everyone posts the good part, you included. But knowing what the machine does means that when it starts to weigh on you, you can name it: this is backstage against stage, not I am not good enough."]],["Cái được cho xem không bao giờ là mẫu ngẫu nhiên. Nó là mẫu đã được chọn, và chọn theo hướng đẹp lên.","What you are shown is never a random sample. It is a selected one, and selected in the flattering direction."],["Bẫy: nghĩ mình đủ tỉnh nên không bị ảnh hưởng. Biết trước không làm mất tác dụng — chỉ cho mình gọi được tên nó lúc nó đang xảy ra.","The trap: believing you are too clever to be affected. Knowing does not switch the effect off — it only lets you name it while it is happening."],["Hỏi bố mẹ: hồi chưa có mạng, người ta so mình với ai?","Ask at home: before there was an internet, who did people compare themselves with?"]),n("keo-chu-y",3,["Nhìn ra thứ nào cố ý không có chỗ dừng.","Spot the things deliberately built with no ending."],[["Cuốn sách có trang cuối. Bài hát có nốt cuối.","A book has a last page. A song has a last note."],['Chúng tự nói cho mình biết là hết. Cái "hết" ấy là một món quà.',"They tell you themselves that they are over. That ending is a gift."],["Cuộn vô tận và tự chạy thì cố ý không có chỗ hết. Không phải vì người làm ra chúng xấu, mà vì họ được trả tiền theo số phút mình ở lại. Cái máy đang làm đúng việc nó được thiết kế để làm.","Endless scroll and autoplay are built with no ending on purpose. Not because the makers are wicked, but because they are paid by the minute you stay. The machine is doing exactly the job it was designed for."],['Biết được điều ấy đổi hẳn câu hỏi. Không còn là "sao mình yếu thế", mà là "mình đang chơi với một cái máy được nhiều người rất giỏi thiết kế để mình không dừng được". Và thế thì cách chữa cũng đổi: đặt chỗ hết từ bên ngoài — hẹn giờ, để máy ở phòng khác, tắt tự chạy. Không cần thắng cái máy, chỉ cần thêm cái trang cuối vào cho nó.','Knowing that changes the question. Not "why am I so weak" but "I am up against something a great many clever people built so that I would not stop". And that changes the remedy: supply the ending from outside — a timer, the device in another room, autoplay switched off. You need not beat the machine, only give it a last page.']],["Ý chí là thứ có hạn và cạn dần trong ngày. Thiết kế thì không mệt. Nên đấu bằng ý chí thì thua; đổi thiết kế thì thắng.","Willpower is finite and drains through the day. Design never tires. Fight it with willpower and you lose; change the design and you win."],["Bẫy: nghĩ dừng được hay không là chuyện tính cách. Người lớn cũng không dừng nổi — và họ có nhiều năm luyện tập hơn con.","The trap: treating stopping as a matter of character. Adults cannot stop either — and they have had far more years of practice than you."],["Hỏi bố mẹ: nhà mình có luật gì về giờ dùng điện thoại không, và luật ấy áp cho ai?","Ask at home: do we have any rule about screen time, and who does it apply to?"]),n("bi-ngat-thi-mat-cong",3,["Biết việc nào ngắt được, việc nào ngắt là mất cả quãng khởi động.","Know which work can be interrupted and which loses its whole warm-up."],[["Quét nhà thì ngắt lúc nào cũng được. Quét tiếp là xong.","Sweeping can be broken off anywhere. Pick up the broom and carry on."],["Giải một bài toán thì không. Bị ngắt là rơi hết, phải dựng lại từ đầu.","Solving a problem cannot. An interruption drops everything and you rebuild from the start."],["Vì việc ấy phải giữ nhiều thứ cùng lúc trong đầu — đề bài, chỗ đang làm dở, hai ba hướng đã thử. Cả cái giàn ấy cần vài phút mới dựng xong, và nó đổ trong một giây.","Because that work holds several things at once — the question, where you are, two or three routes already tried. That scaffold takes minutes to build and falls in a second."],['Nên "chỉ xem một cái thôi" giữa lúc làm bài không tốn một phút. Nó tốn một phút cộng với cả quãng khởi động — thường là năm tới mười lăm phút nữa. Đó không phải lời mắng, đó là một phép cộng, và ai cũng làm được phép cộng ấy cho chính mình.','So "just one quick look" mid-problem does not cost a minute. It costs a minute plus the whole warm-up again — usually another five to fifteen. That is not a scolding, it is an addition, and anyone can do that sum for themselves.']],["Việc nào cần nhiều thứ trong đầu cùng lúc thì có chi phí khởi động. Chi phí ấy phải trả lại từ đầu sau mỗi lần gián đoạn.","Work that needs several things in mind at once carries a start-up cost. That cost is paid again in full after every interruption."],["Bẫy: nghĩ làm nhiều việc cùng lúc là làm được nhiều hơn. Với việc cần nghĩ, nó chỉ là chuyển qua chuyển lại và trả phí khởi động mỗi lần chuyển.","The trap: believing multitasking gets more done. For thinking work it is only switching back and forth, paying the start-up cost at every switch."],["Hỏi bố mẹ: lúc bố mẹ làm việc cần tập trung, ai làm phiền thì bố mẹ làm gì?","Ask at home: when you need to concentrate at work, what do you do about interruptions?"]),n("tra-tien-cho-gi",3,["Bóc một cái giá ra thành từng phần và biết phần nào mang về nhà được.","Take a price apart and know which parts come home with you."],[["Giá một món hàng gồm chi phí thật cộng phần lời.","A price is real cost plus margin."],["Chi phí thật là vật liệu, công làm, chở hàng, bảo hành. Bốn thứ ấy mang về nhà dùng được.","The real cost is materials, labour, shipping and warranty. Those four come home with you."],["Còn cái hộp đẹp, cái logo, tiền thuê người nổi tiếng — mình trả để chính mình được nghe quảng cáo, rồi bóc hộp ra vứt đi.","The pretty box, the logo, the fee for a famous face — you pay so that you can be advertised to, then open the box and throw it away."],["Nhưng thương hiệu không hẳn là lừa. Nó đáng tiền khi nó bảo đảm chất lượng đều tay và chịu trách nhiệm lúc hỏng — mua một cái mũ bảo hiểm không tên tuổi rẻ hơn thật, và không ai đứng ra chịu nếu nó vỡ. Việc phải làm không phải là ghét thương hiệu, mà là hỏi cho ra: cái tên này đang bảo đảm điều gì, hay chỉ đang bán cái cảm giác?","Yet a brand is not automatically a trick. It earns its money when it guarantees consistency and answers for failure — an unbranded helmet is genuinely cheaper, and nobody stands behind it when it cracks. The task is not to despise brands but to ask what exactly the name is guaranteeing, or whether it is selling a feeling."]],["Tiền chảy về phía nào thì phía đó lớn lên. Trả cho chất lượng thì có thêm hàng tốt; trả cho quảng cáo thì có thêm quảng cáo.","Whatever money flows towards, grows. Pay for quality and more quality gets made; pay for advertising and more advertising gets made."],["Bẫy: nghĩ đắt là tốt, hoặc rẻ là khôn. Cả hai đều là lười — cách duy nhất là bóc giá ra xem từng phần.","The trap: assuming dear means good, or that cheap means clever. Both are shortcuts — the only way is to take the price apart."],["Hỏi bố mẹ: có món nào nhà mình mua loại đắt vì đáng, và món nào mua loại rẻ nhất cũng được?","Ask at home: what do we buy the expensive version of because it is worth it, and what do we buy the cheapest of?"]),n("tinh-theo-don-vi",3,["So được hai món khác cỡ bằng cách chia ra một đơn vị chung.","Compare unlike sizes by dividing down to a common unit."],[["Gói 400 nghìn và gói 250 nghìn: cái nào rẻ hơn?","A pack at 400,000 and a pack at 250,000: which is cheaper?"],["Không trả lời được, vì hai gói khác cỡ. Phải chia ra mỗi cân, mỗi cái, mỗi lần dùng.","Unanswerable, because the packs are different sizes. Divide down: per kilo, per item, per use."],["Đôi giày 900 nghìn đi được ba năm là 25 nghìn một tháng. Đôi 300 nghìn đi bốn tháng là 75 nghìn một tháng. Đôi đắt rẻ hơn ba lần — mà trên kệ thì nó là đôi đắt gấp ba.","Shoes at 900,000 lasting three years cost 25,000 a month. Shoes at 300,000 lasting four months cost 75,000 a month. The dear pair is three times cheaper — while on the shelf it is the pair that costs three times more."],["Phép chia ấy là toàn bộ bí quyết, và nó dùng được cho gần như mọi thứ: điện thoại, xe, sách, khoá học. Chỉ có một điều kiện — phải đoán được nó dùng được bao lâu, và chỗ ấy thì mình có thể đoán sai. Nên tính theo đơn vị không cho câu trả lời chắc chắn; nó chỉ cho một câu hỏi đúng hơn.","That division is the whole trick, and it works for nearly everything: phones, bikes, books, courses. There is one condition — you must estimate how long it will last, and there you can be wrong. So unit pricing does not give a certain answer; it gives a better question."]],["Tổng tiền là con số về cái ví; giá theo đơn vị là con số về món hàng. Chỉ số thứ hai so được giữa hai món khác nhau.","A total is a fact about your purse; a unit price is a fact about the goods. Only the second can be compared between two different things."],["Bẫy: chia theo đơn vị rồi quên mất là mình vẫn phải có đủ 900 nghìn ngay hôm nay. Rẻ hơn theo tháng mà không đủ tiền mặt thì vẫn là mua không được.","The trap: doing the division and forgetting you still need the 900,000 today. Cheaper per month is no help if the cash is not there."],["Hỏi bố mẹ: món đồ nào trong nhà dùng lâu nhất, và hồi mua nó có đắt không?","Ask at home: what object here has lasted longest, and was it expensive when we bought it?"]),n("lai-nhap-goc",4,["Tính được số tiền sau vài năm khi lãi được nhập vào gốc.","Work out what money becomes over years when interest joins the pot."],[["Gửi 100 đồng, lãi 10% một năm. Năm sau có 110.","Put in 100 at 10% a year. After a year, 110."],["Năm thứ hai, lãi tính trên 110 chứ không phải trên 100 nữa. Nên được 121, không phải 120.","In year two the interest is charged on 110, not on 100. So 121, not 120."],["Rồi 133, rồi 146. Chênh lệch năm đầu nhỏ tới mức không ai để ý — một đồng. Nhưng sau hai mươi năm thì 100 thành 673, chứ không phải 300.","Then 133, then 146. The gap in year one is too small to notice — one unit. But after twenty years, 100 has become 673, not 300."],["Bộ não người dở đúng ở chỗ này: mình hình dung được cái gì tăng đều, chứ không hình dung được cái gì tăng nhân lên. Nên hầu như ai cũng đánh giá thấp khoản để dành dài hạn — và cũng đánh giá thấp món nợ dài hạn, vì luật này chạy y hệt về phía nợ. Nợ thẻ tín dụng lãi 2% một THÁNG nghe nhỏ, mà một năm thành hơn 26%, chứ không phải 24%.","The human brain is bad at exactly this: we can picture steady growth, not multiplying growth. So nearly everyone underestimates long-term saving — and equally underestimates long-term debt, because the law runs identically in that direction. Credit-card interest of 2% a MONTH sounds small, and comes to over 26% a year, not 24%."],["Có một mẹo cũ đáng nhớ, gọi là luật 72: lấy 72 chia cho lãi suất phần trăm thì ra số năm để tiền gấp đôi. Lãi 6% thì mười hai năm; lãi 9% thì tám năm; lãi 12% thì sáu năm. Không chính xác tuyệt đối, nhưng đủ để nhẩm trong đầu lúc ai đó đang mời mình một con số và đang giục mình quyết ngay. Và mẹo ấy dùng được cả hai chiều: một món nợ lãi 18% một năm thì cứ bốn năm là số tiền phải trả gấp đôi lên, dù mình không vay thêm đồng nào. Biết chia được 72 cho một con số là biết đủ để tự hỏi lại một lời mời.","There is an old trick worth keeping, the rule of 72: divide 72 by the interest rate and you get the years to double. At 6%, twelve years; at 9%, eight; at 12%, six. Not exact, but enough to run in your head while somebody is offering you a number and hurrying you to decide. And it works both ways: a debt at 18% a year doubles what you owe every four years, even if you never borrow another coin. Being able to divide 72 by something is enough to make you question an offer."]],["Khi phần tăng thêm cũng được cộng vào cái đang sinh ra nó, thì tốc độ tăng tự nó lớn dần. Đó là lý do đường cong đi lên chứ không đi thẳng.","When the growth is added back into whatever is producing it, the rate of growth itself keeps rising. That is why the line curves instead of running straight."],["Bẫy: nghĩ thời gian là phần phụ, tiền mới là phần chính. Ngược lại — với lãi kép, số năm mới là biến mạnh nhất. Bắt đầu sớm hơn năm năm thường thắng góp gấp đôi mỗi tháng.","The trap: treating time as the minor factor and the amount as the main one. The reverse — with compounding, years are the strongest variable. Starting five years earlier usually beats doubling the monthly amount."],["Hỏi bố mẹ: nhà mình có khoản nào để dành dài hạn không, và bắt đầu từ bao giờ?","Ask at home: do we have any long-term savings, and when did they start?"]),n("dau-hieu-lua",4,["Nhận ra ba dấu hiệu chung của gần như mọi trò lừa tiền.","Recognise the three signs common to nearly every money scam."],[["Dấu hiệu thứ nhất: hứa lãi cao mà bảo là không có rủi ro.","Sign one: a high return promised with no risk."],["Đây là lời nói dối cổ nhất trên đời. Nếu có thật, người nói đã tự làm chứ không đi rủ mình.","This is the oldest lie there is. If it were true the speaker would be doing it, not recruiting you."],['Dấu hiệu thứ hai: gấp lên, chỉ hôm nay, sắp hết chỗ. Chữ "gấp" tồn tại để mình không kịp hỏi ai khác. Người bán hàng thật thì không sợ mình về hỏi bố mẹ đã.','Sign two: hurry, today only, nearly full. The word "hurry" exists so that you cannot ask anyone else. An honest seller is not afraid of you going home to ask a parent first.'],["Dấu hiệu thứ ba: giữ bí mật, đừng kể với ai. Chữ ấy tồn tại để mình không kịp kể cho đúng người sẽ can. Ba dấu hiệu này không nói về món hàng — chúng nói về cách người kia đang cắt mình khỏi những người có thể kiểm tra giúp.","Sign three: keep it quiet, do not tell anyone. That exists so you cannot tell the one person who would stop you. None of the three is about the product — all three describe someone cutting you off from anyone who could check."],['Cách chống thì đơn giản tới mức buồn cười: chờ một đêm, và kể cho một người. Trò lừa nào cũng hỏng trước hai việc ấy, và đó chính là lý do mọi trò lừa đều cố ngăn đúng hai việc ấy. Nên khi thấy ai đó khó chịu vì mình muốn chờ, hay muốn hỏi thêm một người nữa, thì bản thân phản ứng khó chịu ấy đã là câu trả lời — người bán hàng tử tế sẽ nói "cứ về hỏi đi rồi quay lại". Không cần biết món hàng là gì mới nhận ra được điều đó, và đó là chỗ hay nhất của ba dấu hiệu này.','The defence is almost comically simple: sleep on it, and tell one person. Every scam fails against those two, which is exactly why every scam works to prevent those two. So when someone is annoyed that you want to wait, or to ask one more person, the annoyance is itself the answer — an honest seller says "go and ask, then come back". You need not understand the product to notice that, and it is the best thing about these three signs.']],["Lợi nhuận cao là phần thưởng cho việc chịu rủi ro. Bỏ rủi ro đi mà giữ lợi nhuận thì không phải một cơ hội hiếm, mà là một câu vô nghĩa.","High return is the payment for bearing risk. Remove the risk and keep the return and you do not have a rare opportunity, you have a sentence that means nothing."],["Bẫy: tưởng chỉ người ngu mới bị lừa. Người bị lừa nhiều nhất thường là người tự tin nhất — vì họ không hỏi ai.","The trap: assuming only fools are taken in. The most frequently defrauded tend to be the most confident — because they ask nobody."],["Hỏi bố mẹ: có ai trong nhà từng suýt bị lừa tiền không, và cái gì đã cứu?","Ask at home: has anyone here nearly been defrauded, and what saved them?"]),n("bot-rui-ro",3,["Kể được ba cách làm cho rủi ro nhỏ đi mà không cần né tránh nó.","Name three ways to shrink a risk without avoiding it."],[["Không ai bỏ hết trứng vào một giỏ.","Nobody puts every egg in one basket."],["Không phải vì sợ, mà vì một giỏ rơi thì mất tất cả; năm giỏ rơi một thì còn bốn.","Not out of fear, but because one basket dropped loses everything, while one of five leaves four."],["Cách thứ hai là khoản để dành. Nó không sinh lời, nên nghe như tiền chết. Nhưng nó mua cho mình một thứ đắt hơn lãi: quyền nói không với một lời mời tồi, và quyền chờ.","The second way is a cushion of savings. It earns nothing, so it sounds like dead money. It buys something dearer than interest: the right to say no to a bad offer, and the right to wait."],["Cách thứ ba là học được một nghề. Tiền thì mất được, đồ thì hỏng được, nhưng cái mình làm được thì không ai lấy đi, và càng dùng càng giỏi. Ba cách này không xoá rủi ro — không có cách nào xoá được. Chúng chỉ làm cho một lần xui không thành một lần mất hết.","The third is learning a trade. Money can be lost and things can break, but what you can do cannot be taken, and improves with use. None of the three removes risk — nothing does. They stop one piece of bad luck from becoming total loss."]],["Rủi ro không đo bằng khả năng xui, mà bằng hậu quả nếu xui. Chia nhỏ ra thì khả năng xui không đổi, còn hậu quả thì nhỏ hẳn.","Risk is not measured by the chance of bad luck but by what bad luck costs. Spreading it leaves the chance unchanged and cuts the cost right down."],["Bẫy: nghĩ tránh hết rủi ro là an toàn. Không làm gì cũng là một lựa chọn có rủi ro — chỉ là rủi ro của nó đến chậm và không ai nhìn thấy.","The trap: treating total avoidance as safety. Doing nothing is also a choice with a risk — its risk simply arrives slowly and nobody sees it happen."],["Hỏi bố mẹ: nhà mình có việc gì mà nếu hỏng thì sẽ rất khó không, và có cách nào chia nhỏ nó ra không?","Ask at home: is there anything here that would be very hard if it failed, and could it be spread out?"])],o=[n("nhan-voi-0",2,["Nói được vì sao nhân với 0 luôn ra 0, còn cộng với 0 thì không đổi gì.","Say why multiplying by zero always gives zero while adding zero changes nothing."],[["Nhân là lấy một số bấy nhiêu lần.","Multiplying is taking a number that many times."],["Vậy 7×0 là lấy số 7 đúng không lần nào. Không lần nào thì trong tay chẳng có gì, nên kết quả là 0.","So 7×0 means taking the seven no times at all. No times means nothing in your hands, so the answer is zero."],['Cộng thì khác hẳn: 7+0 là có sẵn bảy rồi thêm vào không cái nữa, nên vẫn là bảy. Cùng một con số 0, mà một phép thì nó xoá sạch, một phép thì nó chẳng động tới gì. Khác nhau ở chỗ nhân hỏi "mấy lần", còn cộng hỏi "thêm bao nhiêu" — hai câu hỏi khác nhau thì số 0 trả lời khác nhau.',"Adding is a different question: 7+0 means you already hold seven and add nothing more, so seven it stays. The same zero wipes one sum out and leaves the other untouched. The difference is that multiplying asks how many lots, and adding asks how much more — two questions, so zero answers them two ways."]],["Số 0 không có một tính cách cố định. Nó làm gì là do phép tính đang hỏi nó cái gì, và đó là điều đúng với mọi con số.","Zero has no fixed personality. What it does depends on what the operation is asking of it, and that is true of every number."],['Bẫy: học thuộc "gặp số 0 thì ra 0" rồi áp cả vào phép cộng, viết 7+0=0. Rất nhiều lỗi số học của trẻ không phải quên bảng cửu chương mà là mang luật của phép này sang phép kia.','The trap: memorising "a zero makes it zero" and carrying it into addition, writing 7+0=0. A great many arithmetic slips are not forgotten tables but a rule carried from one operation into another where it does not live.'],["Hỏi ở nhà: nếu một tuần nhà mình đi chợ 0 lần thì tiền chợ tuần đó là bao nhiêu?","Ask at home: if the family went to market zero times this week, what did market cost?"]),n("phep-nguoc-nhau",2,["Dùng một dòng cửu chương đã thuộc để trả lời bốn câu hỏi khác nhau.","Use one line of the times table you already know to answer four different questions."],[["6×4 bằng 24. Đó là một điều biết.","Six fours are twenty-four. That is one thing known."],["Nhưng nó cũng cho luôn 4×6 bằng 24, 24 chia 6 bằng 4, và 24 chia 4 bằng 6.","But it also hands you 4×6, and 24 shared into six, and 24 shared into four, all at once."],["Chia là phép cởi ngược của nhân, đúng như trừ cởi ngược cho cộng. Nên bảng cửu chương ngắn hơn vẻ ngoài của nó rất nhiều: ai thấy nó dài là vì đang học cùng một điều tới bốn lần dưới bốn cái tên. Nhận ra chỗ ngược nhau ấy thì một buổi học thuộc biến thành bốn buổi.","Division undoes multiplication exactly as subtraction undoes addition. So the times table is far shorter than it looks: anyone who finds it long is learning the same fact four times under four names. Seeing where the operations reverse turns one afternoon of learning into four."]],["Mỗi phép tính đều có một phép cởi nó ra. Biết luật ấy thì không phải nhớ thêm, chỉ phải nhìn lại cái đã nhớ theo chiều ngược.","Every operation has another that undoes it. Knowing this adds nothing to memorise; it only asks you to read what you already hold backwards."],["Bẫy: tưởng phép chia là một môn mới phải học lại từ đầu, nên học sinh thuộc làu bảng nhân mà đứng hình trước 24 chia 6. Cái thiếu không phải trí nhớ, cái thiếu là chưa ai chỉ ra hai phép ấy là một.","The trap: treating division as a fresh subject to learn from scratch, so a child recites the tables fluently and then freezes at 24 divided by 6. What is missing is not memory but the fact that nobody pointed out the two are one."],["Hỏi ở nhà: nhà mình có 24 cái bát, xếp mỗi chồng 6 cái thì được mấy chồng?","Ask at home: with twenty-four bowls stacked six to a pile, how many piles?"]),n("thu-tu-phep-tinh",3,["Đọc được một dãy phép tính theo đúng một cách, và nói được vì sao chỉ một.","Read a line of arithmetic exactly one way, and say why only one is allowed."],[["2+3×4 bằng bao nhiêu? Có người nói 20, có người nói 14.","What is 2+3×4? Some say twenty, some say fourteen."],["Cả hai đều tính đúng từng phép một. Họ chỉ khác nhau ở chỗ làm cái nào trước.","Both have done every single sum correctly. They differ only in which part they did first."],["Vì thế người ta phải thoả thuận một luật chung: nhân chia làm trước, cộng trừ làm sau. Luật này không do trời sinh, không có gì trong bản chất con số bắt phải thế — nó sinh ra để một dãy ký hiệu chỉ còn đúng một cách đọc, y như luật đi bên phải đường. Muốn đổi thứ tự thì đặt dấu ngoặc, và đó là toàn bộ công dụng của dấu ngoặc.","So a common rule had to be agreed: multiply and divide first, add and subtract after. Nature did not hand this down and nothing in the numbers themselves demands it — it exists so that one string of symbols has exactly one reading, like the rule about which side of the road to drive on. To change the order you write brackets, and that is the whole purpose of brackets."]],["Toán học cần luật thoả thuận ở đúng những chỗ mà sự thật không tự quyết được. Chỗ nào cũng đúng như nhau thì phải chọn một, rồi cả thế giới chọn theo.","Mathematics needs agreed conventions exactly where truth cannot decide. Where several readings are equally sound, one must be chosen, and then everybody chooses the same one."],['Bẫy: nghĩ rằng luật này là một sự thật của con số nên "hiển nhiên đúng". Nó không hiển nhiên chút nào — máy tính bỏ túi đời cũ làm từ trái sang phải và ra 20, và nó không hỏng, nó chỉ theo một thoả thuận khác.',"The trap: believing the rule is a truth about numbers and therefore obvious. It is not obvious at all — old pocket calculators worked left to right and answered twenty, and they were not broken, merely following a different agreement."],["Hỏi ở nhà: mua 2 quả trứng rồi mua thêm 3 vỉ, mỗi vỉ 4 quả — cả thảy mấy quả?","Ask at home: two loose eggs plus three trays of four — how many eggs in all?"]),n("so-lon-tron",2,["Làm tròn một số về hàng nghìn và nói được mình vừa bỏ đi cái gì.","Round a number to the nearest thousand and say what you just threw away."],[["Làm tròn là cố ý bỏ bớt độ chính xác cho dễ nghĩ.","Rounding is deliberately throwing away precision to make thinking easier."],["Quy ước rất gọn: từ 5 trở lên thì lên, dưới 5 thì xuống. Nên 1049 về 1000, còn 1500 lên 2000.","The convention is short: five and over goes up, under five goes down. So 1049 becomes 1000 while 1500 becomes 2000."],["Cái mất đi khi làm tròn không phải là rác. Nó là thông tin thật, và bỏ nó đi là một lựa chọn có giá: làm tròn tiền chợ từng món về nghìn thì cuối buổi có thể lệch cả chục nghìn. Nhưng đổi lại, số tròn nhẩm được trong đầu, mà nhẩm được thì phát hiện ra sai sót ngay tại quầy, chứ không phải về nhà mới biết.","What rounding removes is not rubbish. It is real information, and dropping it is a choice with a price: round every item at the market to the nearest thousand and the total can be out by ten thousand. In exchange, round numbers can be held in the head, and a number held in the head catches a mistake at the counter instead of at home."]],["Chính xác và dễ nghĩ là hai thứ đánh đổi nhau. Không có con số nào vừa đủ chính xác vừa đủ gọn cho mọi việc, nên phải chọn theo việc đang làm.","Precision and ease of thought trade against each other. No single number is both exact enough and short enough for every purpose, so you choose by the job in hand."],['Bẫy: làm tròn từng số rồi mới cộng, và tưởng kết quả vẫn "gần đúng". Cộng hai mươi số đã làm tròn thì các sai số không triệt tiêu nhau mà có thể dồn về một phía, và tổng lệch xa hơn nhiều so với người ta tưởng.',"The trap: rounding every number first and then adding, believing the total stays roughly right. Add twenty rounded numbers and the errors need not cancel; they can all lean the same way, and the total drifts much further than anyone expects."],["Hỏi ở nhà: tiền chợ hôm nay, làm tròn về nghìn thì hết khoảng bao nhiêu?","Ask at home: rounded to the nearest thousand, what did today’s shopping cost?"]),n("uoc-luong-nhanh",3,["Ước lượng trước khi tính, và dùng chỗ ước lượng để bắt lỗi của chính mình.","Estimate before you calculate, and use the estimate to catch your own mistakes."],[["19×21 là bao nhiêu? Đừng tính vội, hãy đoán trước.","What is 19×21? Do not calculate yet — guess first."],["19 gần 20, 21 cũng gần 20. Mà 20×20 là 400. Vậy đáp án phải quanh quẩn 400.","Nineteen is near twenty and so is twenty-one, and twenty twenties are four hundred. So the answer sits somewhere near four hundred."],["Đáp án thật là 399. Nhưng cái đáng giá không phải con số ấy, mà là: từ giờ nếu tính ra 4000 hay 40 thì biết ngay mình lạc một chữ số, không cần ai chấm bài. Người làm nghề tính toán giỏi không phải người không bao giờ sai — họ sai như mọi người, nhưng họ có một con số trong đầu để đối chiếu, nên cái sai không đi xa được quá một dòng.","The true answer is 399. But the valuable part is not that number: from now on, an answer of 4000 or of 40 tells you instantly that a digit went astray, with nobody marking your work. People who are good with numbers are not people who never slip — they slip like everyone, but they carry a rough figure to compare against, so a slip never travels more than one line."]],["Ước lượng không phải phiên bản lười của phép tính. Nó là cái lưới an toàn đặt dưới phép tính, và nó phải có mặt TRƯỚC, chứ đặt sau thì đã muộn.","Estimating is not a lazy version of calculating. It is the safety net under the calculation, and it has to be strung BEFORE, not after, when it is already too late."],["Bẫy: có máy tính rồi thì thôi khỏi ước lượng. Nhưng máy tính không bao giờ báo lỗi khi mình bấm nhầm một phím — nó trả lời rất tự tin một con số sai, và người duy nhất phát hiện ra được là người đã có sẵn một con số ước lượng trong đầu.","The trap: having a calculator, so why estimate. But a calculator never warns you about a mistyped key — it answers a wrong sum with complete confidence, and the only person who can catch it is the one who already had a rough figure in mind."],["Hỏi ở nhà: một tháng nhà mình tiêu khoảng bao nhiêu tiền chợ, tính tròn thôi?","Ask at home: roughly, in round numbers, what does a month of food cost here?"]),n("phan-so-lon-hon",3,["So hai phân số khác mẫu mà không cần quy đồng.","Compare two fractions with different denominators without finding a common one."],[["3/4 và 2/3, cái nào lớn hơn?","Which is larger, three quarters or two thirds?"],["Cách quen là quy đồng: 9/12 và 8/12. Nhưng có một cách nhanh hơn: nhìn vào chỗ THIẾU.","The usual way is a common denominator: nine twelfths against eight twelfths. But there is a quicker way: look at what is MISSING."],["3/4 thiếu đúng 1/4 nữa là đầy. 2/3 thiếu 1/3. Mà một phần tư thì nhỏ hơn một phần ba — chia cái bánh làm bốn thì mỗi miếng bé hơn chia làm ba. Thiếu ít hơn nghĩa là gần đầy hơn, nên 3/4 lớn hơn. Mẹo này chỉ chạy khi cả hai phân số cùng thiếu đúng một phần, nhưng đó lại là trường hợp gặp nhiều nhất.","Three quarters is one quarter short of whole; two thirds is one third short. And a quarter is smaller than a third — cut a cake into four and each piece is smaller than cutting it into three. Missing less means nearer full, so three quarters wins. The trick works only when both fractions are one piece short of whole, but that is much the commonest case."]],['Một câu hỏi thường có nhiều đường tới đáp án, và đường ngắn nhất hay là đường hỏi ngược lại: không hỏi "có bao nhiêu" mà hỏi "thiếu bao nhiêu".',"A question usually has several roads to its answer, and the shortest is often the one that turns it round: not how much is there, but how much is absent."],["Bẫy: mẫu số to hơn thì phân số to hơn. Nhìn 1/8 và 1/3 mà chọn 1/8 vì tám lớn hơn ba. Mẫu số càng lớn thì miếng càng bé, vì cái bánh vẫn bằng ấy mà phải chia cho nhiều phần hơn.","The trap: a bigger bottom number means a bigger fraction, so an eighth beats a third because eight beats three. A bigger denominator makes a smaller piece, because the same cake is being shared among more parts."],["Hỏi ở nhà: chia cái bánh cho 3 người hay cho 4 người thì miếng của con to hơn?","Ask at home: is your slice bigger when the cake is cut for three, or for four?"]),n("bang-9",1,["Kiểm tra một phép nhân 9 mà không cần tính lại.","Check a nine times sum without doing it again."],[["9×3 là 27. Cộng hai chữ số: 2+7 bằng 9.","Nine threes are twenty-seven. Add the digits: two and seven make nine."],["9×7 là 63, mà 6+3 cũng bằng 9. Bảng 9 nào cũng thế, thử cả bảng mà xem.","Nine sevens are sixty-three, and six and three make nine as well. Every line of the nine table does this."],["Đây không phải phép màu. Số 9 kém 10 đúng một đơn vị, nên mỗi lần nhân thêm một lần 9 là thêm một chục rồi bớt một đơn vị — chữ số hàng chục lên một, chữ số hàng đơn vị xuống một, và tổng hai chữ số đứng nguyên. Biết vì sao thì cái mẹo không còn là mẹo nữa, nó thành một thứ mình tự dựng lại được.","This is not magic. Nine is exactly one short of ten, so every extra nine adds a ten and takes away a unit — the tens digit climbs by one, the units digit drops by one, and the two together stay put. Once you know why, the trick stops being a trick and becomes something you could rebuild yourself."]],["Mọi mẹo tính nhanh đều là một luật thật bị viết tắt. Tìm ra luật đằng sau thì không phải nhớ mẹo nữa, và mẹo hỏng ở đâu cũng biết.","Every quick trick is a real law written in shorthand. Find the law behind it and there is no trick to remember, and you can see where it stops working."],["Bẫy: dùng mẹo tổng chữ số làm bằng chứng là phép tính đúng. Nó chỉ bắt được một số lỗi thôi: 9×3 mà tính nhầm thành 72 thì tổng chữ số vẫn là 9, mẹo không kêu gì cả.","The trap: taking the digit-sum as proof the sum is right. It catches only some errors: mistype nine threes as seventy-two and the digits still add to nine, and the trick says nothing at all."],["Hỏi ở nhà: 9 nhân 6 là bao nhiêu, và hai chữ số của nó cộng lại bằng mấy?","Ask at home: what are nine sixes, and what do the two digits add up to?"]),n("goc-vuong",2,["Nói được 90 độ từ đâu ra, và vì sao vòng tròn lại là 360 độ.","Say where ninety degrees comes from, and why a circle has three hundred and sixty."],[["Góc vuông là 90 độ, đúng một phần tư vòng tròn.","A right angle is ninety degrees, exactly a quarter of a circle."],["Vòng tròn có 360 độ. Con số ấy không phải trời cho — người Lưỡng Hà chọn nó cách đây bốn nghìn năm.","A circle has three hundred and sixty degrees. That figure is not from nature — Mesopotamia chose it four thousand years ago."],["Họ đếm theo hệ 60 chứ không theo hệ 10, và 360 chia hết cho rất nhiều số: 2, 3, 4, 5, 6, 8, 9, 10, 12. Chia vòng tròn kiểu nào cũng ra số nguyên, không phải dùng phân số. Một quyết định thực dụng của mấy người đo ruộng bốn nghìn năm trước còn nằm nguyên trong cái thước đo độ trong cặp con hôm nay.","They counted in sixties rather than tens, and 360 divides evenly by a great many numbers: 2, 3, 4, 5, 6, 8, 9, 10, 12. However you cut the circle you land on whole numbers instead of fractions. A practical decision made by land surveyors four thousand years ago sits intact in the protractor in your bag today."]],['Đơn vị đo không phải sự thật của thế giới, chúng là công cụ do người làm ra, và cái nào tiện thì sống lâu. Hỏi "vì sao lại là số này" thì gần như bao giờ cũng ra một câu chuyện có thật.',"Units are not truths about the world; they are tools people made, and the convenient ones outlive the rest. Asking why this number rather than another nearly always uncovers a real story."],["Bẫy: nghĩ 360 là con số tự nhiên của vòng tròn. Không hề — trong toán cao hơn người ta đo góc bằng radian, và một vòng tròn khi ấy là 2π, một con số còn không phải số nguyên.","The trap: assuming 360 is the circle’s own natural number. It is not — higher mathematics measures angles in radians, where a full circle is two pi, which is not even a whole number."],["Hỏi ở nhà: trong nhà mình có bao nhiêu góc vuông, thử đếm một phòng xem?","Ask at home: how many right angles are in this room — try counting them?"]),n("tam-giac-dung-duoc",3,["Nhìn ba số là biết dựng được tam giác hay không, không cần vẽ.","Look at three numbers and know whether they make a triangle, without drawing."],[["Cho ba que dài 1, 2 và 9. Ghép lại thành tam giác được không?","Three sticks: one, two and nine. Can they make a triangle?"],["Không. Hai que ngắn cộng lại mới được 3, không với tới hai đầu của que 9.","No. The two short sticks together reach only three, which cannot span the ends of the nine."],["Luật đầy đủ là: hai cạnh ngắn cộng lại phải LỚN HƠN cạnh dài. Bằng đúng cũng không được — lúc ấy ba que nằm bẹp thành một đường thẳng, không có ruột nào bên trong. Điều hay của luật này là con tự kiểm được bằng ba que tăm trong năm giây, không phải tin lời ai. Trong toán, thứ mình tự dựng lại được thì mới thật là của mình.","The full rule is: the two shorter sides added must be LONGER than the longest. Exactly equal will not do either — then the three sticks lie flat in a line with no inside at all. The good thing about this rule is that three toothpicks settle it in five seconds, with nobody’s word to take. In mathematics, what you can rebuild yourself is what you actually own."]],["Một luật hình học tốt bao giờ cũng kiểm được bằng vật thật. Nếu một luật chỉ đúng trên giấy mà thử không ra, thì hoặc mình hiểu sai luật, hoặc luật ấy sai.","A good geometric law can always be tested with real objects. If a law holds only on paper and fails in the hand, either you have misread it or it is wrong."],["Bẫy: chỉ so cạnh dài nhất với một cạnh ngắn. Nhìn 2, 3 và 4 rồi bảo không được vì 2 nhỏ hơn 4. Phải cộng CẢ HAI cạnh ngắn lại: 2+3 bằng 5, lớn hơn 4, nên dựng được thật.","The trap: comparing the longest side with only one short side. Seeing 2, 3 and 4 and refusing because two is less than four. You must add BOTH short sides: two and three make five, which beats four, so it really does build."],["Hỏi ở nhà: tìm ba cái que trong bếp, thử xem bộ nào ghép thành tam giác được?","Ask at home: find three sticks in the kitchen — which sets make a triangle?"]),n("doi-don-vi",2,["Đổi mét sang xen-ti-mét mà không phải học thuộc bảng nào.","Convert metres to centimetres without memorising any table."],[["1 mét bằng 100 xăng-ti-mét, và bằng 1000 mi-li-mét.","One metre is a hundred centimetres, and a thousand millimetres."],["Cả hệ mét chạy bằng gấp mười: mi-li, xăng-ti, đề-xi, mét, rồi đề-ca, héc-tô, ki-lô.","The whole metric system runs on tens: milli, centi, deci, metre, then deca, hecto, kilo."],["Nên đổi đơn vị chỉ là dời dấu phẩy đi vài chỗ, không phải nhớ gì thêm. Hệ đo của Anh thì 12 inch một foot, 3 foot một yard, 1760 yard một mile — mỗi bước một con số khác nhau, và mỗi con số phải học thuộc riêng. Đó chính là lý do gần cả thế giới bỏ nó, và cũng là lý do một tàu thăm dò sao Hoả từng nổ tung vì hai nhóm kỹ sư dùng hai hệ đo khác nhau.","So converting is moving a decimal point, with nothing extra to remember. Imperial has twelve inches to a foot, three feet to a yard and 1,760 yards to a mile — a different number at every step, each to be learned separately. That is why nearly all the world dropped it, and also why a Mars probe once broke up because two teams of engineers used two different systems."]],["Một hệ thống tốt là hệ thống bắt trí nhớ làm ít việc nhất. Chọn đúng cách đặt vấn đề thì phần lớn cái phải học thuộc tự biến mất.","A good system asks the least of memory. Choose the right way to set a problem up and most of what had to be memorised simply disappears."],['Bẫy: đổi đơn vị bằng cách nhớ chiều "nhân hay chia" thay vì nghĩ số phải to lên hay bé đi. Đổi 3 mét ra xăng-ti thì con số phải TO lên, vì xăng-ti là đơn vị bé, đo cùng một quãng thì cần nhiều cái hơn.',"The trap: converting by recalling whether to multiply or divide instead of asking whether the number should grow or shrink. Three metres in centimetres must be a BIGGER number, because a centimetre is small and the same distance needs more of them."],["Hỏi ở nhà: cái bàn nhà mình dài bao nhiêu xăng-ti, và bằng mấy mét?","Ask at home: how many centimetres is our table, and how many metres is that?"]),n("the-tich-lit",2,["Phân biệt đo sức chứa với đo khối lượng, và nói được vì sao dầu nổi trên nước.","Tell capacity from mass, and say why oil floats on water."],[["Lít đo sức chứa. Ki-lô-gam đo khối lượng. Hai thứ khác nhau.","Litres measure capacity. Kilograms measure mass. They are different things."],["Một lít nước nặng đúng một ki-lô-gam. Đó không phải trùng hợp: người ta cố ý định nghĩa ki-lô-gam như thế.","One litre of water weighs exactly one kilogram. Not a coincidence: the kilogram was defined that way on purpose."],['Nhưng một lít dầu ăn chỉ nặng khoảng 0,9 ki-lô. Cùng một sức chứa mà nhẹ hơn, nghĩa là dầu "loãng" hơn nước — và đó chính là lý do đổ dầu vào nước thì dầu nổi lên trên. Nổi hay chìm không phụ thuộc vào nặng hay nhẹ, mà phụ thuộc vào nặng bao nhiêu TRÊN MỘT LÍT. Con tàu sắt nghìn tấn vẫn nổi vì bên trong nó phần lớn là không khí.',"But a litre of cooking oil weighs about 0.9 kilograms. Same capacity, less mass, means oil is thinner than water — which is exactly why poured oil rises above it. Floating does not depend on being heavy or light but on how heavy PER LITRE. A thousand-tonne steel ship floats because most of what is inside it is air."]],['Rất nhiều câu hỏi tưởng khó chỉ khó vì đang trộn hai đại lượng làm một. Tách "bao nhiêu chỗ" khỏi "nặng bao nhiêu" là tách xong nửa bài.',"Many questions look hard only because two quantities have been mashed into one. Separating how much room from how much weight solves half the problem."],['Bẫy: "một cân bông nhẹ hơn một cân sắt". Hai bên nặng bằng nhau đúng một cân, chỉ khác là bông chiếm nhiều chỗ hơn rất nhiều. Câu đố này chơi đúng vào chỗ người ta trộn sức chứa với khối lượng.',"The trap: a kilo of feathers being lighter than a kilo of iron. They weigh the same kilo; the feathers merely take up far more room. The riddle works precisely because people fuse capacity and mass."],["Hỏi ở nhà: chai nước mắm nhà mình mấy lít, và nó nặng khoảng bao nhiêu?","Ask at home: how many litres is our fish-sauce bottle, and how heavy is it?"]),n("dien-tich-hay-chu-vi",2,["Biết lúc nào tính chu vi, lúc nào tính diện tích, và mua đúng số vật liệu.","Know when to work out perimeter and when area, and buy the right amount."],[["Chu vi là đi vòng quanh mép. Diện tích là phủ kín bên trong.","Perimeter walks around the edge. Area covers everything inside."],["Mua hàng rào thì tính chu vi. Mua gạch lát thì tính diện tích. Nhầm hai cái này là mua thiếu hoặc thừa cả đống.","Fencing goes by perimeter, floor tiles by area. Confuse them and you buy far too little or far too much."],["Chỗ khó chịu là hai thửa ruộng cùng chu vi vẫn có thể khác diện tích rất xa. Một thửa 10 nhân 10 và một thửa 1 nhân 19 đều có chu vi 40, nhưng thửa đầu rộng 100 còn thửa sau chỉ 19 — gấp hơn năm lần. Ai bán đất theo chiều dài mặt tiền là đang bán chu vi, còn cái người mua thật sự cần lại là diện tích.","The awkward part is that two fields with the same perimeter can differ enormously in area. A ten by ten and a one by nineteen both have a perimeter of forty, yet the first holds a hundred and the second only nineteen — more than five times apart. Anyone selling land by its frontage is selling perimeter, while what the buyer actually needs is area."]],["Hai đại lượng cùng mô tả một hình không có nghĩa là chúng đi cùng nhau. Biết đại lượng nào trả lời câu hỏi nào là gốc của mọi phép đo.","Two quantities describing one shape need not move together. Knowing which quantity answers which question is the root of all measurement."],["Bẫy: tưởng hình nào chu vi lớn hơn thì diện tích cũng lớn hơn. Sai hẳn — với cùng một chu vi, hình càng vuông vắn thì càng rộng, và hình tròn là hình rộng nhất trong tất cả.","The trap: assuming a bigger perimeter means a bigger area. Quite wrong — for one fixed perimeter, the squarer the shape the more it holds, and a circle holds most of all."],["Hỏi ở nhà: phòng mình dài rộng bao nhiêu, và lát kín sàn thì cần mấy viên gạch?","Ask at home: how long and wide is this room, and how many tiles would floor it?"]),n("gap-doi-canh",3,["Nói được vì sao gấp đôi cạnh thì diện tích gấp bốn chứ không gấp đôi.","Say why doubling a side makes the area four times, not twice."],[["Ô vuông cạnh 1 có diện tích 1. Ô vuông cạnh 2 có diện tích 4.","A square of side one has area one. A square of side two has area four."],["Vì diện tích là dài nhân rộng, mà cả hai chiều đều gấp đôi. Hai lần hai là bốn.","Because area is length times width, and both of those dimensions doubled. Two twos are four."],["Thể tích còn dữ hơn: gấp đôi cạnh thì chứa gấp TÁM, vì có tới ba chiều cùng gấp đôi. Đây chính là lý do một con kiến to bằng con voi sẽ gãy chân ngay lập tức: sức khoẻ của cái chân lớn theo diện tích mặt cắt, tức là bình phương, còn thân nặng lớn theo thể tích, tức là lập phương. Phóng to con vật lên mười lần thì nó nặng hơn nghìn lần mà chân chỉ khoẻ hơn trăm lần.","Volume is fiercer still: double the side and it holds EIGHT times as much, because three dimensions doubled. This is exactly why an ant the size of an elephant would snap its legs at once: a leg’s strength grows with its cross-section, a square, while the body’s weight grows with volume, a cube. Scale a creature up ten times and it weighs a thousand times more while its legs are only a hundred times stronger."]],["Cái gì lớn lên cũng lớn theo một luật riêng, và các luật ấy không lớn cùng tốc độ. Chỗ này là gốc của rất nhiều điều tưởng như phi lý trong tự nhiên.","Everything that grows grows by a law of its own, and those laws do not grow at the same speed. Here lies the root of a great many things in nature that look absurd at first."],["Bẫy: gấp đôi mọi thứ thì mọi thứ gấp đôi. Nên có người tưởng cái bánh đường kính gấp đôi thì to gấp đôi và tính giá gấp đôi — thật ra nó to gấp bốn, và ai bán theo cách ấy thì đang bán rẻ mất một nửa.","The trap: doubling everything doubles everything. So people assume a cake of twice the diameter is twice the cake and price it at twice — in fact it is four times, and anyone pricing that way has given half of it away."],["Hỏi ở nhà: cái bánh 20 phân và cái bánh 30 phân, cái sau to gấp mấy lần?","Ask at home: a twenty-centimetre cake and a thirty — how many times bigger is it?"]),n("xac-suat-cong-lai",3,["Kiểm tra một bộ xác suất bằng cách cộng cả bộ lại xem có bằng 1 không.","Check a set of probabilities by adding them all up and seeing if they make one."],[["Xúc xắc sáu mặt đều nhau, nên mỗi mặt là 1/6.","A fair die has six equal faces, so each face is one sixth."],["Cộng cả sáu khả năng lại: 6/6, tức là bằng 1. Luật này đúng với mọi thứ đo được bằng xác suất.","Add all six together: six sixths, which is one. This holds for anything measured by probability."],["Tổng xác suất của TẤT CẢ những gì có thể xảy ra bao giờ cũng bằng 1, vì chắc chắn sẽ xảy ra một cái gì đó trong số ấy. Nên đây là một cây thước kiểm tra rất khoẻ: ai đưa ra một bảng khả năng mà cộng lại thành 1,4 thì hoặc họ đếm trùng một trường hợp, hoặc họ bịa. Không cần biết gì về vấn đề của họ, chỉ cần cộng.","The chances of EVERYTHING that could happen always sum to one, because something among them is certain to occur. That makes a powerful measuring stick: if somebody’s table of possibilities adds to 1.4, either they have counted one case twice or they are inventing. You need know nothing about their subject — you only need to add."]],['Nhiều thứ trong toán có một "ràng buộc tổng" như thế: một con số mà cả hệ phải khớp vào. Tìm ra ràng buộc ấy là có ngay cách kiểm tra mà không cần hiểu chi tiết.',"Many parts of mathematics carry a constraint on the total like this: one number the whole system must fit. Find that constraint and you have a check that needs no grasp of the details."],["Bẫy: cộng xác suất của những trường hợp CHỒNG LÊN NHAU. Xác suất trời mưa là 0,6 và xác suất trời gió là 0,7, cộng lại thành 1,3 — vô lý, vì trời có thể vừa mưa vừa gió, hai trường hợp ấy không loại trừ nhau.","The trap: adding the chances of cases that OVERLAP. Rain has a chance of 0.6 and wind 0.7, and the sum is 1.3 — nonsense, because it can rain and blow at once, so the cases do not exclude each other."],["Hỏi ở nhà: tung một đồng xu, khả năng ra sấp và khả năng ra ngửa cộng lại bằng mấy?","Ask at home: tossing a coin, what do the chances of heads and tails add to?"]),n("doc-lap-hay-khong",3,["Nói được cái gì thật sự đổi được xác suất, và cái gì chỉ làm mình thấy nó đổi.","Say what really changes the odds, and what only makes them feel changed."],[["Tung đồng xu ra ngửa năm lần liền. Lần thứ sáu, khả năng ra sấp là bao nhiêu?","A coin lands heads five times running. What is the chance of tails on the sixth?"],["Vẫn đúng một nửa. Đồng xu không có trí nhớ, nó không biết năm lần vừa rồi đã xảy ra chuyện gì.","Still exactly half. A coin has no memory and knows nothing of the five tosses just past."],['Cảm giác thì gào lên rằng "sắp tới lượt sấp rồi". Cảm giác ấy có tên riêng trong sách: ngộ nhận của con bạc, và cả sòng bạc trên thế giới sống bằng nó. Cái duy nhất đổi được xác suất là đổi chính đồng xu — làm cong nó, đúc lệch nó, dính keo một mặt. Đổi vật thì đổi được xác suất; đổi cảm giác thì không.',"The gut roars that tails is due. The feeling has a name in the books: the gambler’s fallacy, and every casino in the world lives on it. The only thing that changes the odds is changing the coin itself — bending it, casting it off-centre, gluing one face. Change the object and the odds change; change how you feel and nothing moves."]],["Xác suất là tính chất của VẬT và của cách làm, không phải của lịch sử vừa rồi. Muốn biết khả năng đổi hay chưa thì hỏi: có gì trong thế giới thật vừa khác đi không?","Probability is a property of the OBJECT and the procedure, not of recent history. To know whether the odds moved, ask what in the physical world has actually changed."],['Bẫy: ngược lại cũng sai — thấy ngửa năm lần rồi đặt tiếp vào ngửa vì "đang có lộc". Cả hai kiểu đều đang đọc ý nghĩa vào một chuỗi số ngẫu nhiên, chỉ khác chiều đọc, và cả hai đều tốn tiền như nhau.',"The trap runs both ways: after five heads, backing heads again because the streak is hot. Both readings pour meaning into a random run, differing only in direction, and both cost exactly the same."],["Hỏi ở nhà: nếu tung đồng xu mười lần mà ra ngửa cả mười, mình nên nghi cái gì?","Ask at home: if a coin came up heads ten times in ten, what should we suspect?"]),n("trung-binh-hay-trung-vi",4,["Chọn giữa trung bình và trung vị, và nói được vì sao chọn cái ấy.","Choose between the mean and the median, and say why you chose it."],[["Mười người trong một phòng. Chín người lương 5 triệu, một người 500 triệu.","Ten people in a room. Nine earn five million and one earns five hundred."],["Lương trung bình của phòng ấy là 54,5 triệu. Con số này tính đúng, không sai một li.","The average wage in that room is 54.5 million. The figure is arithmetically perfect."],["Nhưng nó mô tả sai gần như tất cả mọi người trong phòng: chín trên mười người kiếm ít hơn nó gấp mười lần. Trung vị — con số đứng giữa khi xếp cả dãy theo thứ tự — là 5 triệu, và nó nói thật hơn hẳn. Khi trong dãy có một giá trị lệch hẳn, trung bình bị nó kéo đi, còn trung vị thì đứng yên. Đó là lý do báo chí nói về giá nhà và về lương thường dùng trung vị, còn ai muốn con số nghe cho to thì dùng trung bình.","Yet it describes almost nobody in that room: nine of the ten earn a tenth of it. The median — the middle value once the list is put in order — is five million, and it tells far more truth. When one value lies far out, the mean is dragged towards it while the median stays put. That is why reporting on house prices and wages usually uses the median, and why anyone who wants a large-sounding number reaches for the mean."]],['Không có con số nào "tóm tắt" một đám đông mà không mất mát gì. Mỗi cách tóm tắt giữ lại một thứ và ném đi thứ khác, nên phải hỏi: người đưa số này đang muốn mình thấy gì?',"No single number summarises a crowd without loss. Each summary keeps one thing and throws another away, so ask what the person offering it wants you to see."],['Bẫy: nghe hai chữ "trung bình" là tin ngay vì nó nghe có vẻ khách quan. Trung bình khách quan về mặt tính toán, nhưng CHỌN dùng trung bình thay vì trung vị lại là một lựa chọn của con người, và lựa chọn ấy có thể có chủ ý.',"The trap: trusting the word average because it sounds neutral. A mean is neutral in its arithmetic, but CHOOSING a mean instead of a median is a human decision, and that decision can be quite deliberate."],["Hỏi ở nhà: cả nhà mình cao trung bình bao nhiêu, và ai đúng ở giữa?","Ask at home: what is the average height in this family, and who is in the middle?"]),n("bay-cua-bieu-do",4,["Nhìn một biểu đồ và chỉ ra chỗ người vẽ đã chọn khung nhìn.","Look at a chart and point to where its maker chose the frame."],[["Một cái biểu đồ có thể nói dối mà không cần một con số sai nào.","A chart can lie without a single false number in it."],["Cách dễ nhất là cắt trục dọc cho nó không bắt đầu từ 0. Mức tăng 2% lập tức trông như tăng gấp đôi.","The easiest way is to cut the vertical axis so it does not start at zero. A two per cent rise instantly looks like a doubling."],["Cách thứ hai là chọn khoảng thời gian có lợi: lấy đúng từ năm thấp nhất tới năm cao nhất thì đường nào cũng vẽ được thành đi lên. Cách thứ ba là bỏ đơn vị đi, để người xem không so được với cái gì. Không cách nào trong ba cách này là bịa số, nên không ai bắt được ai nói dối — họ chỉ chọn khung nhìn, và đó là kiểu nói dối khó bắt nhất, vì tất cả bằng chứng đều thật.","The second is to pick a helpful stretch of time: run from the lowest year to the highest and any line can be made to climb. The third is to drop the units, so the viewer has nothing to compare against. None of the three invents a number, so nobody can be caught lying — they merely chose the frame, and that is the hardest lie to catch, because every piece of evidence in it is true."]],["Số liệu không tự nói. Bao giờ cũng có một người quyết định vẽ cái gì, bỏ cái gì, và bắt đầu từ đâu — nên câu hỏi đầu tiên trước mọi biểu đồ là: ai vẽ cái này, và họ muốn gì?","Data never speaks for itself. Somebody always decides what to draw, what to leave out and where to begin — so the first question before any chart is who made it and what they want."],["Bẫy: cái đẹp làm ta tin. Biểu đồ 3D bóng bẩy, màu đẹp, phông chữ sang thì được tin hơn hẳn một bảng số thô, dù bảng số thô mới là thứ cho phép mình tự kiểm tra lại.","The trap: beauty buys belief. A glossy three-dimensional chart in handsome colours is trusted far more than a plain table of numbers, although only the plain table lets you check anything yourself."],["Hỏi ở nhà: tìm một biểu đồ trên báo hoặc trên tivi, trục của nó có bắt đầu từ 0 không?","Ask at home: find a chart in the news — does its axis start at zero?"]),n("mau-du-lon-chua",4,["Hỏi hai câu về bất kỳ kết quả khảo sát nào: hỏi bao nhiêu người, và chọn thế nào.","Ask two questions of any survey result: how many people, and how were they chosen."],[['Hỏi 5 người bạn rồi kết luận "cả lớp thích món này". Sai ở đâu?',"Ask five friends and conclude the class likes it. What went wrong?"],["Sai ngay từ cỡ mẫu: năm người thì một người đổi ý đã làm kết quả lệch hai mươi phần trăm.","It fails at the sample size: with five people, one changing their mind swings the result by twenty per cent."],["Nhưng cỡ mẫu mới là nửa câu chuyện. Nửa còn lại là chọn NGẪU NHIÊN hay không: hỏi toàn bạn thân thì có hỏi năm nghìn người vẫn lệch, vì bạn thân thường giống mình. Điều đáng kinh ngạc là để nói về một nước tám mươi triệu dân, hỏi khoảng một nghìn hai người chọn ngẫu nhiên đã đủ tin — cái quyết định không phải hỏi được bao nhiêu phần trăm dân số, mà là cách chọn có lệch hay không.","But sample size is only half the story. The other half is whether the choosing was RANDOM: ask only close friends and five thousand of them stay biased, because friends resemble you. The astonishing part is that to speak about a country of eighty million, about twelve hundred people chosen at random suffice — what decides it is not what share of the population you reached but whether the reaching was slanted."]],["Một mẫu chỉ nói được về đám đông mà nó được rút ra từ đó, và chỉ khi cách rút không thiên vị ai. Chọn sai cách rút thì cỡ mẫu lớn tới đâu cũng không cứu được.","A sample speaks only about the population it was drawn from, and only if the drawing favoured nobody. Draw it wrongly and no size of sample can rescue it."],["Bẫy: khảo sát trên mạng, ai muốn thì bấm vào trả lời. Loại này luôn lệch, vì người có ý kiến mạnh mới bỏ công trả lời, còn người thấy bình thường thì lướt qua — nên kết quả nghiêng hẳn về phía những người đang bực.","The trap: an online poll anyone may click. These always tilt, because people with strong feelings take the trouble to answer while the indifferent scroll past — so the result leans heavily towards whoever is annoyed."],["Hỏi ở nhà: bố mẹ có bao giờ được ai hỏi ý kiến trong một cuộc khảo sát chưa?","Ask at home: has anyone here ever actually been asked to take part in a survey?"]),n("tuong-quan-khong-phai-nhan-qua",4,["Thấy hai thứ cùng tăng thì đi tìm thứ thứ ba đứng sau cả hai.","When two things rise together, go looking for the third thing behind both."],[["Tháng nào bán nhiều kem thì tháng ấy nhiều người chết đuối. Số liệu đúng thật.","In months when more ice cream sells, more people drown. The figures are real."],["Nhưng kem không dìm ai cả. Cái đứng sau cả hai là mùa hè: hè thì vừa ăn kem nhiều vừa đi bơi nhiều.","But ice cream drowns nobody. Behind both stands summer: in summer people eat more ice cream and swim more."],["Kiểu nhầm này có ở khắp nơi và rất khó bỏ, vì đầu người được làm ra để đi tìm nguyên nhân. Trẻ chân to đọc giỏi hơn trẻ chân bé — vì chân to nghĩa là lớn tuổi hơn. Ở châu Âu nơi nào nhiều cò thì nhiều trẻ sơ sinh — vì nơi ấy là vùng nông thôn đông dân. Muốn biết thật sự cái này có gây ra cái kia không thì chỉ có một cách chắc chắn: can thiệp vào một bên rồi xem bên kia có đổi không.","This mistake is everywhere and hard to shake, because the human head is built to hunt for causes. Children with bigger feet read better — because bigger feet mean older children. Regions of Europe with more storks have more babies — because those are populous rural regions. To know whether one thing truly causes another there is only one sure method: intervene on one side and see whether the other moves."]],["Hai thứ đi cùng nhau có thể vì ba lý do: cái này gây ra cái kia, cái kia gây ra cái này, hoặc một thứ thứ ba gây ra cả hai. Số liệu một mình không bao giờ tách được ba khả năng ấy.","Two things move together for one of three reasons: this causes that, that causes this, or a third thing causes both. Data alone can never separate the three."],["Bẫy: tin vào tương quan khi nó hợp với điều mình vốn đã nghĩ. Chỗ nguy không phải mấy ví dụ buồn cười về cò với kem — chỗ nguy là những tương quan nghe rất có lý, vì lúc ấy không ai buồn đi tìm thứ thứ ba.","The trap: believing a correlation when it agrees with what you already thought. The danger is not the comic examples about storks and ice cream — it is the correlations that sound entirely sensible, because then nobody bothers to look for the third thing."],['Hỏi ở nhà: bố mẹ có nghe câu nào kiểu "cứ làm A là được B" mà thật ra chưa chắc không?',"Ask at home: have you heard a claim that doing A brings B, which might not hold?"])],c=[n("tien-tu-dau-ra",2,["Quy giá một món đồ ra số buổi làm, rồi quyết định mua hay không.","Price a thing in afternoons of work, then decide whether to buy it."],[["Tiền được cho và tiền tự kiếm tiêu giống hệt nhau ở ngoài chợ.","Money given and money earned buy exactly the same things at the market."],["Nhưng cảm giác thì khác hẳn, và cái khác ấy có ích: thứ mình đổi công ra mới thấy nó đáng bao nhiêu giờ.","Yet they feel entirely different, and the difference is useful: only what you traded work for shows how many hours it costs."],['Nên có một mẹo nhỏ mà rất khoẻ: trước khi mua gì, thử quy nó ra "bằng mấy buổi làm". Một món 200 nghìn với người kiếm 50 nghìn một buổi là bốn buổi. Câu hỏi "có đáng 200 nghìn không" rất khó trả lời, nhưng câu hỏi "có đáng bốn buổi làm không" thì trả lời được ngay, vì bốn buổi là thứ mình hình dung ra được.',"So here is a small but powerful habit: before buying, convert the price into afternoons of work. Two hundred thousand, for someone earning fifty a shift, is four shifts. The question of whether something is worth two hundred thousand is hard to answer, but whether it is worth four afternoons answers itself, because four afternoons is a thing you can picture."]],["Tiền là phiếu ghi công đã bỏ ra. Quy về công thì mọi cái giá đều so sánh được với nhau, kể cả những cái giá không cùng loại.","Money is a receipt for work already done. Convert to work and every price becomes comparable, even prices of quite different kinds."],["Bẫy: tiền lì xì hay tiền được cho thì tiêu dễ hơn hẳn, vì đầu mình xếp nó vào một ngăn khác. Nhưng đồng tiền không biết nó tới từ đâu, và cái ngăn ấy chỉ có trong đầu, không có trong ví.","The trap: gift money spends far more easily, because the head files it in a separate drawer. The money itself does not know where it came from, and the drawer exists only in the head, not in the purse."],["Hỏi ở nhà: bố mẹ làm bao lâu thì đủ tiền mua một bao gạo?","Ask at home: how long do you have to work to pay for one sack of rice?"]),n("gia-cua-cho",3,["Giải thích một cái giá bằng hai thứ: có bao nhiêu hàng và bao nhiêu người muốn.","Explain a price by two things: how much exists and how many want it."],[["Không ai một mình quyết được giá rau ngoài chợ.","Nobody alone decides the price of vegetables at the market."],["Giá là chỗ gặp nhau giữa hai bên: bao nhiêu hàng đang có, và bao nhiêu người đang muốn mua.","A price is where two sides meet: how much is there, and how many people want it."],["Nên được mùa lại là tai hoạ của người trồng: ai cũng thu hoạch cùng lúc, hàng đầy chợ, giá sập tới mức có năm nông dân đổ rau xuống ruộng vì chở ra chợ còn lỗ tiền xe. Cùng một công sức, cùng cây rau ấy, mà giá khác nhau ba lần chỉ vì thời tiết năm nay thuận. Giá không đo công sức của ai cả — nó đo quan hệ giữa số hàng và số người muốn, ngay lúc ấy.","So a bumper harvest can ruin the grower: everybody crops at once, the market fills, and the price collapses until in some years farmers tip vegetables back into the field because the cart fare exceeds the takings. The same labour and the same plants fetch three times less simply because the weather was kind. A price measures nobody’s effort — it measures the relation between the quantity and the wanting, at that moment."]],["Giá không phải một tính chất nằm trong món đồ, kiểu như cân nặng. Nó là một quan hệ giữa người với người, nên nó đổi khi người đổi, dù món đồ không đổi gì.","A price is not a property sitting inside an object, like its weight. It is a relation between people, so it moves when people move, though the object has not changed at all."],["Bẫy: nghĩ giá cao nghĩa là đồ tốt. Nước trong sa mạc đắt không phải vì nó ngon hơn nước ở nhà, mà vì ở đó có ít nước và nhiều người khát. Giá nói về hoàn cảnh nhiều hơn nói về món đồ.","The trap: taking a high price as a mark of quality. Water in a desert is dear not because it tastes better than water at home but because there is little of it and many are thirsty. A price says more about circumstances than about the object."],["Hỏi ở nhà: mùa này quả gì đang rẻ nhất ngoài chợ, và vì sao lại rẻ?","Ask at home: which fruit is cheapest at the market now, and why is it cheap?"]),n("tiet-kiem-hay-cat-giam",3,["Phân biệt khoản cắt đi thật sự tiết kiệm với khoản cắt đi hoá ra tốn hơn.","Tell a cut that really saves from a cut that turns out to cost more."],[["Không phải khoản nào cắt đi cũng là tiết kiệm.","Not every cut is a saving."],["Tắt đèn, mang cơm đi làm, sửa thay vì mua mới — những khoản này cắt đi thì đỡ tốn thật.","Lights off, lunch from home, repair instead of replace — cut these and you genuinely spend less."],["Nhưng bỏ tiền khám bệnh sớm để rồi phải nằm viện, hay mua đôi giày rẻ đi hai tháng lại phải mua đôi nữa, thì không phải tiết kiệm — đó là trả chậm với lãi rất cao. Người nghèo hay bị kẹt đúng chỗ này: không phải vì họ không biết đôi giày tốt rẻ hơn về lâu dài, mà vì hôm nay trong túi chỉ có đủ tiền mua đôi rẻ. Nghèo tự nó là một khoản chi phí.","But skipping the early doctor’s visit and ending in hospital, or buying cheap shoes that last two months and buying them again, is no saving — it is paying later at a punishing rate. Poor households are caught precisely here: not because they fail to see that good shoes are cheaper over years, but because today’s pocket holds only the price of the cheap ones. Being poor is itself an expense."]],["Muốn biết một khoản cắt có phải tiết kiệm không thì phải nhìn xa hơn tháng này. Cùng một hành động, tính trong một tuần thì lời, tính trong một năm thì lỗ.","To know whether a cut saves, you must look past this month. The same act can show a gain over a week and a loss over a year."],["Bẫy: đo tiết kiệm bằng số tiền chi ra hôm nay. Cách đo ấy luôn khen món rẻ nhất, kể cả khi món rẻ nhất là món phải mua lại năm lần. Phải đo bằng chi phí trên mỗi tháng dùng được thì mới ra sự thật.","The trap: measuring thrift by what leaves your pocket today. That measure always praises the cheapest option, even when the cheapest must be bought five times over. Cost per month of use is the measure that tells the truth."],["Hỏi ở nhà: nhà mình có món gì mua rẻ rồi phải mua lại mấy lần không?","Ask at home: is there something here we bought cheap and had to buy again?"]),n("ba-cai-hu",2,["Chia mọi khoản tiền vào ba chỗ ngay lúc nhận, trước khi kịp nghĩ.","Split every amount three ways the moment it arrives, before thinking."],[["Cách cổ điển: mỗi khoản tiền chia ngay làm ba phần.","The old method: split every amount into three at once."],["Một phần tiêu bây giờ, một phần để dành, một phần cho đi. Chia ngay lúc nhận, chưa kịp nghĩ.","One part to spend now, one to keep, one to give away. Split it on arrival, before any thinking starts."],['Cái hay không nằm ở tỉ lệ chia bao nhiêu, mà ở chỗ chỉ phải quyết định MỘT LẦN. Sau đó mỗi khoản tiền tự biết đi đâu, không phải cân nhắc lại. Người ta không tiêu hết tiền vì tham — người ta tiêu hết vì mỗi ngày phải quyết định lại "cái này mua hay không", và quyết mãi thì mệt, mà mệt thì gật đầu cho xong. Chia trước là cách cắt hẳn cái mệt ấy.',"The strength is not in the proportions but in deciding ONCE. After that each amount knows where it goes and needs no further weighing. People do not run out of money from greed — they run out because every day brings the same question of whether to buy this, and deciding wears you down, and worn down you say yes to be finished. Splitting in advance removes the wearing entirely."]],["Ý chí là thứ có hạn và cạn dần trong ngày. Nên cách giữ tiền tốt nhất không phải cố gắng nhiều hơn, mà là dựng sẵn một luật để về sau khỏi phải cố.","Willpower is finite and drains through the day. So the best way to keep money is not trying harder but setting a rule in advance, so that later no trying is needed."],["Bẫy: để dành phần dư cuối tháng. Cuối tháng gần như không bao giờ còn dư, vì chi tiêu tự nở ra cho vừa số tiền đang có. Phải cất phần để dành ra TRƯỚC, rồi mới tiêu phần còn lại.","The trap: saving whatever is left at the end of the month. There is almost never anything left, because spending swells to fill whatever is present. The saving must be taken out FIRST and the rest spent after."],["Hỏi ở nhà: nhà mình có cất riêng một khoản nào ra trước khi tiêu không?","Ask at home: do we set any money aside before we start spending?"]),n("mua-bay-gio-hay-doi",2,["Dùng luật một đêm để tách cơn thèm mua khỏi nhu cầu thật.","Use the one-night rule to tell an urge to buy from a real need."],[["Luật một đêm: món nào không cần ngay thì để qua một đêm rồi hãy quyết.","The one-night rule: anything not needed at once waits a night before you decide."],["Phần lớn cơn thèm mua tan trong một đêm. Cái còn lại sau một đêm thường là thứ mình cần thật.","Most urges simply dissolve overnight. Whatever survives the night is usually a real need."],['Người bán biết luật này rõ hơn mình, và toàn bộ nghề của họ là làm sao để mình không kịp qua đêm: "chỉ hôm nay", "còn 3 suất", đồng hồ đếm ngược trên màn hình. Những thứ ấy không nói gì về món đồ cả — chúng chỉ nói rằng người bán rất muốn mình quyết trong lúc còn đang nóng. Thấy ai giục mình quyết nhanh thì đó chính là lúc nên chậm lại.',"Sellers know this rule better than you do, and their entire craft is making sure the night never arrives: today only, three left, a countdown clock on the screen. None of that says anything about the goods — it says the seller badly wants the decision made while you are still warm. Being hurried is itself the signal to slow down."]],["Quyết định vội và quyết định kỹ dùng hai phần khác nhau trong đầu. Ai muốn mình quyết vội thường là vì phần nghĩ kỹ sẽ trả lời không.","Fast decisions and careful decisions use different parts of the head. Anyone who wants yours fast usually knows the careful part would say no."],['Bẫy: giảm giá là tiết kiệm. Mua một món giảm 50% mà mình không cần thì không tiết kiệm được nửa tiền, mà tốn đúng số tiền đã trả. Chữ "tiết kiệm" trên biển quảng cáo chỉ đúng khi mình đằng nào cũng phải mua món ấy.','The trap: a discount as a saving. Buying something half price that you do not need saves nothing and costs exactly what you paid. The word "save" on a sign is true only for something you were going to buy anyway.'],["Hỏi ở nhà: có món nào nhà mình mua vì đang giảm giá rồi không dùng tới không?","Ask at home: did we ever buy something because it was on sale and never use it?"]),n("von-va-lai",3,["Tách tiền bán khỏi tiền lời, và nói được vì sao quán đông khách vẫn có thể lỗ.","Separate takings from profit, and say why a busy shop can still lose money."],[["Một quán bán được 10 triệu một ngày. Quán ấy lời bao nhiêu?","A shop takes ten million a day. How much has it made?"],["Chưa biết. Còn phải trừ tiền hàng, tiền thuê nhà, tiền công thợ, tiền điện.","Not known yet. Stock, rent, wages and electricity have still to come off."],["Nếu vốn hàng 7 triệu, thuê nhà và công thợ 2 triệu, thì lời đúng 1 triệu — một phần mười của con số nghe rất kêu ban đầu. Người mới buôn hay nhìn tiền bán mà quên vốn, và đó là lý do rất nhiều quán đông khách vẫn phải đóng cửa: bán chạy nghĩa là dòng tiền chảy qua tay nhiều, không nghĩa là còn lại nhiều. Con số duy nhất đáng nhìn là con số cuối cùng, sau khi đã trả hết mọi thứ.","If the stock cost seven million and rent and wages two, the profit is exactly one — a tenth of the impressive figure it started from. Beginners watch the takings and forget the cost, which is why plenty of busy shops close: selling fast means a great deal of money passing through your hands, not a great deal remaining in them. The only figure worth reading is the last one, after everything has been paid."]],['Mọi con số về tiền đều phải hỏi "trước hay sau khi trừ cái gì". Cùng một hoạt động có thể mô tả bằng một con số rất to hoặc rất nhỏ, và cả hai đều đúng.',"Every figure about money needs the question: before or after subtracting what. One activity can be described by a very large number or a very small one, and both are honest."],["Bẫy: khoe doanh thu như thể đó là lời. Cách nói này gặp khắp nơi, từ quán ăn tới công ty lớn, và nó không sai một chữ nào — nó chỉ dừng lại đúng ở chỗ nghe hay nhất và không đi tiếp.","The trap: quoting revenue as though it were profit. The habit runs from food stalls to large companies, and not a word of it is false — it simply stops at the most flattering point and goes no further."],["Hỏi ở nhà: nếu nhà mình bán một món gì đó, tiền vốn của nó gồm những khoản nào?","Ask at home: if we sold something, what would all the costs of it be?"]),n("chi-phi-co-hoi",4,["Tính giá thật của một lựa chọn bằng thứ tốt thứ hai mà mình đã bỏ.","Price a choice by the second-best thing you gave up for it."],[["Giá thật của một lựa chọn không phải con số ghi trên nhãn.","The true price of a choice is not the number on the label."],["Nó là thứ tốt thứ hai mà mình đã phải bỏ để chọn cái này. Chọn một là mất tất cả những cái còn lại.","It is the second-best thing you gave up to take this one. To choose is to lose everything else."],["Học nghề ba năm không chỉ tốn tiền học: nó còn tốn ba năm lương mà lẽ ra mình đã kiếm được. Một buổi chiều xem phim không chỉ tốn tiền vé, nó tốn cả buổi chiều ấy. Nhìn ra được chi phí cơ hội là chỗ khác nhau giữa tính giá và tính đúng — và nó cũng giải thích vì sao thời gian của người bận rộn lại đắt: họ có nhiều thứ tốt để bỏ hơn.","Three years of training does not merely cost the fees: it costs three years of wages you would otherwise have earned. An afternoon at the cinema does not merely cost the ticket, it costs the afternoon. Seeing opportunity cost is the difference between counting a price and counting correctly — and it explains why the time of busy people is expensive: they have more good things to give up."]],["Không có lựa chọn nào miễn phí, kể cả lựa chọn không làm gì cả. Không làm gì cũng là bỏ mất mọi thứ mình có thể đã làm trong quãng ấy.","No choice is free, including the choice to do nothing. Doing nothing forfeits everything you might have done in that stretch of time."],["Bẫy: chỉ tính những khoản có hoá đơn. Cái đắt nhất trong phần lớn quyết định là thời gian và cơ hội, mà hai thứ ấy không ai gửi hoá đơn tới, nên chúng thường bị bỏ ra ngoài phép tính.","The trap: counting only what came with a receipt. The dearest part of most decisions is time and forgone chances, and nobody invoices you for either, so they usually drop out of the sum."],["Hỏi ở nhà: bố mẹ đã từng bỏ một việc để làm một việc khác chưa, và bỏ cái gì?","Ask at home: did you ever give up one path to take another — what did you give up?"]),n("tien-mat-roi-thi-thoi",4,["Bỏ khoản đã tiêu ra khỏi phép tính, và chỉ nhìn về phía trước khi quyết.","Leave what is already spent out of the sum, and decide looking only forward."],[["Mua vé xem phim rồi mà phim dở. Nên ngồi hết hay đi về?","You bought the ticket and the film is bad. Stay or leave?"],["Ngồi hết cũng không lấy lại được tiền vé. Tiền ấy mất rồi, dù mình ở hay đi.","Sitting through it refunds nothing. That money is gone whether you stay or go."],['Nên câu hỏi đúng chỉ còn là: hai tiếng tới, ngồi đây hay làm việc khác thì hơn? Quyết định đúng bao giờ cũng chỉ nhìn về phía trước. Nhưng con người rất ghét bỏ dở, nên hay ngồi tiếp cho "đỡ phí" — và kết cục mất cả tiền vé lẫn hai tiếng. Cái bẫy này lớn dần theo số tiền đã bỏ ra: càng đầu tư nhiều vào một việc hỏng thì càng khó dừng, dù chính vì thế mà càng nên dừng.',"So the only real question left is whether the next two hours are better spent here or elsewhere. A sound decision always looks forward. But people hate abandoning things and stay on to avoid waste — and end up losing the ticket and the two hours. The trap grows with the sum already sunk: the more you have poured into something failing, the harder it is to stop, although that is exactly why you should."]],["Quá khứ không phải một khoản đang nằm trên bàn để mình cân nhắc. Nó đã ra khỏi cuộc chơi, và mọi lựa chọn còn lại đều bắt đầu từ đúng chỗ mình đang đứng.","The past is not a stake still lying on the table to be weighed. It has left the game, and every remaining choice begins exactly where you now stand."],['Bẫy: câu "đã trót thì trét". Nghe như kiên trì, thật ra là để khoản tiền đã mất quyết định thay cho mình, và nó thường đẩy người ta đi thêm rất xa trên một con đường mà chính họ đã thấy là sai.',"The trap: in for a penny, in for a pound. It sounds like perseverance and is really letting lost money make the decision, and it usually carries people a long way further down a road they had already seen was wrong."],["Hỏi ở nhà: có việc gì nhà mình đã bỏ dở giữa chừng mà bỏ là đúng không?","Ask at home: was there something we abandoned halfway that was right to abandon?"]),n("bao-hiem-la-gi",3,["Nói được vì sao bảo hiểm và vé số cùng một cỗ máy mà ngược chiều nhau.","Say why insurance and a lottery run on the same machine in opposite directions."],[["Nhiều người góp tiền vào một chỗ. Một ít người nhận về.","Many people pay into one pot. A few are paid out of it."],["Câu ấy mô tả đúng cả vé số lẫn bảo hiểm. Cỗ máy y hệt nhau, chỉ khác một chỗ.","That describes a lottery and an insurance scheme equally well. The machine is identical but for one thing."],["Vé số trả cho người MAY. Bảo hiểm trả cho người XUI. Nên một cái làm rủi ro của mình lớn lên — bình thường mình không mất gì, mua vé rồi thì gần như chắc chắn mất tiền vé — còn cái kia làm rủi ro nhỏ đi: mất đều đặn một khoản nhỏ để khỏi mất một khoản khổng lồ vào đúng năm xui nhất. Quỹ tương tế của làng ngày xưa chính là bảo hiểm, chỉ khác là không có công ty nào đứng giữa.","A lottery pays the LUCKY. Insurance pays the UNLUCKY. So one enlarges your risk — normally you lose nothing, and once you buy a ticket you almost certainly lose its price — while the other shrinks it: you lose a small amount steadily so as not to lose an enormous one in your worst year. The old village mutual fund was insurance exactly, with no company standing in the middle."]],['Cùng một cơ chế chuyển tiền có thể dùng để tăng hay giảm rủi ro, tuỳ vào việc nó trả cho ai. Hỏi "ai được trả tiền" thường hiểu ra nhanh hơn hỏi "cái này là gì".',"One and the same money-moving mechanism can raise or lower risk, depending on whom it pays. Asking who gets paid usually explains a scheme faster than asking what it is."],['Bẫy: nghĩ mua bảo hiểm là "lỗ" khi cả năm không dùng tới. Năm không dùng tới chính là năm mình đã thắng — mình trả tiền để mua sự yên tâm, và thứ mình mua đã được giao đủ.',"The trap: feeling a loss when a year passes and the insurance is never claimed. That year is the year you won — you paid for peace of mind, and it was delivered in full."],["Hỏi ở nhà: nhà mình có khoản nào đóng đều đặn để phòng lúc khó không?","Ask at home: do we pay anything regularly to cover us against a bad turn?"]),n("lam-phat",3,["Nói được vì sao bát phở ngày xưa rẻ mà không phải vì phở ngon hơn bây giờ.","Say why a bowl of pho was cheap long ago, and not because the pho was better."],[["Ông bà kể hồi xưa bát phở có mấy hào.","Grandparents remember a bowl of pho costing a few coins."],["Không phải phở đắt lên. Là đồng tiền nhỏ đi: cùng một tờ tiền, mỗi năm mua được ít hơn.","Pho did not grow dear. The money grew small: the same note buys less every year."],["Nên để tiền mặt nằm trong tủ nhiều năm là một khoản lỗ có thật, chỉ là khoản lỗ không ai gửi hoá đơn. Với lạm phát 5% một năm, mười năm sau một triệu chỉ còn mua được bằng khoảng sáu trăm nghìn hôm nay. Đó là lý do người ta gửi ngân hàng, mua vàng, hay mua đất — không hẳn để giàu lên, mà để không nghèo đi trong lúc ngồi yên.","So cash left in a drawer for years is a genuine loss, merely one nobody invoices. At five per cent a year, a million ten years on buys about what six hundred thousand buys today. That is why people put money in banks, or into gold, or into land — not necessarily to grow richer, but to avoid growing poorer while sitting still."]],["Con số trên tờ tiền không phải giá trị của nó. Giá trị là số hàng nó đổi được, và số ấy thay đổi theo thời gian dù con số in trên giấy thì đứng yên.","The number printed on a note is not its value. Its value is the goods it fetches, and that moves with time although the printed number never does."],['Bẫy: so tiền của hai thời khác nhau mà không quy về cùng một năm. "Ngày xưa lương có 50 đồng" nghe như nghèo khủng khiếp, nhưng phải hỏi 50 đồng lúc ấy mua được bao nhiêu gạo thì mới so được.',"The trap: comparing money from two eras without converting to one year. Wages of fifty back then sound like terrible poverty, but you must ask how much rice fifty bought before any comparison means anything."],["Hỏi ở nhà: hồi bố mẹ bằng tuổi con, một bát phở giá bao nhiêu?","Ask at home: when you were my age, what did a bowl of pho cost?"]),n("vay-de-lam-gi",4,["Phân biệt khoản vay tự trả được với khoản vay để lại nợ mà không để lại gì.","Tell a loan that pays for itself from one that leaves the debt and nothing else."],[["Vay tiền không phải bao giờ cũng sai. Vấn đề là vay để mua cái gì.","Borrowing is not always a mistake. The question is what the borrowing buys."],["Vay để học nghề, để mua cái máy làm ra tiền, để chữa bệnh — những khoản này về sau tự trả được.","Borrowing to learn a trade, to buy a tool that earns, to be treated when ill — these can pay for themselves later."],["Vay để mua thứ tiêu đi thì món đồ hết mà món nợ ở lại, và món nợ ấy còn lớn lên theo lãi. Nguy nhất là vay để trả một khoản nợ cũ: lúc ấy vòng quay bắt đầu, và nó quay càng lúc càng nhanh vì mỗi vòng lại thêm một lớp lãi. Câu hỏi cần hỏi trước mọi khoản vay chỉ có một: khoản này rồi sẽ tự sinh ra tiền để trả chính nó, hay mình sẽ phải trả nó bằng một nguồn khác chưa biết là gì?","Borrowing for something consumed leaves the thing gone and the debt behind, and the debt grows with interest. Most dangerous is borrowing to pay an older debt: there the wheel begins, and it spins faster every turn as another layer of interest joins. There is only one question to put before any loan: will this generate the money to repay itself, or will I repay it from some other source I cannot yet name?"]],["Nợ không phải xấu hay tốt, nó là một cái máy khuếch đại: vay đúng chỗ thì nó đẩy mình đi nhanh hơn, vay sai chỗ thì nó kéo mình xuống nhanh hơn, cùng một tốc độ ấy.","Debt is neither good nor bad; it is an amplifier: borrowed well it moves you forward faster, borrowed badly it pulls you down faster, at the very same speed."],["Bẫy: nhìn vào số tiền phải trả mỗi tháng thay vì tổng số phải trả. Trả góp kéo dài gấp đôi thì mỗi tháng nhẹ đi thật, mà tổng tiền lãi thì tăng lên rất nhiều — và đó chính là chỗ người bán trả góp kiếm sống.","The trap: reading the monthly payment instead of the total. Stretch an instalment plan to twice the length and each month is genuinely lighter while the total interest climbs sharply — which is precisely where the lender makes a living."],["Hỏi ở nhà: nhà mình có bao giờ vay để mua thứ gì rồi thấy đáng vay không?","Ask at home: have we ever borrowed for something and found it worth borrowing for?"]),n("viec-ra-tien",2,["Phân biệt việc có người trả công với việc không ai trả mà vẫn phải làm.","Tell paid work apart from the unpaid work that still has to happen."],[["Một buổi rửa xe thì có người trả tiền. Một buổi quét nhà thì không.","An afternoon washing bikes gets paid. An afternoon sweeping the house does not."],["Cái chợ chỉ trả cho thứ nó dùng được, và nó chỉ dùng được thứ nó nhìn thấy. Việc trong nhà thì không ai ngoài nhà nhìn thấy, nên không ai trả — chứ không phải vì nó nhẹ hơn hay dễ hơn.","A market pays for what it can use, and it can only use what it can see. Housework happens where nobody outside the house can see it, so nobody pays for it — not because it is lighter or easier work."],["Thử làm phép này một lần: cộng số giờ cả nhà bỏ ra mỗi tuần cho nấu, giặt, dọn, trông em. Rồi hỏi nếu phải thuê người làm đúng chỗ ấy thì hết bao nhiêu. Con số hiện ra thường lớn hơn cả tháng lương, và nó vẫn không xuất hiện ở bất kỳ tờ giấy nào. Việc không ai trả không phải việc không có giá — nó là việc có giá mà không có hoá đơn.","Try this sum once: add up the hours the household spends each week cooking, washing, tidying, minding the little ones. Then ask what hiring somebody to do exactly that would cost. The figure is often larger than a month’s wages, and it appears on no piece of paper anywhere. Unpaid work is not work without a price — it is work with a price and no invoice."]],["Tiền chỉ chảy qua chỗ có người ngoài nhìn thấy và chịu trả. Cái nhìn thấy được thì không phải lúc nào cũng là cái quan trọng, và nhầm hai thứ ấy là nhầm cả một đời người.","Money only flows where an outsider can see the work and agrees to pay for it. What is visible is not always what matters, and confusing the two can misdirect a whole life."],["Bẫy: nghĩ việc nào không ra tiền thì việc ấy không đáng làm. Nếu đúng thế thì không ai nuôi con, không ai chăm bố mẹ già, và cái nhà sập trước cái ví.","The trap: assuming work that earns nothing is work not worth doing. Were that true, nobody would raise a child or care for an ageing parent, and the household would collapse well before the purse did."],["Hỏi ở nhà: một tuần nhà mình mất bao nhiêu giờ cho việc không ai trả công?","Ask at home: how many hours a week does this house spend on work nobody pays for?"]),n("tien-vao-hay-ra",2,["Xếp mọi khoản của một tháng về đúng hai cửa: vào và ra.","Sort every item of a month into the two doors: in and out."],[["Cái ví nào cũng chỉ có hai cửa. Tiền vào một cửa, tiền ra cửa kia.","Every purse has only two doors. Money comes in one and leaves by the other."],["Nghe thì hiển nhiên, nhưng ít người ngồi xếp thật. Chưa xếp thì tháng nào cũng thấy thiếu mà không chỉ ra được chỗ thiếu, và cái không chỉ ra được thì không sửa được.","It sounds obvious, and few people ever actually sort. Until they do, every month feels short without a nameable place where it went short — and what cannot be named cannot be fixed."],["Cách làm mất mười phút: một tờ giấy, kẻ dọc một vạch. Bên trái ghi mọi khoản vào trong một tháng, bên phải mọi khoản ra. Cộng hai bên rồi trừ. Nếu bên phải lớn hơn thì phần chênh ấy đang được trả bằng một cái gì đó — tiền để dành cũ, hoặc một món nợ mới. Không có cách thứ ba, và chính vì không có cách thứ ba nên tờ giấy này chưa bao giờ nói dối ai.","It takes ten minutes: one sheet of paper with a line down the middle. On the left, everything that came in over a month; on the right, everything that went out. Add both, subtract. If the right side is bigger, that difference is being paid by something — old savings, or a new debt. There is no third possibility, and because there is no third possibility this sheet of paper has never once lied to anybody."]],["Không có khoản nào lơ lửng giữa hai cửa. Mỗi đồng hoặc đang đi vào hoặc đang đi ra, nên một cái ví bao giờ cũng đếm được — chỉ có người ngại đếm, chứ không có cái ví không đếm nổi.","Nothing hovers between the two doors. Every dong is either arriving or leaving, so any purse can be counted — there are only people who would rather not count, never a purse beyond counting."],["Bẫy: chỉ nhớ các khoản to. Cái làm hụt một tháng thường không phải cái xe đạp mua một lần, mà là mười lăm khoản nhỏ lặp lại mà không khoản nào đáng nhớ riêng.","The trap: remembering only the large items. What sinks a month is rarely the bicycle bought once, but fifteen small repeats, no one of which was worth remembering on its own."],["Hỏi ở nhà: tháng vừa rồi nhà mình có mấy cửa tiền vào?","Ask at home: how many doors did money come in by last month?"]),n("tra-cong-the-nao",2,["Hỏi cho rõ mình được trả cho thời gian hay cho kết quả, trước khi nhận việc.","Settle whether you are paid for time or for output, before taking the work."],[["Dạy kèm thì tính theo giờ. Bán rau thì tính theo món bán được.","Tutoring is counted by the hour. Selling greens is counted by what sells."],["Hai cách trả này kéo bàn tay đi hai hướng ngược nhau. Trả theo giờ thì làm nhanh chẳng được thêm gì, nên tay chậm lại và kỹ hơn. Trả theo món thì làm kỹ lại thiệt, nên tay nhanh lên.","The two arrangements pull a pair of hands in opposite directions. Paid by the hour, hurrying earns nothing, so hands slow down and grow careful. Paid by the piece, care costs you, so hands speed up."],["Vì thế trách một người làm ẩu hay làm chậm mà không nhìn cách trả công là trách nhầm chỗ. Đổi cách trả thì cùng một người ấy làm khác hẳn. Một quán trả người rửa bát theo giờ sẽ có bát sạch và bếp đóng muộn; trả theo mâm thì bếp đóng sớm mà bát thì phải kiểm. Không cách nào tốt hơn cách nào — chỉ có cách nào hợp với thứ mình thật sự cần.","So blaming somebody for sloppiness or slowness without looking at how they are paid is blaming the wrong thing. Change the arrangement and the same person works differently. A kitchen that pays its washer by the hour gets clean plates and a late close; paying by the tray closes early and needs the plates checked. Neither is better — only one of them matches what you actually need."]],["Cách trả công là một cái luật đặt lên bàn tay, và bàn tay bao giờ cũng đi theo luật. Muốn đổi việc người ta làm thì đổi luật, chứ đổi lời khuyên thì không ăn thua.","How pay is arranged is a rule laid over a pair of hands, and hands follow rules. To change what people do, change the rule; advice alone rarely shifts anything."],['Bẫy: tưởng trả theo món bao giờ cũng công bằng hơn vì "làm nhiều ăn nhiều". Nó chỉ công bằng khi mọi món khó như nhau — mà ngoài đời thì hiếm khi thế.',"The trap: assuming piece rates are always fairer because more work means more pay. That holds only when every piece is equally hard, which in real work it seldom is."],["Hỏi ở nhà: việc của bố mẹ được trả theo giờ, theo món, hay theo tháng?","Ask at home: is your parents’ work paid by the hour, by the piece, or by the month?"]),n("gia-niem-yet",2,["Biết chỗ nào mặc cả được, chỗ nào không, và vì sao lại khác nhau.","Know where haggling works, where it does not, and why the two differ."],[["Giá trong siêu thị thì in sẵn. Giá ngoài chợ rau thì phải hỏi.","A supermarket price is printed. A price at the vegetable market has to be asked for."],["Giá in ra là giá cùng một số cho mọi người, nên nó không phụ thuộc vào việc mình khéo nói hay không. Đứa trẻ tám tuổi và một bà buôn ba mươi năm mua cùng hộp sữa ấy đúng một giá.","A printed price is one number for everybody, so it does not depend on how well you speak. An eight-year-old and a trader of thirty years pay exactly the same for that tin of milk."],["Ngoài chợ thì giá là chỗ hai người gặp nhau, nên nó đổi theo giờ, theo mùa, theo cả việc mình có vẻ vội hay không. Ở đó cái làm ra một giá tốt không phải tài mặc cả mà là biết giá hôm qua bao nhiêu: người biết giá thì chỉ cần đứng yên, còn người không biết giá thì mặc cả hăng đến mấy cũng chỉ đang mặc cả quanh một con số do người bán chọn.","At a market the price is where two people meet, so it moves with the hour, the season, and with whether you look in a hurry. There, a good price comes not from skill at haggling but from knowing yesterday’s price: whoever knows it need only stand still, while whoever does not can haggle furiously and still only be haggling around a number the seller chose."]],["Giá niêm yết mua lấy sự công bằng bằng cách bỏ đi sự linh hoạt; chợ giữ linh hoạt bằng cách bỏ đi sự công bằng. Không kiểu nào đúng hơn — chúng đổi hai thứ khác nhau lấy nhau.","A listed price buys fairness by giving up flexibility; a market keeps flexibility by giving up fairness. Neither is more correct — each trades one thing for the other."],["Bẫy: tưởng chỗ nào cũng mặc cả được nếu đủ lì. Mặc cả ở quầy thuốc hay quầy vé không rẻ được đồng nào, chỉ làm mất thì giờ của cả hàng người phía sau.","The trap: believing anywhere yields to persistence. Haggling at a pharmacy counter or a ticket window saves nothing at all and costs the queue behind you its afternoon."],["Hỏi ở nhà: nhà mình mua thứ gì mà giá đổi theo mùa?","Ask at home: what does this house buy whose price moves with the season?"]),n("mua-thua-vi-re",2,["Chia giá cho số dùng được, không phải cho số mua về.","Divide the price by what gets used, not by what came home."],[["Gói năm cân rẻ hơn mỗi cân. Nhưng nhà mình ăn hết năm cân không?","The five-kilo sack is cheaper per kilo. But will this house finish five kilos?"],["Phép chia mà tấm biển làm hộ mình là chia cho số mua về. Phép chia đúng là chia cho số thật sự dùng được, và hai phép ấy chỉ bằng nhau khi không hỏng mất cái nào.","The sum the sign does for you divides by what you carry home. The honest sum divides by what actually gets used, and the two agree only when nothing spoils."],["Thùng hai tư hộp giá bằng hai mươi hộp lẻ, nghe là lãi bốn hộp. Nhưng nếu tới hạn mà còn tám hộp phải bỏ, thì hai mươi hộp tiền ấy chỉ đổi được mười sáu hộp ăn — thành ra đắt hơn mua lẻ. Cái bẫy không nằm ở con số, nó nằm ở chỗ tấm biển biết trước mình sẽ chia sai. Hàng để lâu không hỏng thì mua nhiều gần như luôn đúng; hàng mau hỏng thì phải hỏi thêm một câu về cái tủ lạnh nhà mình.","A case of twenty-four costs the same as twenty singles, which sounds like four tins gained. But if eight are still there at the use-by date, that twenty tins of money bought sixteen tins of eating — dearer than buying singly. The trick is not in the arithmetic; it is that the sign knows in advance which way you will divide. For things that keep, buying big is nearly always right; for things that spoil, there is a second question, and it is about your own fridge."]],["Một cái giá chỉ có nghĩa khi đi kèm mẫu số. Đổi mẫu số thì cùng một con số ấy chuyển từ rẻ sang đắt, và người bán được chọn mẫu số in lên biển.","A price means nothing without its denominator. Change the denominator and the same number moves from cheap to dear — and the seller chooses which denominator goes on the sign."],['Bẫy: thấy chữ "rẻ hơn" là tin ngay mà không hỏi rẻ hơn tính trên cái gì. Rẻ hơn mỗi cân, rẻ hơn mỗi hộp, và rẻ hơn mỗi bữa thật sự ăn là ba con số khác nhau.','The trap: trusting the words "cheaper" without asking cheaper per what. Cheaper per kilo, cheaper per tin, and cheaper per meal actually eaten are three different numbers.'],["Hỏi ở nhà: tháng vừa rồi nhà mình phải bỏ đi thứ gì vì mua nhiều quá?","Ask at home: what did this house throw away last month because too much was bought?"]),n("tien-thoi-dung",2,["Kiểm tiền thối bằng cách cộng lên, không phải trừ xuống.","Check your change by counting up, not by taking away."],[["Mua hết ba mươi lăm, đưa tờ năm mươi. Phải thối lại bao nhiêu?","The bill is thirty-five, you hand over fifty. How much comes back?"],["Cách trong sách là năm mươi trừ ba mươi lăm. Cách ngoài chợ là cộng lên: từ ba lăm lên bốn mươi là năm, từ bốn mươi lên năm mươi là mười — vị chi mười lăm.","The schoolbook way is fifty take away thirty-five. The market way counts up: thirty-five to forty is five, forty to fifty is ten — fifteen in all."],["Hai cách cùng ra một số, nhưng cộng lên thì đầu ít trượt hơn hẳn, vì không phải nhớ mượn của ai. Đó cũng đúng là cách người bán hàng đếm tiền trả lại: họ không trừ, họ đặt từng tờ xuống và đếm tiếp từ giá món cho tới số mình đưa. Biết cách ấy thì mình kiểm được ngay lúc đứng đó, chứ không phải về tới nhà mở ví ra mới ngờ ngợ — mà lúc ấy thì chẳng còn ai để hỏi.","Both give the same number, but counting up slips far less, because nothing has to be borrowed and remembered. It is also exactly how a shopkeeper hands change back: not by subtracting but by laying notes down and counting on from the bill to the money given. Knowing it lets you check while still standing there, rather than half-doubting at home with the purse open — by which point there is nobody left to ask."]],["Cộng dễ nhẩm hơn trừ vì cộng đi thẳng một chiều, còn trừ thì có lúc phải quay lại mượn hàng trên. Chọn phép dễ hơn không phải là lười, đó là bớt một chỗ để sai.","Adding is easier in the head than subtracting because adding runs one way, while subtracting sometimes has to turn back and borrow. Choosing the easier operation is not laziness; it removes one place to go wrong."],["Bẫy: nhận tiền thối rồi mới đếm lúc đã đi khỏi quầy. Đếm ngay tại chỗ không phải là nghi ngờ ai — đó là lúc duy nhất còn sửa được nếu có nhầm.","The trap: pocketing the change and counting it once you have left the counter. Counting on the spot is not an accusation — it is the only moment when a mistake can still be put right."],["Hỏi ở nhà: có ai từng bị thối nhầm tiền chưa, và lúc ấy phát hiện ra thế nào?","Ask at home: has anyone here ever been given the wrong change, and how was it spotted?"]),n("mat-thi-doi-lai-duoc",2,["Biết thứ nào mất còn đòi lại được, thứ nào mất là thôi.","Know which losses can be recovered and which are simply gone."],[["Mất cái thẻ thì gọi một cuộc là khoá được. Mất tờ tiền thì thôi.","Lose the card and one phone call locks it. Lose the note and that is that."],["Khác nhau ở một chỗ duy nhất: có tên mình ghi ở đâu đó hay không. Tờ tiền không biết chủ của nó là ai, nên ai nhặt được là của người ấy, và không có cách nào chứng minh ngược lại.","The difference is one thing only: whether your name is written down somewhere. A banknote does not know who owns it, so whoever picks it up owns it, and there is no way to prove otherwise."],["Đó là lý do người lớn không để cả tháng lương trong túi quần, và cũng là lý do cái xe có giấy tờ khác hẳn cái xe không giấy. Ghi tên lại chỗ nào đó nghe rất buồn tẻ so với việc cầm tiền mặt cho tiện, nhưng cái buồn tẻ ấy chính là thứ biến một mất mát thành một phiền phức. Tiền mặt tiện đúng lúc tiêu, và chỉ đúng lúc ấy thôi.","That is why grown-ups do not carry a month’s wages in a trouser pocket, and why a bike with papers is a different object from a bike without. Having your name recorded somewhere sounds very dull beside the convenience of cash, yet that dullness is precisely what turns a loss into a nuisance. Cash is convenient at the moment of spending, and at no other moment."]],["Cái gì có sổ thì có thể lần lại; cái gì không có sổ thì chỉ tồn tại trong tay người đang cầm. Sổ sách không sinh ra để làm khó nhau, nó sinh ra để mất còn tìm lại được.","What is recorded can be traced; what is unrecorded exists only in the hand holding it. Records were not invented to make life awkward, but so that what is lost can be found again."],['Bẫy: nghĩ giữ tiền mặt là an toàn nhất vì "mình cầm được nó". Cầm được cũng có nghĩa là rơi được, cháy được, và không ai đền được.',"The trap: thinking cash is safest because you can hold it. Being holdable also means being droppable, burnable, and reimbursed by nobody."],["Hỏi ở nhà: nhà mình có thứ gì quý mà không ghi tên ở đâu cả không?","Ask at home: does this house own anything valuable whose name is written down nowhere?"]),n("khong-cho-ai-biet",2,["Nhận ra thứ nào là chìa khoá, và không đọc nó cho bất kỳ ai.","Recognise which things are keys, and read them aloud to nobody."],[["Có thứ giấu vì ngại. Có thứ giấu vì nó chính là cái chìa.","Some things are kept quiet out of shyness. Some are kept quiet because they are the key."],["Mã OTP là chìa khoá dùng một lần của tiền nhà mình. Ai cầm được nó trong đúng vài phút ấy thì mở được cửa, và cánh cửa không hỏi người mở là ai.","A one-time code is a single-use key to the family money. Whoever holds it during those few minutes can open the door, and the door does not ask who is opening it."],["Nên có một luật rất gọn, gọn tới mức không cần nghĩ: không ngân hàng nào, không công an nào, không nhân viên nào hỏi mã ấy bao giờ. Không phải vì họ lịch sự, mà vì họ không cần — bên trong hệ thống họ đã nhìn thấy mọi thứ trừ đúng cái mã này. Cho nên người đang hỏi mã, dù giọng có gấp gáp và tử tế đến đâu, đều là người đứng ngoài cửa. Câu trả lời cho mọi trường hợp là như nhau: cúp máy, rồi tự mình gọi lại vào số in trên thẻ.","So there is one rule, short enough to need no thinking: no bank, no police officer, no member of staff ever asks for that code. Not out of politeness, but because they do not need it — inside the system they can already see everything except this one code. Which means anybody asking for it, however urgent and however kind the voice, is somebody standing outside the door. The answer is the same every time: hang up, then ring back yourself on the number printed on the card."]],["Một cái chìa chỉ có tác dụng khi chỉ một người cầm. Chia sẻ chìa không phải là chia sẻ thông tin — nó là trao quyền mở cửa, và trao rồi thì không rút lại được.","A key only works while one person holds it. Sharing a key is not sharing information — it is handing over the right to open the door, and once handed over it cannot be recalled."],["Bẫy: người gọi đọc đúng tên mình, đúng địa chỉ, đúng số tài khoản nên nghe rất thật. Những thứ ấy đều mua được ở chợ đen; đúng cái mã kia thì không, và vì thế mới phải hỏi mình.","The trap: the caller knows your name, your address, your account number, so the call sounds real. All of that can be bought on a black market; the code cannot, which is exactly why they must ask you for it."],["Hỏi ở nhà: nhà mình đã ai nhận cuộc gọi lạ hỏi mã bao giờ chưa?","Ask at home: has anyone here had a strange call asking for a code?"]),n("no-phai-tra",2,["Tách khoản mình được cho ra khỏi khoản mình phải trả lại.","Separate money you were given from money you must give back."],[["Tiền mượn tiêu giống hệt tiền của mình. Đó chính là chỗ bẫy.","Borrowed money spends exactly like your own. That is precisely the trap."],["Lúc cầm trong tay, hai loại không phân biệt được: cùng tờ giấy ấy, cùng mua được ngần ấy thứ. Chúng chỉ khác nhau ở một ngày trong tương lai, và cái ngày ấy thì lúc tiêu không nhìn thấy.","In the hand the two are indistinguishable: the same paper, buying the same things. They differ only on a day in the future, and that day is invisible at the moment of spending."],["Món nợ nhỏ mà nhớ ngày trả thì không hại gì, thậm chí còn tiện. Cái hỏng bắt đầu ở chỗ quên mất nó là nợ: mình đếm số tiền đang có, thấy đủ, rồi tiêu — trong khi một phần số ấy đã có chủ khác. Nên người lớn hay ghi nợ ra giấy không phải vì trí nhớ kém, mà vì họ biết đầu mình sẽ tự động xếp nợ vào chung một ngăn với tiền của mình nếu không có gì chặn lại.","A small debt with a remembered due date does no harm, and can even be convenient. The damage starts where you forget it is a debt: you count what you have, find it sufficient, and spend — while part of that sum already belongs to somebody else. Grown-ups write debts down not because their memory is poor, but because they know the mind will quietly file a debt in the same drawer as its own money unless something stops it."]],["Nợ không phải là tiền, nó là thời gian: mình đang mượn phiên bản tương lai của chính mình một khoản, và người ấy sẽ phải trả. Câu hỏi duy nhất là người ấy có trả nổi không.","A debt is not money but time: you are borrowing from your own future self, and that person will have to pay. The only question is whether they can."],["Bẫy: thấy trong ví còn tiền là tưởng mình còn tiền. Số dư không trừ nợ ra hộ mình bao giờ, nên nó luôn là một con số rộng rãi hơn sự thật.","The trap: seeing money in the purse and concluding you have money. A balance never subtracts your debts for you, so it is always a more generous number than the truth."],["Hỏi ở nhà: nhà mình có ghi các khoản nợ ra chỗ nào không, hay chỉ nhớ?","Ask at home: are debts written down anywhere in this house, or only remembered?"]),n("luong-thuc-nhan",3,["Đọc một tờ lương: phân biệt số ghi trên hợp đồng với số về tới tay.","Read a payslip: tell the contract figure from the figure that arrives."],[["Hợp đồng ghi một trăm. Về tới tay bảy mươi lăm. Không ai bị lừa cả.","The contract says a hundred. Seventy-five arrives. Nobody has been cheated."],["Khoảng chênh ấy là mấy khoản bị trừ trước khi mình nhìn thấy đồng nào: bảo hiểm y tế, bảo hiểm xã hội, quỹ hưu, rồi thuế thu nhập. Chúng đi thẳng từ chỗ trả lương sang chỗ nhận, không qua tay mình.","The gap is a set of deductions taken before you see a single dong: health cover, social insurance, the pension fund, then income tax. They pass straight from payer to recipient without touching your hands."],["Vì thế người đi làm lần đầu gần như ai cũng hụt hẫng, và cái hụt hẫng ấy không đến từ số tiền mà đến từ chỗ không ai nói trước. Khi so hai lời mời việc, so con số cuối chứ đừng so con số đầu: một chỗ trả một trăm mà đóng đủ bảo hiểm có thể về tay ít hơn một chỗ trả chín mươi trả tay không giấy tờ — nhưng chỗ thứ nhất còn trả cho mình những tháng ốm, còn chỗ thứ hai thì tháng ốm là mình tự lo hết.","So almost every first job feels like a swindle, and the feeling comes not from the amount but from nobody having said so in advance. When comparing two offers, compare the final figures rather than the headline ones: a job paying a hundred with full contributions may deliver less in hand than one paying ninety in cash with no paperwork — but the first also pays for your sick months, while under the second every sick month is yours alone."]],["Lương là một con số bị hai lần biến đổi trước khi thành đồ ăn: một lần bởi các khoản đóng góp bắt buộc, một lần bởi thuế. Cả hai lần đều có luật viết sẵn, nên đều tra được — không có gì bí ẩn ở đây, chỉ có thứ chưa ai chỉ.","A wage passes through two transformations before it becomes food: compulsory contributions, then tax. Both are written in law and both can be looked up — nothing here is mysterious, only unexplained."],["Bẫy: chọn việc theo con số to nhất nghe được lúc phỏng vấn. Con số ấy hầu như luôn là con số trước khi trừ, và hai chỗ trả cùng con số ấy vẫn có thể về tay chênh nhau cả một phần năm.","The trap: choosing a job by the largest figure said aloud at interview. That figure is almost always the pre-deduction one, and two employers quoting it identically can still differ by a fifth in what reaches your hand."],["Hỏi ở nhà: trên tờ lương của bố mẹ có mấy dòng bị trừ, và dòng nào lớn nhất?","Ask at home: how many deduction lines are on your parents’ payslip, and which is largest?"]),n("thue-tra-cho-gi",3,["Nói được vì sao có những thứ không ai mua lẻ được.","Say why some things cannot be bought one household at a time."],[["Không nhà nào tự đắp nổi một con đê. Và một con đê hở một đoạn thì vô dụng.","No single household can raise a dyke. And a dyke with one gap in it is useless."],["Đó là loại thứ không chia lẻ ra bán được: con đê, con đường, cái đèn đường, việc dập một trận dịch. Ai ở sau đê cũng được nó che, kể cả người không góp — nên nếu để tuỳ tâm thì gần như chắc chắn đê không bao giờ đắp xong.","These are the things that cannot be sold in single portions: the dyke, the road, the street lamp, the ending of an epidemic. Everyone behind the dyke is sheltered by it, including those who gave nothing — so left to goodwill, the dyke would almost certainly never be finished."],['Thuế là cách người ta giải bài toán ấy: góp bắt buộc, để cái không chia lẻ được vẫn làm được. Vì bắt buộc nên nó luôn gây tranh cãi, và tranh cãi ấy là chuyện lành mạnh — nhưng nó là tranh cãi về mức bao nhiêu và tiêu vào đâu, chứ không phải về việc có cần con đê hay không. Một người nói "tôi không dùng trường công nên tôi không nên đóng" đang quên rằng cái làm anh ta thuê được thợ biết đọc chính là những cái trường ấy.','Tax is how that problem gets solved: a compulsory contribution so that the unsliceable thing can still be made. Being compulsory, it argues forever, and the argument is healthy — but it is an argument about how much and spent on what, not about whether the dyke is needed. Somebody saying "I use no state school so I should not contribute" has forgotten that what lets him hire a literate worker is precisely those schools.']],["Có những thứ chỉ tồn tại được khi mua chung, vì phần lợi của chúng không cắt ra riêng cho ai được. Chỗ nào không cắt lẻ được thì chợ không làm nổi, và chỗ ấy phải có một cách góp khác.","Some things exist only if bought together, because their benefit cannot be cut into private portions. Where it cannot be cut, a market cannot supply it, and some other way of contributing must be found."],["Bẫy: coi thuế là tiền mất đi, vì phần được nhận lại không mang tên mình. Con đường mình đi mỗi ngày cũng không mang tên ai, và nó vẫn là thứ mình đang tiêu.","The trap: reading tax as money lost, because what comes back carries nobody’s name. The road you use daily carries nobody’s name either, and you are spending it all the same."],["Hỏi ở nhà: quanh nhà mình có thứ gì mà không hàng xóm nào tự làm một mình được?","Ask at home: what stands near this house that no single neighbour could have built alone?"]),n("hoa-don-that",3,["Giữ đúng loại giấy tờ chứng minh được mình đã trả.","Keep the kind of paper that proves a payment happened."],[["Cái bắt tay là thật. Và nó vẫn không đứng được trước một người quên.","A handshake is real. And it still cannot stand against somebody who has forgotten."],["Giấy tờ không sinh ra vì người ta xấu. Nó sinh ra vì sau sáu tháng, trí nhớ hai bên lệch nhau một cách hoàn toàn thành thật — mỗi bên nhớ đúng cái phần có lợi cho mình mà không hề định nói dối.","Paperwork did not arise because people are dishonest. It arose because after six months two memories diverge quite sincerely — each remembering the part that suits it, with no intention of lying at all."],["Nên giữ lại tờ biên lai không phải là nghi ngờ ai, mà là tha cho cả hai khỏi một cuộc cãi mà không ai thắng nổi. Bốn thứ đứng được là hoá đơn, biên lai, sao kê ngân hàng và hợp đồng, vì cả bốn đều có ngày tháng và có bên thứ ba ghi nhận. Tin nhắn và ảnh chụp thì đỡ hơn không có, nhưng chúng ghi lại lời hứa chứ không ghi lại việc tiền đã đi.","So keeping the receipt is not suspicion; it spares both sides an argument nobody can win. Four things stand up: an invoice, a receipt, a bank statement and a contract, because all four carry a date and a third party who recorded it. Messages and photographs are better than nothing, but they record a promise rather than the movement of money."]],["Bằng chứng của một việc đã xảy ra phải do một bên thứ ba giữ, hoặc phải có dấu thời gian mà không bên nào sửa được. Cái gì chỉ nằm trong đầu hai người thì sau này là hai phiên bản.","Evidence that something happened must be held by a third party, or carry a timestamp neither side can alter. Whatever lives only in two heads becomes, later, two versions."],["Bẫy: nghĩ giữa người quen thì không cần giấy. Đúng những khoản giữa người quen mới hay hỏng tình, vì không ai muốn là người đầu tiên đòi hỏi giấy tờ.","The trap: assuming that between people who know each other, no paper is needed. Money between friends spoils friendships most reliably, precisely because nobody wants to be the first to ask for a record."],["Hỏi ở nhà: nhà mình giữ hoá đơn của thứ gì, và giữ trong bao lâu?","Ask at home: which receipts does this house keep, and for how long?"]),n("no-nao-dang-vay",4,["Hỏi một khoản vay sẽ được trả bằng cái gì, trước khi hỏi lãi bao nhiêu.","Ask what will repay a loan before asking what it charges."],[["Vay mua cái máy thì chính cái máy đi trả nợ. Vay đi chơi thì mình của năm sau trả.","A loan for a machine is repaid by the machine. A loan for a holiday is repaid by next year’s self."],["Đó là hai loại nợ khác hẳn nhau, dù trên giấy chúng giống nhau từng chữ. Loại thứ nhất mua về một thứ sinh ra dòng tiền mới; loại thứ hai mua về một thứ đã tiêu xong trước khi kỳ trả đầu tiên tới.","These are two quite different debts, though on paper they read identically. The first buys something that generates a new flow of money; the second buys something already consumed before the first instalment falls due."],['Không loại nào sai. Vay đi đám cưới bố mẹ có thể là quyết định đúng nhất đời một người, và không phép tính nào cãi được điều đó. Nhưng phải biết mình đang ở loại nào, vì loại thứ nhất tự nó lo được phần lãi còn loại thứ hai thì phần lãi phải cắt ra từ chỗ khác — thường là từ chính khoản để dành mà mình đang định gây dựng. Người hỏi "lãi bao nhiêu" trước khi hỏi "cái gì sẽ trả khoản này" là người đang so giá hai chiếc thuyền mà chưa biết mình định qua sông hay ra biển.',"Neither is wrong. Borrowing for a parent’s wedding may be the finest decision of somebody’s life, and no arithmetic can argue with it. But you must know which kind you are in, because the first covers its own interest while the second must cut that interest out of something else — usually out of the very savings you were trying to build. Anybody asking the rate before asking what will repay it is comparing the price of two boats without yet knowing whether the crossing is a river or an ocean."]],["Một khoản vay là việc kéo tiền từ tương lai về hiện tại, và bao giờ cũng phải trả thêm cho quãng kéo ấy. Nếu thứ mua được bằng khoản vay sinh ra nhiều hơn phần phải trả thêm thì phép đổi ấy lãi; nếu không thì nó chỉ là dời một cái khó sang chỗ khác.","A loan drags money from the future into the present, and the drag always costs. If what the money buys produces more than that cost, the exchange gains; if not, it has merely moved a difficulty somewhere else."],["Bẫy: chỉ nhìn khoản trả hằng tháng vì nó nhỏ và nghe kham được. Kéo dài kỳ hạn ra thì khoản tháng nào cũng nhỏ đi được, trong khi tổng phải trả thì lớn lên — và người bán biết rất rõ mình đang nhìn con số nào.","The trap: looking only at the monthly payment because it is small and sounds manageable. Stretch the term and the monthly figure always shrinks while the total grows — and the seller knows exactly which number you are watching."],["Hỏi ở nhà: nhà mình từng vay để mua thứ gì làm ra tiền chưa?","Ask at home: has this house ever borrowed to buy something that then earned?"]),n("phi-nap-them",4,["Cộng hết mọi khoản phải trả rồi so với giá mua đứt.","Total every payment you will make, then set it beside the cash price."],[['"Trả góp không lãi" gần như luôn đúng về chữ lãi và sai về số tiền.','"Nought per cent finance" is nearly always true about the word interest and false about the money.'],["Phần đáng lẽ gọi là lãi được đổi tên: thành phí hồ sơ, phí quản lý, phí bảo hiểm khoản vay, hoặc đơn giản là đã nằm sẵn trong cái giá trả góp cao hơn giá trả thẳng. Chữ đổi, tiền không đổi.","The part that would be interest is renamed: an arrangement fee, a management fee, loan insurance, or simply built into a hire-purchase price above the cash price. The word changes; the money does not."],["Nên chỉ có một phép kiểm, và nó không cần biết công thức nào: cộng hết mọi khoản mình sẽ phải trả từ đầu tới cuối, kể cả khoản trả trước và mọi thứ có chữ phí, rồi trừ đi giá mua đứt. Con số còn lại chính là giá của việc được trả dần, dù nó tự gọi mình là gì. Nếu người bán không nói được giá mua đứt là bao nhiêu thì đó đã là câu trả lời rồi: chỗ ấy không bán món hàng, chỗ ấy bán khoản vay.","So there is one test, and it needs no formula: add every payment you will make from first to last, including the deposit and everything with the word fee on it, then subtract the cash price. What remains is the price of paying over time, whatever it calls itself. And if the seller cannot tell you the cash price, that is already the answer: this shop is not selling the object, it is selling the loan."]],["Tên gọi của một khoản không đổi được sức nặng của nó. Mọi thứ phải chi ra vì trả dần thay vì trả ngay đều là giá của thời gian, nên phép cộng thô luôn thắng mọi cách đặt tên.","What a charge is called does not change its weight. Everything paid because you paid later rather than now is the price of time, so a crude total always beats any naming."],["Bẫy: so lãi suất giữa hai nơi mà không so tổng phải trả. Một nơi lãi thấp mà phí cao vẫn đắt hơn nơi lãi cao mà không phí, và cách duy nhất thấy được là cộng ra tiền.","The trap: comparing advertised rates between two lenders without comparing totals. Low rate with high fees beats nothing; the only way to see it is to add the money up."],["Hỏi ở nhà: nhà mình có món nào mua trả góp không, và tổng trả hơn giá đứt bao nhiêu?","Ask at home: was anything here bought on instalments, and how far above the cash price did it total?"]),n("nen-vay-o-dau",4,["Nhận ra chỗ cho vay tử tế bằng ba con số họ chịu viết ra.","Recognise a decent lender by the three numbers it will write down."],[["Chỗ cho vay tử tế viết ra ba con số: vay bao nhiêu, trả bao nhiêu, trong bao lâu.","A decent lender writes three numbers: how much, how much back, and by when."],["Chỗ không viết ra không phải vì họ tin mình. Là vì con số cuối cùng sẽ do họ nói, và nói lúc nào cũng được — nhất là lúc mình đã tiêu hết khoản vay và không còn đường nào khác.","A lender who writes nothing is not trusting you. It is keeping the final figure in its own mouth, to be named whenever suits — most usefully once the money is spent and you have no other road."],['Vay nhanh nhất bao giờ cũng là vay đắt nhất, và đó không phải sự trùng hợp: cái tốc độ ấy được mua bằng việc bỏ qua khâu xem mình có trả nổi không, mà khâu ấy vốn là khâu bảo vệ mình chứ không phải bảo vệ họ. Một quỹ xã hay hội phụ nữ cho vay chậm hơn, hỏi nhiều hơn, giấy tờ lằng nhằng hơn — và chính mấy cái phiền ấy là thứ ngăn một khoản vay biến thành một cái hố. Khi thấy một nơi cho vay dễ hơn hẳn mọi nơi khác, câu hỏi đúng không phải "sao họ tốt thế" mà "họ lấy lại bằng cách nào".',"The fastest loan is always the dearest, and that is no coincidence: the speed is bought by skipping the check on whether you can repay — a check that protects you rather than them. A commune fund or a women’s union lends more slowly, asks more questions and demands more paperwork, and those irritations are exactly what stops a loan becoming a pit. When one lender is far easier than all the others, the right question is not why they are so kind but how they take it back."]],["Một hợp đồng vay tồn tại để cả hai bên bị ràng như nhau. Bên nào không muốn viết ra là bên muốn giữ quyền đổi luật giữa chừng, và bên kia thì không có quyền ấy.","A loan contract exists so that both sides are bound equally. A side unwilling to write it down is a side keeping the right to change the rules midway — a right the other side does not have."],["Bẫy: tưởng cái app duyệt trong ba phút là hiện đại và tiện. Ba phút ấy có được vì họ không kiểm khả năng trả của mình, và họ không cần kiểm vì cách đòi của họ mới là thứ đảm bảo.","The trap: reading a three-minute approval as modern convenience. Those three minutes exist because nobody checked whether you can repay, and nobody needed to, because their method of collection is the security."],["Hỏi ở nhà: ở làng mình, người cần tiền gấp thường tới chỗ nào?","Ask at home: in this village, where do people go when they need money quickly?"]),n("giuc-cho-voi",3,["Nhận ra cái đồng hồ đếm ngược đang cắt đi quãng thời gian nào của mình.","See which interval of your own time a countdown is removing."],[["Cái đồng hồ đếm ngược trên màn hình không đo cái gì có thật cả.","The countdown on the screen is not measuring anything real."],["Nó chỉ có đúng một việc: cắt đi quãng thời gian mà lẽ ra mình dùng để hỏi một người khác, hoặc để so giá ở chỗ thứ hai. Quãng ấy thường chỉ cần một buổi tối, và nó là thứ đắt nhất mà người bán muốn lấy đi.","It has one function: to remove the interval in which you would have asked somebody else, or compared a second price. That interval is usually one evening long, and it is the most expensive thing the seller wants from you."],["Nên có một phép thử rất rẻ: nói với chính mình rằng để mai quay lại. Món hàng tốt chịu được câu ấy — mai nó vẫn còn, giá vẫn thế, và nếu hết thật thì trên đời còn chỗ khác. Đúng những món không chịu được câu ấy mới là món cần nghĩ lâu nhất, vì nếu giá trị của nó có thật thì nó đâu cần tới cái đồng hồ. Sự vội không phải là một đặc tính của món hàng; nó là một thứ được lắp thêm vào, và lắp cho mình chứ không phải cho món hàng.","So there is a very cheap test: tell yourself you will come back tomorrow. A good product survives it — tomorrow it is still there, still that price, and if it has genuinely sold out the world holds other shops. The offers that cannot survive it are the ones deserving the longest thought, because if the value were real it would not need the clock. Urgency is not a property of the goods; it is fitted afterwards, and fitted to you rather than to them."]],["Quyết định vội và quyết định sai không phải một, nhưng vội thì cắt mất khâu duy nhất bắt được cái sai: khâu so với một cái thứ hai. Mọi cách bán dựa vào gấp gáp đều nhắm đúng vào khâu ấy.","Hurried and wrong are not the same, but hurry removes the one step that catches wrongness: comparison with a second option. Every sales method built on urgency aims precisely there."],["Bẫy: nghĩ mình miễn nhiễm vì mình biết đó là chiêu. Biết tên cái bẫy không tắt được cảm giác sợ mất, nên thứ chặn được nó là một luật đặt sẵn cho mình, chứ không phải sự tỉnh táo lúc đứng đó.","The trap: believing you are immune because you can name the technique. Naming it does not switch off the fear of missing out, so what stops it is a rule set in advance, not alertness in the moment."],["Hỏi ở nhà: có ai từng mua vội một thứ rồi tiếc không, và tiếc vì cái gì?","Ask at home: has anyone bought something in a hurry and regretted it, and regretted what exactly?"]),n("ai-tra-tien-ho",4,["Hỏi ai đang trả cho thứ mình đang dùng miễn phí, và họ lấy lại bằng gì.","Ask who is paying for the free thing you use, and what they take back."],[["Nước mưa miễn phí vì không ai phải làm ra nó. Một ứng dụng thì có người làm.","Rainwater is free because nobody had to make it. An app had makers."],["Có người viết, có máy chủ chạy, có tiền điện trả hằng tháng, có lương trả hằng tháng. Không khoản nào trong đó tự biến mất chỉ vì trên màn hình có chữ miễn phí.","There are authors, servers running, a power bill each month, wages each month. Not one of those disappears because the screen says free."],['Nên nếu mình không trả bằng tiền thì cái đang được đem bán là thời gian mình nhìn quảng cáo, và những gì mình để lại trong đó: mình bao nhiêu tuổi, ở đâu, thích gì, mua gì, bấm vào cái gì lúc mấy giờ. Thứ ấy đáng tiền thật, đủ đáng để nuôi cả một toà nhà kỹ sư. Câu hỏi đúng không phải "có mất tiền không" mà "ai đang trả, và họ lấy lại bằng gì" — hỏi xong thì vẫn có thể dùng, chỉ là dùng mà biết mình đang trả bằng cái gì.',"So if you are not paying in money, what is being sold is the time you spend looking at advertisements, and what you leave behind: your age, your place, your likes, your purchases, what you tapped and at what hour. That is worth real money — enough to keep a building of engineers. The right question is not whether it costs anything but who is paying and what they take back — and having asked, you may well go on using it, only now knowing the currency."]],["Không có thứ gì cần công sức làm ra mà lại không có ai trả. Khi cái giá không hiện ra bằng tiền thì nó đang hiện ra bằng một thứ khác, và thứ khác ấy khó đếm hơn nên dễ trả nhiều hơn mức mình định.","Nothing that takes effort to make goes unpaid for. When the price does not appear in money it is appearing as something else, and that something else is harder to count — which is how people end up paying more of it than they meant to."],['Bẫy: coi dữ liệu của mình là thứ không đáng gì vì "tôi có gì đâu mà giấu". Giá trị của nó không nằm ở một người, nó nằm ở việc gộp một triệu người lại — và cái được bán là khả năng đoán trước mình sẽ làm gì.',"The trap: treating your own data as worthless because you have nothing to hide. Its value is not in one person but in a million pooled — and what is sold is the ability to predict what you will do next."],["Hỏi ở nhà: cái ứng dụng nhà mình dùng nhiều nhất sống bằng tiền của ai?","Ask at home: the app this house uses most — whose money keeps it alive?"]),n("quang-cao-hay-that",3,["Tách câu kiểm chứng được ra khỏi câu không bao giờ sai được.","Separate claims that can be checked from claims that can never be wrong."],[['Một câu kiểm được thì đem cân, đem thước ra là xong. "Tốt nhất" thì không cân vào đâu.','A checkable claim meets a scale or a ruler and the matter ends. "The best" meets nothing.'],["Nặng hai cân là câu có thể sai: đặt lên cân, thấy một cân tám, thế là bắt được. Tốt nhất thì không có cách nào sai, vì không ai định nghĩa được tốt nhất theo cái gì và so với ai.",'Two kilos is a claim that can be false: put it on the scale, read one point eight, and it is caught. "The best" cannot be false, because nobody has said best at what, or against whom.'],["Mà một câu không bao giờ sai được thì cũng không nói cho mình biết điều gì — nó chỉ chiếm chỗ. Nên có một cách đọc quảng cáo rất nhanh: gạch hết các tính từ đi, còn lại bao nhiêu con số và cam kết. Chỗ nào quảng cáo chuyển từ số sang tính từ chính là chỗ nó hết bằng chứng, và thường chỗ ấy rơi đúng vào điều quan trọng nhất. Một tấm biển đầy chữ mà không còn gì sau khi gạch tính từ thì đã tự nói ra tất cả.","And a sentence that cannot be false tells you nothing — it merely occupies space. So there is a fast way to read an advertisement: strike out every adjective and see how many numbers and commitments remain. The point where it switches from figures to adjectives is the point where its evidence ran out, and that point usually falls on the thing that matters most. A sign crowded with words that leaves nothing behind after the adjectives go has already told you everything."]],["Một câu chỉ có giá trị thông tin khi nó loại bỏ được điều gì đó. Câu nào cũng đúng trong mọi trường hợp thì nó không loại bỏ gì, nên nó không mang tin — dù nghe rất mạnh.","A statement carries information only if it rules something out. A statement true in every case rules out nothing and so carries nothing, however forceful it sounds."],['Bẫy: thấy có con số là tin, mà không hỏi con số ấy đo cái gì. "Chín trên mười người dùng thấy tốt hơn" là một con số thật đứng trên một phép đo không ai kiểm được.','The trap: trusting anything with a figure in it without asking what the figure measured. "Nine in ten users noticed an improvement" is a real number standing on a measurement nobody can inspect.'],["Hỏi ở nhà: tìm một tấm biển quảng cáo, gạch hết tính từ đi, còn lại gì?","Ask at home: take one advertisement, strike out every adjective — what is left?"])],s=[n("chu-nom-la-gi",3,["Nói được chữ Nôm khác chữ Hán ở chỗ nào, và vì sao nó khó học.","Say how chu Nom differs from Chinese script, and why it was hard to learn."],[["Tiếng Việt có từ rất lâu. Chữ để viết tiếng Việt thì có sau, rất muộn.","Vietnamese is very old. A script for writing it came much later."],["Chữ Nôm ghép các bộ phận chữ Hán lại để ghi âm tiếng Việt — mượn hình của người, ghi tiếng của mình.","Chu Nom joined parts of Chinese characters to record Vietnamese sounds — borrowing their shapes to write our speech."],["Cái khó nằm ở chỗ: muốn đọc được chữ Nôm thì trước hết phải biết chữ Hán đã, vì mọi bộ phận đều lấy từ đó ra. Học một thứ chữ mà phải học xong một thứ chữ khác trước, nên chữ Nôm chưa bao giờ phổ cập được, dù Truyện Kiều và rất nhiều tác phẩm lớn nhất của ta đều viết bằng nó. Một hệ chữ hay tới đâu mà khó học quá thì cũng không đi xa được.","The difficulty was this: to read chu Nom you first had to know Chinese, since every component came from it. A script that requires another script to be learned first never became widespread, although the Tale of Kieu and many of our greatest works are written in it. However fine a writing system is, one too hard to learn does not travel far."]],["Một hệ thống chữ viết cạnh tranh với nhau không chỉ bằng độ chính xác mà bằng công sức để học. Cái dễ học thường thắng cái ghi đúng hơn.","Writing systems compete not only on precision but on the labour of learning them. The easier system usually beats the more exact one."],["Bẫy: tưởng chữ Nôm là chữ Hán, vì nhìn giống hệt. Người biết chữ Hán mà chưa học Nôm thì đọc một trang Nôm sẽ ra một chuỗi chữ vô nghĩa, vì âm đọc là âm tiếng Việt chứ không phải tiếng Hán.","The trap: taking chu Nom for Chinese because it looks identical. Someone who reads Chinese but has not studied Nom will find a page of it meaningless, because the sounds it records are Vietnamese, not Chinese."],["Hỏi ở nhà: trong nhà mình có ai từng nhìn thấy chữ Nôm ở đâu chưa?","Ask at home: has anyone here ever seen chu Nom written anywhere?"]),n("tu-muon-tieng-anh",2,["Nhận ra từ mượn trong câu nói hằng ngày và đoán nó tới từ đâu.","Spot borrowed words in everyday speech and guess where they came from."],[["Xà phòng, ga, sốp-phơ, cà phê — bốn từ này đều mượn của tiếng Pháp.","Soap, gas, chauffeur, coffee — in Vietnamese all four are French loans."],["Ti-vi, in-tơ-nét, sếp, phông — mượn của tiếng Anh, và mượn gần đây hơn nhiều.","Television, internet, chief, font — English loans, and much more recent ones."],['Mượn xong thì tiếng Việt uốn lại cho vừa miệng mình: "savon" thành "xà phòng", hai âm tiết thành ba, vì tiếng Việt không quen kết thúc âm tiết bằng phụ âm kép. Điều đáng nói là không tiếng nào tự làm ra hết vốn từ của mình, và mượn không hề làm một thứ tiếng nghèo đi — tiếng Anh mượn từ tiếng Pháp còn nhiều hơn tiếng Việt mượn từ tiếng Hán.',"Once borrowed, Vietnamese bends each word to fit its own mouth: savon becomes xa phong, two syllables becoming three, because Vietnamese dislikes ending a syllable in a consonant cluster. What is worth saying is that no language makes all its own vocabulary, and borrowing impoverishes nothing — English borrowed more from French than Vietnamese ever borrowed from Chinese."]],["Ngôn ngữ đi theo hàng hoá và theo người. Nhìn một lớp từ mượn là nhìn thấy một quãng lịch sử: ai tới, mang gì tới, và ở lại bao lâu.","Language travels with goods and with people. A layer of loanwords is a stretch of history: who came, what they brought, and how long they stayed."],['Bẫy: nghĩ từ mượn là từ "không thuần Việt" nên kém sang. Rất nhiều từ ta tưởng là thuần Việt thật ra đã mượn từ nghìn năm trước, chỉ vì mượn lâu quá nên không ai nhận ra nữa.',"The trap: treating loanwords as impure and second-rate. A great many words we take for native were borrowed a thousand years ago, and only their age keeps anyone from noticing."],["Hỏi ở nhà: trong bếp nhà mình có mấy đồ mà tên của nó là từ mượn?","Ask at home: how many things in our kitchen have borrowed names?"]),n("sau-thanh-dieu",2,["Nói được vì sao đổi dấu là đổi hẳn nghĩa của một từ.","Say why changing a tone mark changes a word’s meaning outright."],[["Ma, mà, má, mả, mã, mạ. Sáu từ, sáu nghĩa khác hẳn nhau.","Six Vietnamese words differing only in tone mean six entirely different things."],["Chúng chỉ khác nhau ở cao độ của giọng khi phát âm. Trong tiếng Việt, cao độ là một phần của từ.","They differ only in the pitch of the voice. In Vietnamese, pitch is part of the word itself."],["Đây là chỗ người học tiếng Việt vất vả nhất, vì trong tiếng Anh hay tiếng Pháp cao độ chỉ dùng để hỏi hay để tỏ thái độ, chứ không bao giờ đổi nghĩa. Nhưng đổi lại, tiếng có thanh điệu chở được nhiều nghĩa hơn trong cùng một số âm tiết — nên tiếng Việt gọn hơn tiếng Anh rất nhiều, và một câu tiếng Việt dịch ra tiếng Anh gần như bao giờ cũng dài hơn.","This is where learners of Vietnamese struggle most, because in English and French pitch only asks questions or shows feeling and never changes meaning. In exchange, a tonal language carries more meanings in the same number of syllables — so Vietnamese is far more compact than English, and a Vietnamese sentence translated almost always comes out longer."]],["Mỗi thứ tiếng chọn dùng một loại khác biệt âm thanh để phân biệt từ. Không loại nào tốt hơn loại nào, chỉ là mỗi tiếng chọn một chỗ để làm việc nặng.","Every language picks some kind of sound difference to keep words apart. None is better than another; each simply chooses where the heavy work is done."],['Bẫy: nghĩ dấu thanh là thứ trang trí thêm vào cho đẹp, bỏ đi vẫn hiểu. Bỏ dấu thì "ma", "má" và "mạ" thành một, và người đọc phải đoán bằng ngữ cảnh — đọc được, nhưng chậm hơn hẳn và có lúc đoán sai.',"The trap: treating tone marks as decoration that can be dropped without loss. Strip them and several distinct words collapse into one, leaving the reader to guess from context — possible, but far slower, and sometimes wrong."],["Hỏi ở nhà: cả nhà thử tìm một từ khác nữa mà đổi dấu là đổi hẳn nghĩa?","Ask at home: can we find another word where changing the tone changes everything?"]),n("tu-lay",1,["Nhận ra từ láy trong câu và nói nó thêm cái gì vào nghĩa.","Spot a reduplicated word in a sentence and say what it adds."],[["Lung linh, lấp lánh, rì rào, xào xạc.","Vietnamese has words built by repeating part of a syllable."],["Hai tiếng trong mỗi từ giống nhau một phần. Đó gọi là từ láy, và tiếng Việt có rất nhiều.","The two halves of each echo one another. These are reduplicated words, and Vietnamese is full of them."],['Từ láy không chỉ để cho đẹp. Nó thường tả một thứ kéo dài hoặc lặp đi lặp lại: gió không thổi một cái rồi thôi mà "rì rào" suốt buổi, ánh sáng không loé một phát mà "lấp lánh" liên tục. Cái lặp trong âm thanh đang bắt chước cái lặp trong sự việc — nên nghe một từ láy là nghe thấy hình dáng của việc nó tả.',"Reduplication is not mere ornament. It usually describes something drawn out or repeating: wind does not gust once but rustles all afternoon; light does not flash once but glitters continuously. The repetition in the sound imitates the repetition in the event — so hearing such a word is hearing the shape of what it describes."]],["Âm thanh của từ đôi khi mang chính hình dáng của cái nó tả. Đây là một trong số ít chỗ mà chữ không hoàn toàn tuỳ tiện, mà có dính dáng thật tới vật.","Sometimes the sound of a word carries the shape of what it names. This is one of the few places where words are not wholly arbitrary but genuinely touch the thing."],['Bẫy: cứ hai tiếng giống nhau là gọi từ láy. "Cha cha" hay "ba ba" lặp mà không phải láy theo nghĩa này, còn "mập mờ" thì hai tiếng khác nhau khá nhiều mà vẫn là láy — cái quyết định là quan hệ âm, không phải mắt nhìn.',"The trap: calling any doubled syllable reduplication. Some repeats are not, and some pairs that look quite different are — what decides is the relation between the sounds, not what the eye sees."],["Hỏi ở nhà: bố mẹ nói giúp con một từ láy tả tiếng mưa được không?","Ask at home: can you give me a reduplicated word for the sound of rain?"]),n("cau-co-chu-ngu",2,["Chỉ ra ai làm và làm gì trong một câu, và nhận ra câu đang thiếu chỗ nào.","Point out who does what in a sentence, and notice when a piece is missing."],[['"Con mèo ngủ." Câu này đủ: có ai đó, và có việc họ làm.',"The cat sleeps. That is complete: somebody, and something they do."],['"Đang ngủ trên mái nhà." Câu này thiếu: có việc, mà không biết ai đang làm.',"Sleeping on the roof. That is incomplete: an action, with nobody doing it."],['Trong tiếng Việt, chủ ngữ hay bị bỏ đi khi ai cũng biết đang nói về ai — hỏi "ăn cơm chưa?" thì không cần nói "con đã ăn cơm chưa". Nhưng khi viết cho người lạ đọc, người ấy không có mặt lúc mình nói nên không đoán ra được. Đó là lý do văn nói bỏ chủ ngữ thoải mái còn văn viết thì phải cẩn thận: viết là nói với một người mình không nhìn thấy.',"Vietnamese drops the subject freely when everyone knows who is meant — asking whether someone has eaten needs no pronoun at all. But writing for a stranger, that person was not present when you spoke and cannot fill the gap. This is why speech may drop subjects casually while writing must be careful: to write is to speak to somebody you cannot see."]],["Câu đủ hay thiếu không phải luật ngữ pháp cho vui, nó là câu hỏi người đọc có dựng lại được ý mình không. Người đọc càng xa mình thì càng phải nói rõ.","Whether a sentence is complete is not a rule for its own sake but a question of whether a reader can rebuild your meaning. The further away the reader, the more must be said."],["Bẫy: viết y như lúc nói rồi tưởng ai đọc cũng hiểu. Lúc nói còn có mặt mũi, giọng điệu và hoàn cảnh giúp đỡ; trên trang giấy thì chỉ còn chữ, và chữ phải gánh hết phần việc của cả ba thứ kia.","The trap: writing exactly as you speak and assuming it carries. Speech has a face, a tone and a shared situation to help; on the page only the words remain, and they must do the work of all three."],["Hỏi ở nhà: bố mẹ đọc thử câu này xem có hiểu con đang nói về ai không?","Ask at home: read this sentence — can you tell who I am talking about?"]),n("vi-sao-thang-tran",3,["Giải thích một trận thắng bằng chỗ đánh và lúc đánh, không bằng ai khoẻ hơn.","Explain a victory by ground and timing rather than by who was stronger."],[["Ba lần quân Nguyên sang, ba lần thua. Không lần nào ta đông quân hơn.","Three Mongol invasions, three defeats. Never once were we the larger army."],["Trần Hưng Đạo không đánh trực diện: ông rút, để giặc đi sâu vào chỗ không có lương.","Tran Hung Dao refused a head-on fight: he withdrew and let the enemy march deep into country with no food."],["Ở Bạch Đằng thì Ngô Quyền dùng chính con nước: cắm cọc dưới lòng sông, đợi triều lên cho thuyền giặc vào, rồi đợi triều xuống cho thuyền mắc cọc. Cả hai trận đều không thắng bằng sức mà thắng bằng việc chọn được chỗ đánh và lúc đánh — tức là bắt hoàn cảnh đánh hộ mình. Đó là điều người ta gọi là binh pháp, và nó cũng đúng ngoài chiến trận: chọn đúng chỗ và đúng lúc thường quan trọng hơn cố gắng nhiều hơn.","At Bach Dang, Ngo Quyen used the tide itself: stakes driven into the riverbed, the fleet let in on the flood, and the ebb left it impaled. Neither battle was won by force but by choosing the ground and the hour — that is, by making circumstance do the fighting. This is what strategy means, and it holds off the battlefield too: the right place and the right moment usually beat trying harder."]],["Kết quả của một cuộc đọ sức không chỉ do hai bên mạnh yếu, mà do điều kiện xung quanh. Ai chọn được điều kiện thì đã thắng trước khi đánh.","The outcome of a contest is not decided by the two sides alone but by the conditions around them. Whoever chooses the conditions has already won before it starts."],["Bẫy: kể sử theo kiểu bên nào chính nghĩa thì bên ấy thắng. Chính nghĩa giúp giữ được lòng người và giữ được lâu, nhưng nó không tự cắm cọc xuống sông, và trận nào cũng phải có người tính đúng con nước.","The trap: telling history as though the just side wins. Justice holds people together and holds them long, but it does not drive stakes into a riverbed, and every battle still needs somebody who reads the tide correctly."],["Hỏi ở nhà: bố mẹ có biết vì sao lại đóng cọc ở sông Bạch Đằng không?","Ask at home: do you know why stakes were driven into the Bach Dang river?"]),n("thoi-tu-chu",3,["Đặt năm 938 vào đúng chỗ của nó trong dòng sử nước mình.","Put the year 938 in its right place in our country’s current."],[["Từ năm 111 trước Công nguyên tới năm 938, nước ta bị phương Bắc cai trị.","From 111 BC to AD 938 our country was ruled from the north."],["Hơn một nghìn năm liền. Quãng ấy còn dài hơn cả quãng từ năm 938 tới hôm nay.","More than a thousand years — longer than the whole stretch from 938 until today."],["Điều đáng kinh ngạc không phải là mất nước một nghìn năm, mà là sau một nghìn năm ấy tiếng Việt vẫn còn. Rất nhiều dân tộc bị cai trị ngắn hơn thế đã mất hẳn tiếng nói của mình. Tiếng Việt mượn rất nhiều từ tiếng Hán — khoảng sáu trên mười từ trong sách vở — nhưng ngữ pháp và những từ thường ngày nhất thì giữ nguyên, và đó chính là cái lõi không mất.","The astonishing thing is not a thousand years of foreign rule but that Vietnamese survived them. Many peoples ruled for far shorter lost their language entirely. Vietnamese borrowed enormously from Chinese — perhaps six words in ten in formal writing — yet its grammar and its most everyday words held, and that is the core that was never lost."]],["Một dân tộc giữ được mình không phải bằng cách từ chối mọi thứ vay mượn, mà bằng cách giữ được cái lõi trong lúc vẫn mượn rất nhiều ở lớp ngoài.","A people keeps itself not by refusing everything borrowed but by holding its core intact while borrowing freely at the surface."],["Bẫy: nghĩ nghìn năm Bắc thuộc là nghìn năm đứng yên. Trong quãng ấy có hàng chục cuộc khởi nghĩa, có Hai Bà Trưng, có Bà Triệu, có Lý Bí lập nước Vạn Xuân — sử chép thưa không có nghĩa là chuyện xảy ra thưa.","The trap: imagining those thousand years as a thousand years of stillness. They held dozens of risings, the Trung sisters, Ba Trieu, Ly Bi founding his own state — a thin record does not mean thin events."],["Hỏi ở nhà: nhà mình có ai nhớ năm 938 xảy ra chuyện gì không?","Ask at home: does anyone here remember what happened in the year 938?"]),n("kinh-do-o-dau",2,["Nói được vì sao một triều đại chọn chỗ này làm kinh đô chứ không chọn chỗ kia.","Say why a dynasty put its capital here rather than there."],[["Hoa Lư nằm giữa núi đá. Thăng Long nằm giữa đồng bằng.","Hoa Lu sits among limestone hills. Thang Long sits in the middle of the delta."],["Núi đá dễ giữ, khó đánh vào. Đồng bằng thì rộng, gần sông, tiện đi lại và buôn bán.","Hills are easy to hold and hard to attack. A delta is broad, close to rivers, and good for travel and trade."],["Nên năm 1010 Lý Công Uẩn dời đô từ Hoa Lư ra Thăng Long, và trong chiếu dời đô ông nói thẳng lý do: đất ấy rộng và bằng, hợp cho một nước đang lớn. Đổi kinh đô là đổi cả cách nghĩ về đất nước — từ chỗ lo giữ mình sang chỗ tính chuyện làm ăn lâu dài. Nhà Nguyễn sau này lại chọn Huế, vì lúc ấy nước đã dài từ Bắc tới Nam và kinh đô cần nằm ở khoảng giữa.","So in 1010 Ly Cong Uan moved the capital from Hoa Lu to Thang Long, and his edict gives the reason plainly: broad flat land, fit for a country that was growing. Changing a capital changes how a country thinks of itself — from guarding itself to planning for the long run. The Nguyen later chose Hue, because by then the country ran from north to south and its capital needed to sit in the middle."]],["Chỗ đặt kinh đô nói ra điều một triều đại đang lo nhất. Lo bị đánh thì chọn chỗ hiểm; lo làm ăn thì chọn chỗ tiện; lo giữ hai đầu thì chọn chỗ giữa.","Where a capital stands says what a dynasty most fears. Fear of attack chooses defensible ground; hope of trade chooses convenient ground; the need to hold two ends chooses the middle."],["Bẫy: nghĩ kinh đô là nơi đẹp nhất hay thiêng nhất. Đôi khi đúng, nhưng lý do quyết định gần như bao giờ cũng rất thực tế: đường đi, nguồn nước, chỗ hiểm, và khoảng cách tới nơi mình sợ.","The trap: assuming a capital marks the finest or holiest place. Sometimes it does, but the deciding reasons are almost always practical: roads, water, defensible ground, and distance from whatever is feared."],["Hỏi ở nhà: nhà mình chọn ở chỗ này vì lý do gì?","Ask at home: why did our family choose to live in this particular place?"]),n("cay-di-vong-quanh",3,["Kể ra ba thứ trong bữa cơm nhà mình vốn không phải của xứ mình.","Name three things on our table that did not originally grow here."],[["Ngô, khoai lang, ớt, cà chua, lạc — cả năm thứ này đều từ châu Mỹ sang.","Maize, sweet potato, chilli, tomato and peanut all came from the Americas."],["Chúng chỉ tới châu Á sau năm 1492, tức là muộn hơn Truyện Kiều chưa đầy ba trăm năm.","They reached Asia only after 1492 — less than three centuries before the Tale of Kieu."],['Nghĩa là món ăn ta coi là "truyền thống" phần lớn còn trẻ hơn ta tưởng rất nhiều. Trước đó bữa cơm Việt không có ớt, không có ngô, không có lạc rang. Chiều ngược lại cũng thế: người châu Âu không có trà, không có lụa, không có thuốc súng cho tới khi hàng từ châu Á sang. Cái ta gọi là bản sắc thường là kết quả của một lần trao đổi, chỉ vì lần ấy xảy ra đủ lâu nên không ai nhớ nữa.',"Which means the food we call traditional is often much younger than we assume. Before that, a Vietnamese meal had no chilli, no maize, no roasted peanuts. The traffic ran the other way too: Europe had no tea, no silk and no gunpowder until goods came from Asia. What we call identity is often the residue of one exchange, long enough ago that nobody remembers it."]],["Không có nền văn hoá nào lớn lên một mình. Cái riêng của mỗi nơi phần lớn là cách nơi ấy dùng những thứ vay mượn, chứ không phải danh sách những thứ nó tự có.","No culture grew up alone. What is distinctive about a place is mostly how it uses what it borrowed, not a list of what it originally held."],["Bẫy: thấy một món ăn có từ đời ông bà là gọi luôn là cổ truyền nghìn năm. Ba đời người là khoảng một trăm năm, mà nghìn năm là ba mươi đời — khoảng cách ấy lớn hơn nhiều so với cảm giác.","The trap: calling a dish thousand-year-old tradition because grandparents ate it. Three generations is about a century, while a thousand years is thirty — a far larger gap than it feels."],["Hỏi ở nhà: bữa cơm tối nay có món nào gốc ở nước khác không?","Ask at home: is there anything in tonight’s dinner that came from another country?"]),n("benh-di-theo-nguoi",4,["Nói được vì sao dịch bệnh đi theo đường buôn chứ không đi theo gió.","Say why epidemics travel along trade roads rather than on the wind."],[["Bệnh truyền nhiễm cần người mang nó đi. Nó không tự bay qua biển được.","An infectious disease needs somebody to carry it. It cannot cross a sea by itself."],["Nên bản đồ các trận dịch lớn trong lịch sử trùng gần khít với bản đồ các con đường buôn.","So a map of history’s great epidemics matches the map of its trade roads almost exactly."],["Cái chết Đen giữa thế kỷ 14 đi từ Trung Á theo đường tơ lụa sang châu Âu và giết khoảng một phần ba dân số ở đó. Ba trăm năm sau, đậu mùa theo tàu châu Âu sang châu Mỹ và giết phần lớn dân bản địa — không phải bằng vũ khí mà bằng vi trùng, vì người ở đó chưa từng gặp căn bệnh ấy nên trong người không có sức chống. Cùng một con đường chở lụa, chở ngô, chở vàng thì cũng chở cả bệnh, và không ai lúc ấy biết mình đang chở gì.","The Black Death of the mid fourteenth century travelled the silk roads from Central Asia into Europe and killed perhaps a third of its people. Three centuries later smallpox crossed on European ships to the Americas and killed most of the native population — not by weapons but by germs, because those people had never met the disease and carried no defence against it. The same road that carried silk, maize and gold carried illness too, and nobody aboard knew what they were carrying."]],["Mọi thứ nối con người lại với nhau đều nối theo cả hai chiều tốt xấu. Đường buôn mang hàng, mang chữ, mang giống cây — và mang cả những thứ không ai muốn mang.","Everything that connects people connects in both directions. Trade roads carry goods, writing and seeds — and also what nobody meant to carry."],["Bẫy: nghĩ dịch bệnh là chuyện của thời chưa có thuốc. Thời nay máy bay làm quãng đường ngắn lại còn vài giờ, nên một mầm bệnh mới đi vòng quanh thế giới nhanh hơn nhiều so với mọi thế kỷ trước.","The trap: filing epidemics under the age before medicine. Aircraft have shortened those roads to hours, so a new pathogen now circles the world far faster than in any earlier century."],["Hỏi ở nhà: bố mẹ nhớ hồi có dịch, nhà mình đã thay đổi những gì?","Ask at home: during the epidemic, what did our family actually change?"]),n("kim-loai-doi-doi",3,["Nói được vì sao một thứ kim loại lại đủ sức đặt tên cho cả một thời đại.","Say why one metal can give its name to an entire age."],[["Thời đại đồ đá, thời đại đồ đồng, thời đại đồ sắt. Tên thời đại đặt theo vật liệu.","Stone age, bronze age, iron age. Whole eras named after a material."],["Vì đổi vật liệu là đổi hết: đổi cách làm ruộng, cách đánh nhau, và đổi cả ai là người mạnh.","Because changing the material changes everything: how you farm, how you fight, and who ends up powerful."],["Đồng cần thiếc, mà thiếc thì rất ít nơi có — nên thời đồ đồng, ai kiểm soát đường buôn thiếc thì mạnh, và đồ đồng luôn là của người giàu. Sắt thì có gần như khắp nơi, chỉ khó ở chỗ phải nung thật nóng. Khi người ta biết cách nung, nông dân bình thường cũng có cày sắt, và điều ấy làm ruộng đất mở rộng ra rất nhanh. Một thay đổi trong lò rèn kéo theo một thay đổi trong bữa ăn của hàng triệu người.","Bronze needs tin, and tin lies in few places — so in the bronze age whoever held the tin roads held power, and bronze belonged to the rich. Iron is nearly everywhere; the difficulty is only the heat required. Once that heat was mastered, ordinary farmers had iron ploughs, and farmland spread very fast. One change in the forge became a change in what millions ate."]],["Kỹ thuật đổi thì quyền lực đổi theo, vì quyền lực thường nằm ở chỗ ai nắm được thứ hiếm. Cái gì trở nên sẵn thì hết làm người ta mạnh.","When technique changes, power moves, because power usually sits with whoever holds the scarce thing. What becomes common stops making anyone strong."],["Bẫy: nghĩ kim loại tốt hơn thì lập tức thay được kim loại cũ. Đồ đồng còn dùng song song với đồ sắt hàng trăm năm, vì thợ quen tay, vì lò chưa đủ nóng, và vì đồ cũ vẫn chạy tốt — cái mới hiếm khi thắng ngay.","The trap: assuming a better metal replaces the old one at once. Bronze ran alongside iron for centuries, because smiths knew their craft, because furnaces were not hot enough, and because the old tools still worked — the new rarely wins immediately."],["Hỏi ở nhà: trong nhà mình có đồ gì bằng đồng không, và nó dùng để làm gì?","Ask at home: is there anything made of bronze or copper here, and what is it for?"]),n("viec-su-khong-chep",4,["Hỏi một câu về bất kỳ trang sử nào: ai đã không được chép vào đây?","Ask one question of any page of history: who was left out of it?"],[["Sử chép tên vua, tên tướng, tên năm. Sử ít chép tên người đắp đê.","History records kings, generals and dates. It rarely records who built the dyke."],["Không phải vì họ không quan trọng, mà vì người chép sử ngày xưa làm việc trong triều.","Not because they did not matter, but because the people who wrote history worked at court."],["Nên cái ta biết về quá khứ bị lọc qua chỗ ngồi của người chép: chuyện trong cung được ghi kỹ, chuyện ngoài đồng gần như im lặng. May là còn những nguồn khác biết nói: một con đê còn đó, một cái giếng, một bộ đồ nghề trong mộ, một bài ca dao truyền miệng. Khảo cổ học ra đời chính là để nghe những thứ không ai chép, và nhờ nó mà lịch sử của người thường mới dần dần có mặt.","So what we know of the past is filtered through where the recorder sat: palace affairs written closely, field affairs almost silent. Fortunately other sources speak: a dyke still standing, a well, a set of tools in a grave, a folk verse passed mouth to mouth. Archaeology exists precisely to hear what nobody wrote down, and through it the history of ordinary people has slowly arrived."]],["Mọi ghi chép đều do ai đó quyết định ghi. Nên đọc sử thì phải đọc cả cái vắng mặt, và cái vắng mặt thường nói nhiều hơn cái có mặt.","Every record exists because somebody decided to make it. So reading history means reading the absences too, and the absences often say more than the entries."],["Bẫy: không có bằng chứng thì kết luận là không có chuyện. Không tìm thấy dấu vết của một nghề nào đó có thể chỉ nghĩa là nghề ấy dùng đồ bằng tre bằng gỗ, mà tre gỗ thì mục hết sau vài trăm năm.","The trap: taking no evidence as evidence of nothing. Finding no trace of a craft may only mean it used bamboo and wood, and bamboo and wood rot away within a few centuries."],["Hỏi ở nhà: nhà mình có ai làm việc mà công của họ không ai ghi lại không?","Ask at home: does anyone here do work that nobody writes down anywhere?"]),n("nu-khoa-hoc",3,["Nói được vì sao rất ít tên phụ nữ trong sách khoa học ngày xưa.","Say why so few women’s names appear in the old science books."],[["Marie Curie được giải Nobel hai lần, ở hai ngành khác nhau.","Marie Curie won two Nobel prizes, in two different fields."],["Nhưng lúc bà bắt đầu, phần lớn các trường đại học ở châu Âu còn không nhận sinh viên nữ.","Yet when she began, most European universities would not admit women at all."],['Bà phải rời Ba Lan sang Pháp để được học. Nhiều người khác thì không có cách nào rời đi, nên công của họ hoặc mất hẳn hoặc đứng dưới tên chồng, tên anh, tên thầy. Nên khi thấy một danh sách toàn tên đàn ông, câu hỏi đúng không phải "vì sao phụ nữ không làm khoa học" mà là "ai đã bị chặn ở cửa, và ai đã làm mà không được ghi tên".',"She had to leave Poland for France to study at all. Many others had no way to leave, so their work either vanished or appeared under a husband’s, a brother’s or a supervisor’s name. So when a list holds only men, the right question is not why women did not do science but who was stopped at the door, and who did the work without their name on it."]],["Danh sách người nổi tiếng trong một ngành đo hai thứ cùng lúc: ai làm được việc, và ai được phép vào. Không tách hai thứ ấy ra thì đọc danh sách nào cũng sai.","A list of a field’s famous names measures two things at once: who could do the work and who was allowed in. Without separating them, any such list is misread."],["Bẫy: thấy ít tên nữ rồi kết luận về khả năng. Cứ mỗi lần một cánh cửa được mở ra, số tên nữ trong ngành ấy tăng lên rất nhanh — mà khả năng của con người thì không đổi nhanh như thế trong vài chục năm.","The trap: reading few women’s names as a statement about ability. Each time a door has opened, the number of women in that field has climbed quickly — and human ability does not change that fast in a few decades."],["Hỏi ở nhà: bà hay mẹ hồi bằng tuổi con thì được học tới lớp mấy?","Ask at home: when you were my age, how far were you able to go in school?"])],r=[n("goi-dung-ten",1,["Gọi tên được cơn đang xảy ra trong mình","Name the wave that is going through you"],[["Có hai kiểu từ rất dễ lẫn: từ gọi tên một cơn, và từ dán nhãn lên một người.","Two kinds of word are easy to mix up: words that name a wave, and words that label a person."],['"Tủi thân" là một cơn — nó tới, nó ở lại một lúc, rồi nó đi. "Hư" thì không đi đâu cả: nó dán lên người, và người mang nó thì không còn việc gì để làm với nó.',"Hurt is a wave — it arrives, it stays a while, it goes. Naughty goes nowhere: it sticks to a person, and a person wearing it has nothing left to do about it."],["Người ta đo được một chuyện lạ: chỉ cần gọi đúng tên cảm xúc đang có, cường độ của nó đã tụt xuống một phần. Không phải vì gọi tên là phép thuật, mà vì lúc đi tìm cái tên, phần biết nghĩ trong đầu bật lên làm việc — và nó vốn là phần đang tắt lúc cơn mạnh nhất.","Something odd has been measured: simply naming the feeling you are having drops its strength a notch. Not because naming is magic, but because the hunt for the word switches on the thinking part of the head — the very part that goes quiet when the wave is at its height."]],['Tên chính xác thì chọn được cách xử. "Khó chịu" thì chẳng biết làm gì với nó; "ghen tị vì bạn được khen" thì đã thấy ngay việc phải nói với ai và nói câu gì.','A precise name lets you choose a response. "Bad" gives you nothing to work with; "envious because they were praised" already shows who to speak to and what to say.'],["Chỗ dễ nhầm: người ta tưởng gọi tên cảm xúc xấu ra thì nó mạnh thêm, nên tránh nói. Đo được thì ngược lại — cái không được gọi tên mới là cái ở lại lâu nhất và bật ra ở chỗ không ai ngờ.","The easy mistake: people believe that naming an ugly feeling feeds it, so they avoid saying it. Measurement says the opposite — what goes unnamed is what stays longest and comes out somewhere nobody expected."],["Hôm nay bố mẹ có một lúc thấy khó chịu — cơn ấy tên là gì?","Was there a moment today when you felt off — what was that one called?"]),n("cam-xuc-va-viec",1,["Tách được cảm xúc ra khỏi việc mình làm","Tell a feeling apart from what you do about it"],[["Giận là một cảm xúc. Đánh bạn là một việc làm. Hai thứ ấy không phải một.","Being angry is a feeling. Hitting somebody is an action. They are not the same thing."],["Không ai chọn được mình giận hay không giận — cơn ấy tới trước khi mình kịp bàn với nó. Nhưng cái tay đưa lên thì có chọn, và giữa hai thứ ấy bao giờ cũng có một khoảng trống.","Nobody chooses whether to be angry — the wave arrives before there is anyone to consult. But the hand going up is chosen, and between the two there is always a gap."],['Người lớn hay nói "đừng giận". Câu ấy vô nghĩa, y như bảo một đứa đang đói rằng đừng đói. Câu nói được thì khác: giận thì cứ giận, nhưng lúc đang giận thì chưa nói, chưa nhắn, chưa quyết. Cả đời tập chỉ là tập giữ cho cái khoảng trống ấy đừng khép lại.','Grown-ups say "do not be angry". The sentence is empty, like telling a hungry child not to be hungry. Here is one that works: be as angry as you are, but while you are, do not speak, do not send, do not decide. The whole practice of a life is keeping that gap from closing.']],["Cảm xúc không đúng không sai, nó chỉ có hoặc không có. Việc làm thì có đúng có sai, vì việc làm chạm tới người khác. Nên chỗ để dạy và để tự sửa nằm ở việc làm, không nằm ở cơn.","A feeling is neither right nor wrong, it is only present or absent. An action can be right or wrong, because an action touches other people. So the place for teaching and for self-repair is the action, never the wave."],["Chỗ dễ nhầm: đứa trẻ nào cũng có lúc nghe rằng mình không được phép giận, và học được rằng cơn giận là bằng chứng mình xấu. Nó không giấu được cơn, nó chỉ giấu được việc nói ra.","The easy mistake: most children are told at some point that they may not be angry, and learn that anger is evidence of being bad. They cannot hide the wave — they only learn to hide the telling."],["Hồi bằng tuổi con, bố mẹ giận nhất chuyện gì, và lúc ấy đã làm gì?","At my age, what made you angriest — and what did you do about it?"]),n("viec-lam-diu",1,["Mua được vài phút cho một cơn đi qua","Buy the few minutes a wave needs to pass"],[["Cơn giận nào cũng có một cái đỉnh, và cái đỉnh ấy hẹp hơn mình tưởng.","Every rage has a peak, and the peak is narrower than it feels."],["Qua được vài phút là nó tự tụt, không cần ai làm gì cả. Nên việc phải làm lúc ấy không phải là giải quyết chuyện — mà là mua đủ mấy phút để cái đỉnh trôi qua.","A few minutes past it and it falls on its own, with nobody doing anything. So the job at that moment is not to settle the matter — it is to buy the minutes the peak needs to pass."],["Uống nước, đi ra sân, rửa mặt, đếm chậm, thở ra dài hơn thở vào: năm việc ấy không giải quyết gì hết, và đó chính là điểm mạnh của chúng. Chúng chỉ làm đúng một việc là kéo dài thời gian, mà thời gian thì lại là toàn bộ thứ cơn giận cần để tự hết.","A drink of water, stepping outside, cold water on the face, counting slowly, breathing out longer than in: none of the five settles anything, and that is exactly their strength. They do one job only, which is to stretch time — and time is the entire thing a rage needs in order to end."]],["Thở ra dài hơn thở vào là cái nút duy nhất bấm được bằng tay: nhịp thở chậm báo ngược lên não rằng không có gì đang đuổi mình, và cái chuông báo động vặn nhỏ lại theo.","Breathing out longer than in is the one switch you can press by hand: a slow rhythm reports back up to the brain that nothing is chasing you, and the alarm turns itself down to match."],["Chỗ dễ nhầm: người ta tưởng phải nói cho ra nhẽ ngay lúc đang nóng, không thì ấm ức. Thật ra câu nói ra lúc ấy hầu như luôn là câu phải xin lỗi sau, và cái ấm ức thì đến từ đó chứ không từ việc chờ.","The easy mistake: people believe the thing must be thrashed out while it is hot or the hurt will fester. In fact the sentence produced then is nearly always the one that needs an apology later, and that is where the festering starts."],["Lúc bực nhất, bố mẹ hay làm gì để dịu lại?","When you are at your angriest, what do you do to come down?"]),n("noi-voi-ai",1,["Biết trước ai là người kể được lúc có chuyện","Know in advance who you can tell when something is wrong"],[["Có chuyện thì phải kể — và người kể nên được chọn trước, không phải chọn lúc đang hoảng.","When something is wrong it must be told — and the person should be chosen beforehand, not while panicking."],["Ba dấu hiệu của một người kể được: mình biết mặt họ ngoài đời, họ có trách nhiệm với mình, và họ ở lại kể cả khi chuyện xấu. Thiếu một trong ba thì chưa đủ.","Three marks of somebody you can tell: you know their face in real life, they are answerable for you, and they stay when the news is bad. Missing one of the three is not enough."],['Người trên mạng có thể tử tế thật, nhưng không có cái nào trong ba dấu hiệu ấy. Và người có ý xấu thì bao giờ cũng bắt đầu bằng việc rất tử tế, rất chịu nghe, rất hiểu mình — rồi tới một lúc họ dặn "đừng kể cho ai". Câu dặn ấy chính là dấu hiệu duy nhất cần nhớ: ai bảo con giấu một chuyện với bố mẹ, chuyện ấy phải kể ngay.','Somebody online may genuinely be kind, but has none of the three marks. And people meaning harm always begin by being very kind, very willing to listen, very understanding — until the moment they say "do not tell anyone". That instruction is the one signal worth memorising: whoever asks you to keep something from your parents is the thing to report first.']],["Kể ra không phải là mách. Mách là kể để người khác bị phạt; kể là đưa một việc quá nặng cho người có sức mang nó. Một đứa mười tuổi không có sức mang một chuyện của người lớn, và không ai bắt nó phải có.","Telling is not telling tales. Telling tales is speaking so somebody gets punished; telling is handing something too heavy to a person strong enough to carry it. A ten-year-old does not have the strength for an adult-sized problem, and nobody requires them to."],["Chỗ dễ nhầm: trẻ hay im vì sợ bị mắng thêm, nên chuyện nhỏ giấu thành chuyện to. Người lớn nào muốn được kể thì phải trả giá: lần đầu nghe tin xấu mà không nổi giận, đó là lần quyết định có lần thứ hai hay không.","The easy mistake: children stay quiet for fear of being told off twice over, so a small thing grows into a large one. Any grown-up who wants to be told pays for it in one moment: hearing bad news the first time without anger is what decides whether there is a second time."],["Hồi bé, có chuyện gì bố mẹ đã giấu ông bà không?","When you were small, was there something you kept from your own parents?"]),n("thoi-quen-so-phut",1,["Đặt một thói quen mới nhỏ đủ để nó sống","Set a new habit small enough to survive"],[["Thói quen mới hỏng vì đặt to quá, không phải vì lười.","New habits fail from being set too big, not from laziness."],["Chín mươi phút mỗi tối nghe rất quyết tâm. Nhưng chỉ cần một hôm mệt, một hôm nhà có khách, là đứt — và đứt một lần thì thường đứt luôn.","Ninety minutes every evening sounds impressively determined. But one tired day, one evening with visitors, and the chain breaks — and a chain broken once usually stays broken."],["Năm phút thì hôm mệt vẫn làm được, hôm đi chơi về muộn vẫn làm được. Nghe thì ít, nhưng cái đáng giá của một thói quen không nằm ở độ dài mỗi buổi — nó nằm ở chỗ không đứt. Một việc làm đủ ba tuần liền sẽ tự dài ra, còn một việc bỏ dở tuần đầu thì không bao giờ có cơ hội dài ra cả.","Five minutes survives a tired day and a late night out. It sounds like nothing, but the value of a habit is not in the length of each sitting — it is in the chain staying unbroken. Something done three weeks running lengthens itself, while something abandoned in week one never gets the chance."]],["Ba tuần đầu, việc phải giữ không phải là số lượng mà là chuỗi ngày. Nên đặt mức thấp tới mức không thể lỡ được là một tính toán đúng, không phải một cách tự tha cho mình.","For the first three weeks the thing to protect is the run of days, not the amount. So setting the bar low enough that missing is impossible is sound arithmetic, not going easy on yourself."],["Chỗ dễ nhầm: hôm đầu bao giờ cũng hăng, nên người ta đặt mức theo sức của hôm hăng nhất. Mức đúng phải đặt theo sức của hôm tệ nhất — vì chính hôm tệ nhất mới là hôm quyết định chuỗi có đứt hay không.","The easy mistake: day one always feels strong, so the bar gets set at the strength of the strongest day. The right bar is set at the strength of the worst day, because the worst day is the one that decides whether the chain breaks."],["Bố mẹ có việc gì làm đều đặn được nhiều năm không — bắt đầu nó thế nào?","Is there anything you have kept up for years — how did it start?"]),n("moc-treo-thoi-quen",2,["Treo việc mới vào một việc đã có sẵn","Hang a new task on one you already do"],[["Cách chắc nhất để nhớ một việc mới là đừng nhờ trí nhớ làm việc ấy.","The surest way to remember a new task is not to ask memory to do it."],['"Khi nào rảnh thì tập" nghe rất hợp lý mà không bao giờ chạy, vì nó giao cho trí nhớ đúng cái việc trí nhớ dở nhất: tự nhắc mình đúng lúc.','"I will do it when I have time" sounds reasonable and never happens, because it hands memory the one job memory is worst at: prompting itself at the right moment.'],["Treo vào một mốc có sẵn thì khác hẳn: đánh răng xong thì đọc năm phút, ăn cơm xong thì dọn bàn, đặt cặp xuống thì lấy vở ra. Cái việc cũ đã tự động rồi, nên nó kéo cái việc mới đi theo mà không tốn một chút cố gắng nào.","Hanging it on an existing peg is another matter: after brushing teeth, read five minutes; after dinner, clear the table; the moment the bag lands, the book comes out. The old task is already automatic, so it tows the new one along at no cost in effort."],["Nghe thì nhỏ nhặt, nhưng đây là chỗ tách người làm được với người mãi định làm. Ý chí là thứ hết dần trong ngày, ngày nào cũng hết, còn một cái mốc thì không mệt bao giờ — nó ở đúng chỗ ấy mỗi sáng, không cần ai nhắc, không cần ai quyết tâm gì cả.","It sounds trivial, and it is the line between people who do a thing and people who keep meaning to. Willpower drains over a day, every day, while a peg never tires — it sits in the same place each morning, needing no reminder and no fresh resolve."]],["Một thói quen thật ra là ba mảnh: cái mốc, việc làm, và cái được sau đó. Thiếu mốc thì hai mảnh kia có tốt mấy cũng không tự khởi động được, nên chỗ phải sửa đầu tiên luôn là cái mốc.","A habit is really three pieces: the cue, the action, and what comes after. Without a cue the other two cannot start themselves however good they are, so the first thing to repair is always the cue."],["Chỗ dễ nhầm: người ta đổ tại mình thiếu quyết tâm, rồi hứa lần nữa. Hứa lần nữa là làm lại đúng cái đã hỏng — thứ phải đổi là chỗ treo, không phải mức quyết tâm.","The easy mistake: people blame their own weak resolve and promise again. Promising again repeats exactly what failed — what has to change is where the task hangs, not how hard the promising is."],["Buổi sáng nhà mình có mốc nào đã cố định sẵn rồi?","What is already fixed in our mornings, every single day?"]),n("trong-tay-minh",2,["Chia được cái mình nắm và cái mình không nắm","Sort what you hold from what you do not"],[["Có hai cột, và gần như mọi cái mệt của một người tới từ chỗ xếp lẫn hai cột.","There are two columns, and nearly all of a person’s exhaustion comes from mixing them up."],["Cột trái là thứ mình nắm: giờ đi ngủ, lời mình nói, việc mình làm, chỗ mình ngồi. Cột phải là thứ mình không nắm: thời tiết, điểm của bạn, ý người khác nghĩ về mình.","The left column is what you hold: your bedtime, your own words, your own effort, where you sit. The right is what you do not: the weather, somebody else’s marks, what other people think of you."],["Lo cho cột phải thì lo bao nhiêu cũng không xê dịch nó một li — mà sức thì hết thật, và hết đúng phần sức đáng lẽ dùng cho cột trái. Đó là lý do một người có thể vừa lo lắng cả tuần vừa không làm được gì cả, rồi tự kết luận rằng mình lười.","Worrying about the right column does not move it a millimetre — while the strength spent is genuinely spent, and spent out of the same purse the left column needed. That is how somebody can worry all week, achieve nothing, and conclude they are lazy."],["Cách dùng thì rất khô khan, và chính vì khô khan nên nó chạy được: viết cả chuyện đang lo ra giấy, gạch một đường dọc xuống giữa trang, rồi xếp từng mảnh một về đúng cột của nó. Xong rồi thì cột bên trái là việc của hôm nay, làm ngay được, làm xong thấy nhẹ thật. Còn cột bên phải thì chỉ có đúng một việc duy nhất được phép làm với nó — chuẩn bị sẵn cho trường hợp xấu nhất, rồi gấp tờ giấy lại và thôi.","The method is dry, and because it is dry it works: write the whole worry out on paper, draw a line down the middle of the page, then move each piece across into the column it belongs in. What ends up on the left is today’s work, it can be started at once, and finishing any of it genuinely lightens the load. What ends up on the right allows exactly one action and no more — prepare for the worst case, then fold the paper up and leave it there."]],["Cột phải không phải là chỗ để mặc kệ, nó là chỗ để chuẩn bị. Mang áo mưa là việc của cột trái; bắt trời đừng mưa thì không phải việc của ai cả.","The right column is not a place for shrugging, it is a place for preparing. Packing a raincoat belongs to the left column; ordering the sky not to rain belongs to nobody."],['Chỗ dễ nhầm: nhiều thứ nhìn thì tưởng ở cột phải mà thật ra ở cột trái — ví dụ "được bạn quý" thì không nắm được, nhưng "rủ bạn đi cùng" thì nắm được, và cái thứ hai kéo cái thứ nhất theo.',"The easy mistake: several things look like the right column and are really the left — being liked, for instance, is not yours to hold, while asking somebody along is, and the second one drags the first behind it."],["Tuần này bố mẹ đang lo chuyện gì — nó nằm ở cột nào?","What are you worrying about this week — which column is it in?"]),n("xin-loi-that",2,["Lắp được một lời xin lỗi thật","Build an apology that actually works"],[["Một lời xin lỗi thật gồm ba mảnh, và có đúng một chữ xoá sạch cả câu.","A real apology has three pieces, and there is one word that deletes the whole thing."],["Ba mảnh: nói đúng mình đã làm gì, sửa được gì thì sửa, và lần sau làm khác đi. Không mảnh nào trong ba mảnh ấy nói tới cảm giác của người xin lỗi cả.","The three pieces: say exactly what you did, repair what can be repaired, and next time do otherwise. None of the three mentions how the person apologising feels."],['Chữ xoá sạch cả câu là chữ "nhưng". "Xin lỗi vì tớ hét lên, nhưng cậu cũng có lỗi" — người nghe chỉ còn nghe được vế sau, và vế sau là một lời buộc tội. Chuyện này không phải chuyện phép lịch sự: đầu người giữ lại phần cuối của một câu, nên phần đứng sau chữ "nhưng" bao giờ cũng là phần ở lại.','The word that deletes it is "but". "Sorry I shouted, but you started it" — the listener keeps only the second half, and the second half is an accusation. This is not a matter of manners: heads retain the end of a sentence, so whatever stands after "but" is what remains.'],['Còn một mảnh nữa hay bị bỏ quên: hỏi người kia cần gì. Người xin lỗi thường tự quyết cách đền, mà cách ấy hợp với mình chứ chưa chắc hợp với người bị làm đau. Một câu "tớ làm gì cho đỡ được" ngắn hơn mọi lời giải thích, và nó trả lại cho người kia phần quyết định mà chính mình vừa lấy đi.','One piece is usually forgotten: asking what the other person needs. People apologising tend to choose the repair themselves, and the repair suits them rather than the person hurt. "What would help?" is shorter than any explanation, and it hands back the choice that was taken away in the first place.']],["Xin lỗi không phải để mình hết áy náy — nếu thế thì nó là việc làm cho mình. Nó là việc làm cho người kia, nên thước đo duy nhất là người kia thấy thế nào sau đó.","An apology is not for clearing your own conscience — that would make it a favour to yourself. It is for the other person, so the only measure is how they are afterwards."],["Chỗ dễ nhầm: người ta tưởng xin lỗi xong là chuyện khép lại ngay. Thường thì không: mảnh thứ ba — lần sau làm khác — mới là mảnh người kia đang chờ, và nó chỉ chứng minh được bằng lần sau, không bằng lời.","The easy mistake: people expect an apology to close the matter on the spot. Usually it does not: the third piece — doing otherwise next time — is the one being waited for, and it can only be shown by the next time, never by the words."],["Có lần nào bố mẹ xin lỗi con mà con vẫn thấy chưa xong không?","Has there been a time you said sorry to me and it still did not feel finished?"]),n("hoc-duoc-sau-cung",3,["Biết phần nào của cái đầu còn đang xây dở","Know which part of the head is still being built"],[["Cái đầu không xây xong cùng một lúc. Nó xây từ sau ra trước, và mất hơn hai mươi năm.","A head is not finished all at once. It is built from the back forwards, and takes over twenty years."],["Phần lo việc nhìn, nghe và sợ xong sớm — trẻ con sơ sinh đã sợ tiếng động lớn. Phần lo việc nhớ mặt và nói thành câu xong trước tuổi đi học.","The parts for seeing, hearing and fearing finish early — a newborn already startles at a loud noise. The parts for faces and for speech are done before school starts."],["Phần xong sau cùng là phần nằm ngay sau trán: phần kìm lại, cân nhắc, và nghĩ tới hậu quả của tuần sau. Nó vẫn còn đang được lắp cho tới ngoài hai mươi tuổi — và đó là một sự thật đo được bằng ảnh chụp não, không phải một cách nói.","The last to be finished is the piece just behind the forehead: the one that holds back, weighs things up and thinks about next week. It is still being wired past the age of twenty — and that is a fact from brain scans, not a figure of speech."],['Từ đó ra một chuyện rất dễ chịu cho cả hai phía. Một đứa mười hai tuổi biết rõ điều đúng mà vẫn làm bừa thì không phải là hư, và cũng không phải là chưa hiểu — nó hiểu rồi, chỉ là bộ phanh của nó đang lắp dở. Người lớn nào từng nói với chính mình "biết thế rồi mà sao vẫn làm" thì biết chính xác cảm giác ấy, vì bộ phanh của người lớn cũng có ngày trượt.','From which follows something kinder for both sides. A twelve-year-old who knows the right thing and does the other one is not bad, and is not confused — they understood perfectly; the brakes are simply half-fitted. Any grown-up who has ever said "I knew better and did it anyway" knows the feeling exactly, because grown-up brakes also slip.']],["Đường dây trong não dày lên vì được dùng, và phần lắp sau cùng là phần được dùng ít nhất trong đời một đứa trẻ. Nên cách xây nó không phải là mắng — mà là những lần được tự quyết một việc nhỏ rồi chịu hậu quả nhỏ.","Wiring thickens because it is used, and the last piece fitted is the one a child’s life uses least. So it is not built by scolding — it is built by many small decisions taken alone, each with a small consequence attached."],["Chỗ dễ nhầm: người ta nghĩ hiểu rồi thì tự khắc làm được, nên đứa nào không làm được là đứa chưa hiểu, và giải pháp là giảng thêm. Nhưng biết và kìm được là hai bộ phận khác nhau trong đầu, và bộ phận thứ hai lớn chậm hơn nhiều.","The easy mistake: understanding is assumed to produce doing, so a child who fails is thought not to have understood, and the remedy is more explaining. But knowing and restraining are two different pieces of hardware, and the second grows far more slowly."],["Hồi mười lăm tuổi, bố mẹ có lần nào biết là dại mà vẫn làm không?","At fifteen, was there a time you knew it was foolish and did it anyway?"]),n("nao-doi-duoc",2,["Phân biệt thứ sinh ra đã có với thứ tập mà nên","Tell what you were born with from what practice built"],[["Có thứ sinh ra đã thế, và có thứ mọc ra vì được dùng. Hai loại ấy hay bị xếp lẫn.","Some things you are born with; some grow because they are used. The two get filed together."],["Màu mắt, nhóm máu, vân tay thì cố định — tập kiểu gì cũng không đổi. Đọc chữ, đi xe đạp, bơi, đàn, tiếng nước ngoài thì không cái nào sinh ra đã có cả.","Eye colour, blood group and fingerprints are fixed — no practice moves them. Reading, cycling, swimming, music, another language: not one of them arrives at birth."],["Mỗi lần tập, lớp bọc quanh đường dây làm việc ấy lại dày thêm một chút, và tín hiệu chạy nhanh hơn lần trước. Đó là lý do một việc lúc đầu phải nghĩ từng bước, sau vài tháng thì tay tự làm mà đầu rảnh — không phải vì mình bỗng thông minh hơn, mà vì đường dây ấy đã được đắp dày.","Each repetition adds another layer around the wiring for that job, and the signal runs faster than last time. That is why something that needed step-by-step thought is, months later, done by the hands while the head is free — not from sudden cleverness, but from wiring built up."]],['Cái gì dày lên vì được dùng thì ai dùng cũng dày lên. Nên câu "mình không có khiếu" hầu như luôn là một câu nói về số giờ đã tập, chứ không phải một câu nói về con người.','Whatever thickens from use thickens for anyone who uses it. So "I have no gift for it" is nearly always a statement about hours already spent, not a statement about a person.'],['Chỗ dễ nhầm: người ta nhìn người giỏi ở lúc họ đã giỏi, không nhìn thấy mấy nghìn giờ trước đó. Nên cái nhìn thấy được là "có khiếu", còn cái không nhìn thấy được mới là thứ thật sự làm ra chuyện ấy.',"The easy mistake: we see skilled people only once they are skilled, never the thousands of hours before. So what is visible looks like a gift, while the invisible part is what actually produced it."],["Bố mẹ tập được thứ gì mà lúc đầu tưởng mình không làm nổi?","What did you learn to do that you first thought you could never manage?"]),n("nho-mot-luc-may-thu",2,["Biết chỗ nhớ tạm của mình chứa được bao nhiêu","Know how much your scratch pad holds"],[["Chỗ nhớ tạm trong đầu nhỏ hơn ai cũng tưởng: chừng bốn tới bảy thứ một lúc.","The mind’s scratch pad is smaller than anyone assumes: about four to seven things at once."],["Nghe một dãy mười một chữ số rồi đọc lại ngay là việc gần như không ai làm được — không phải vì kém, mà vì dãy ấy dài gấp đôi chỗ chứa.","Hearing eleven digits and repeating them back at once is something almost nobody manages — not from being dim, but because the string is twice the size of the space."],["Cái chỗ chứa ấy giống nhau ở trẻ con và người lớn, ở học sinh giỏi và học sinh kém. Nên khi cô giáo đọc một đề bốn dữ kiện rồi hỏi luôn, cả lớp đều đang chạm trần cùng một lúc, và đứa nào ghi ra giấy thì đứa ấy vượt lên — không phải vì nhớ hơn, mà vì nó thôi không nhớ nữa.","That space is the same in children and adults, in the top of the class and the bottom. So when a teacher reads out a four-part problem and asks straight away, the whole room hits the same ceiling at once, and whoever writes it down pulls ahead — not by remembering more, but by no longer remembering at all."]],["Vì chỗ chứa không nới ra được, mọi cách học tốt đều đi đường khác: gói nhiều thứ thành một cụm, hoặc đẩy hẳn ra ngoài đầu — ra giấy, ra bảng, ra một dòng ghi chú.","Because the space cannot be widened, every good method goes around it instead: parcel several items into one, or push them out of the head altogether — onto paper, a board, a line of notes."],["Chỗ dễ nhầm: quên mất giữa chừng bị coi là dấu hiệu kém tập trung, nên người ta cố nhớ chặt hơn. Cố chặt hơn không nới được cái trần ấy một li — chỉ có ghi ra hoặc gom cụm mới nới được.","The easy mistake: losing the middle of something is read as poor concentration, so people try to hold on harder. Holding harder does not raise the ceiling by a millimetre — only writing it down or grouping it does."],["Bố mẹ nhớ số điện thoại của mình theo mấy cụm?","How many groups do you break your own phone number into?"]),n("deu-hon-nhieu",3,["Rải giờ học ra thay vì dồn một đêm","Spread the hours instead of piling them into one night"],[["Cùng một số giờ học, xếp hai kiểu khác nhau, cho ra hai kết quả cách nhau rất xa.","The same number of hours, arranged two ways, produce results a long way apart."],["Cày liền một đêm thì sáng hôm sau vẫn thuộc. Đó chính là chỗ đánh lừa: bài kiểm tra hôm sau vẫn qua, nên cách học ấy được thưởng, và được lặp lại.","Cram in one night and it is still there in the morning. That is the trap: the next day’s test is passed, so the method gets rewarded and repeated."],["Một tuần sau thì gần như trống trơn. Cùng số giờ ấy rải ra bốn buổi cách nhau vài ngày thì nhớ được hàng tháng, và người ta đo chuyện này từ hơn một trăm năm trước rồi — đường quên tụt rất dốc trong ngày đầu, rồi thoải dần ra.","A week later there is close to nothing. The same hours spread over four sittings a few days apart last for months, and this was measured more than a century ago — the forgetting curve plunges on the first day, then flattens out."],["Cái nghịch lý nằm ở chỗ này: quên đi một ít RỒI nhớ lại chính là lúc trí nhớ được đắp dày. Học lại lúc còn nhớ rõ thì gần như không thêm được gì, vì chẳng phải lôi cái gì ra cả. Nên khoảng cách giữa hai buổi học không phải chỗ lãng phí — nó là phần việc chính, và nó làm việc trong lúc mình đang ngủ.","Here is the paradox: forgetting a little and then recovering it is the moment the memory thickens. Reviewing while it is still fresh adds almost nothing, because nothing has to be dragged back. So the gap between two sittings is not wasted — it is the main part of the work, and it is done while you sleep."]],["Trí nhớ không đo bằng số lần nhìn thấy, nó đo bằng số lần phải lôi ra từ chỗ sâu. Đặt các buổi học xa nhau ra chính là cách làm cho mỗi lần lôi ra đều nặng hơn một chút.","Memory is not counted in times seen, it is counted in times dragged up from a depth. Placing the sittings further apart is simply how each drag is made a little heavier."],["Chỗ dễ nhầm: cày một đêm cho cảm giác học rất nhiều, vì mệt thật và vì lượng chữ đi qua mắt rất lớn. Cảm giác ấy đo công sức bỏ ra, không đo thứ còn lại tuần sau — mà hai con số đó gần như không liên quan gì tới nhau.","The easy mistake: cramming feels like a great deal of study, because it is genuinely tiring and a great deal of text goes past the eyes. That feeling measures effort spent, not what survives to next week — and the two numbers barely relate."],["Hồi đi học, bố mẹ hay ôn thi kiểu nào?","When you were at school, how did you revise for exams?"]),n("tu-nho-lai",3,["Ôn bằng cách gấp sách lại","Revise by shutting the book"],[["Có hai cách ôn nhìn thì giống nhau, mà hiệu quả chênh nhau gấp mấy lần.","Two ways of revising look alike and are several times apart in what they leave behind."],["Cách thứ nhất: mở sách ra đọc lại, tô vàng những dòng quan trọng. Cách thứ hai: gấp sách lại, tự kể lại xem trong đó có gì, rồi mới mở ra soát.","The first: open the book, reread, highlight the important lines. The second: shut the book, tell yourself what was in it, and only then open up to check."],['Cách thứ nhất dễ chịu hơn hẳn và cho cảm giác thuộc bài, vì mặt chữ quen dần lên. Nhưng cái đầu nhầm cái quen mặt với cái biết, và đó là chỗ hỏng: nhìn thấy một dòng rồi gật đầu "à đúng rồi" hoàn toàn không chứng minh được rằng lúc gấp sách lại mình nói ra được nó.','The first is far pleasanter and produces a feeling of knowing, because the text grows familiar. But the head confuses familiar with known, and that is where it breaks: nodding at a line and thinking "yes, of course" proves nothing about whether you could produce it with the book shut.'],["Cách thứ hai khó chịu: nó phơi ra hết chỗ thủng, và ai cũng ghét cảm giác ấy. Nhưng chính cái phải lôi ra mới là bài tập, còn cái nhìn vào thì không. Đo trong lớp học thật thì nhóm tự kiểm tra nhớ hơn hẳn nhóm đọc lại, dù nhóm đọc lại thấy tự tin hơn nhiều trước lúc thi.","The second is uncomfortable: it exposes every hole in what you know, and nobody enjoys the exposure. But the dragging-up is itself the exercise, while the looking is not exercise at all. Measured in real classrooms, over and over, the self-testing group remembers markedly more of the material than the rereading group does — and does so while feeling much less certain, since the rereading group walks in far more confident than its results deserve."]],["Lôi một thứ ra khỏi trí nhớ làm chính cái đường dẫn tới nó chắc thêm. Nhìn lại nó thì không: đường vẫn nguyên như cũ, chỉ có cảm giác quen là tăng lên.","Dragging something out of memory strengthens the path leading to it. Looking at it again does not: the path is unchanged, only the sense of familiarity has grown."],["Chỗ dễ nhầm: cảm giác tự tin trước lúc thi lại tỉ lệ nghịch với cách học tốt. Cách nào cho cảm giác trôi chảy thì thường là cách để lại ít nhất, còn cách nào làm mình thấy mình dốt thì thường là cách đang xây.","The easy mistake: confidence before an exam runs the wrong way. Whatever method feels smooth usually leaves the least behind, while whatever makes you feel stupid is usually the one building something."],["Bố mẹ thử gấp quyển này lại rồi kể xem vừa đọc được gì nhé?","Shall we shut this and see how much of it you can tell back?"]),n("vao-lai-mach",3,["Tính đúng giá của một lần bị ngắt","Price an interruption honestly"],[["Một cái tin nhắn không tốn mười giây. Nó tốn phần lớn cái giờ đang ngồi.","One message does not cost ten seconds. It costs most of the hour you were sitting in."],["Nhìn màn hình rồi cất máy đi thì đúng là mất mười giây. Nhưng chỗ mình đang nghĩ dở thì không cất đi được, và quay lại chỗ ấy mới là phần tốn kém.","Glancing at the screen and putting the phone down really is ten seconds. But the place you were thinking from cannot be put down, and getting back to it is the expensive part."],["Đo trong công việc thật, quãng quay về ấy thường trên mười lăm phút, có nghiên cứu ra hai mươi ba. Nghĩa là năm cái tin nhắn rải đều trong một tiếng ngồi học thì cái tiếng ấy gần như không còn gì — mà cảm giác thì vẫn là đã ngồi học đủ một tiếng.","Measured in real workplaces the climb back is usually over fifteen minutes, and in one study twenty-three. Which means five messages spread through an hour of study leave almost nothing of the hour — while the feeling is still of an hour spent studying."],["Cái đắt nhất không phải chỗ mất mà là chỗ không nhìn thấy được: không ai cảm thấy mình vừa mất mười lăm phút, vì mười lăm phút ấy trôi qua trong lúc đang làm việc, chỉ là làm ở mức nông hơn. Nên chỗ này không sửa được bằng cách cố tập trung hơn — chỉ sửa được bằng cách dọn cái ngắt đi trước khi ngồi xuống.","The dearest part is not the loss but that it is invisible: nobody feels themselves losing fifteen minutes, because those minutes pass while working, merely at a shallower depth. So this cannot be repaired by concentrating harder — only by clearing the interruptions away before sitting down."]],["Việc khó đòi mang nhiều thứ trong đầu cùng một lúc, mà chỗ nhớ tạm chỉ chứa được vài thứ. Bị ngắt là bị đổ hết cái chồng ấy xuống, và phải xếp lại từ đầu.","Hard work requires several things held in the head at once, and the scratch pad holds only a few. An interruption tips the whole stack over, and it has to be stacked again from the bottom."],["Chỗ dễ nhầm: úp máy xuống mặt bàn được coi là đã cất máy đi. Thí nghiệm cho thấy cùng một cái máy, để phòng bên cạnh cho kết quả tốt hơn để úp trước mặt — vì không với tay cũng đã tốn một phần sức rồi.","The easy mistake: a phone face-down on the desk counts as put away. Experiments show that the same phone in the next room produces better work than the same phone face-down in front of you — because not reaching for it already costs something."],["Lúc làm việc, bố mẹ bị ngắt mấy lần một tiếng?","While you are working, how many times an hour are you interrupted?"]),n("truoc-khi-kip-nghi",2,["Biết có một cái chuông reo trước cả suy nghĩ","Know there is an alarm that rings before thought"],[["Trong đầu có một cái chuông, và nó reo trước phần biết nghĩ chừng hai phần mười giây.","There is an alarm in the head, and it rings about two tenths of a second before the thinking part."],["Đó là lý do mình giật mình trước, rồi mới nhận ra cái vừa rơi chỉ là quyển sách. Cái chuông không chờ hiểu chuyện gì — chờ thì đã muộn với một con hổ.","That is why you flinch first and only then notice the falling thing was a book. The alarm does not wait to understand — waiting would have been too late with a tiger."],['Nó cũ hơn trường học rất nhiều, và nó không phân biệt được hổ với bài kiểm tra: cùng một cái chuông ấy reo cho cả hai, cùng một kiểu tim đập và tay lạnh. Trong lúc nó reo, phần lo việc nghĩ xa gần như tắt — nên câu hỏi "sao lúc ấy không bình tĩnh" hỏi sai chỗ: lúc ấy chưa có ai ở nhà để mà bình tĩnh.','It is much older than school and cannot tell a tiger from a test: the same bell rings for both, the same thumping heart and cold hands. While it rings, the far-sighted part is close to switched off — so "why did you not stay calm" is aimed at nobody: at that instant there was no one home to be calm.']],["Chuông reo không phải một lựa chọn, nên nó không đúng không sai. Cái có lựa chọn là mấy phút sau khi nó reo — và toàn bộ việc tập nằm ở mấy phút đó, không nằm ở tiếng chuông.","The ringing is not a choice, so it is neither right nor wrong. What is chosen is the few minutes after it rings — and all the practice lives in those minutes, not in the bell."],["Chỗ dễ nhầm: người ta nghĩ ai bình tĩnh là người không có cái chuông ấy. Không phải — chuông của họ cũng reo y hệt, họ chỉ có sẵn một việc để làm trong lúc chờ nó tắt.","The easy mistake: calm people are assumed not to have the alarm. They do — theirs rings exactly the same; they simply have something ready to do while waiting for it to stop."],["Có lần nào bố mẹ giật mình xong mới thấy chẳng có gì không?","Have you ever jumped out of your skin and then found there was nothing there?"]),n("con-cho-di-tiep",2,["Thêm một chữ vào câu tự nói với mình","Add one word to the sentence you say to yourself"],[['"Mình không làm được" và "mình chưa làm được" tả cùng một buổi chiều.','"I cannot do this" and "I cannot do this yet" describe the same afternoon.'],["Câu đầu đóng lại: nó nói về con người, và con người thì không sửa trong một tối được. Câu sau để hở một cánh cửa: nó nói về thời điểm, mà thời điểm thì đổi.","The first closes: it is a statement about a person, and a person cannot be altered in an evening. The second leaves a door: it is a statement about timing, and timing moves."],['Nghe thì như một mẹo an ủi, nhưng nó được đo trong lớp học thật: nhóm học sinh được dạy nói "chưa" bỏ cuộc ít hơn hẳn nhóm còn lại khi gặp bài khó, và làm được nhiều bài hơn ở lần thử sau. Một chữ không làm bài toán dễ đi — nó chỉ quyết định có lần thử thứ hai hay không, và gần như mọi bài khó đều được giải ở lần thử thứ hai trở đi.','It sounds like a soothing trick, and it has been measured in real classrooms: the group taught to say "yet" gave up markedly less on hard problems and solved more on the next attempt. One word does not make the problem easier — it only decides whether there is a second attempt, and nearly every hard problem is solved on the second or later.']],["Câu mình tự nói với mình không phải lời bình luận suông — nó quyết định việc tiếp theo có xảy ra hay không, và việc tiếp theo mới là thứ làm ra kết quả.","What you say to yourself is not idle commentary — it decides whether the next attempt happens, and the next attempt is what produces the result."],['Chỗ dễ nhầm: người ta tưởng đây là chuyện nói cho vui vẻ, kiểu tự động viên. Không phải: "chưa" là một câu nói ĐÚNG SỰ THẬT hơn, vì chưa ai đo được giới hạn của một người bằng một buổi chiều.','The easy mistake: this is taken for cheerful self-talk. It is not: "yet" is the more factually accurate sentence, since nobody has ever established the limit of a person from one afternoon.'],["Có việc gì bố mẹ từng nghĩ mình không làm được, rồi hoá ra là chưa?",'Was there something you thought you could not do, and it turned out to be "not yet"?']),n("khen-vao-cho-nao",3,["Khen vào việc đã làm, không khen vào cái sẵn có","Praise what was done, not what was given"],[["Hai câu khen nghe đều tử tế, mà một câu làm trẻ né bài khó.","Two sentences of praise, both kind, and one of them makes children avoid hard work."],['Thí nghiệm rất gọn: hai nhóm trẻ cùng làm xong một bộ câu đố dễ. Nhóm một nghe "con thông minh quá". Nhóm hai nghe "con làm chăm thật đấy". Rồi cho cả hai chọn làm tiếp bộ dễ hay thử bộ khó hơn.','The experiment is tidy: two groups finish the same easy puzzles. One is told "you must be clever". The other, "you must have worked hard". Then both choose between another easy set and a harder one.'],["Nhóm được khen thông minh phần lớn chọn bộ dễ, và khi bị cho làm một bộ thật khó thì bỏ sớm hơn hẳn. Nhóm được khen chăm chỉ phần lớn chọn bộ khó, ngồi lâu hơn với nó, và làm được nhiều hơn ở lần thử sau. Tất cả những khác biệt ấy đến sau đúng một câu nói, và giữa những đứa trẻ mà trước đó không có gì phân biệt được với nhau.","The clever-praised group mostly took the easy set, and when later given a genuinely hard one, gave up on it markedly sooner. The effort-praised group mostly took the harder set, stayed with it longer, and solved more on the attempt after that. All of those differences followed a single sentence, between children who beforehand could not be told apart in any way at all."],["Lý do nằm ở chỗ lời khen ấy dán vào đâu. Khen vào một thứ có sẵn thì đứa trẻ hiểu rằng giá trị của nó nằm ở cái nhãn kia — nên từ đó trở đi, mọi bài khó đều biến thành một mối đe doạ, vì làm không xong nghĩa là mất nhãn, và mất nhãn thì mất luôn chỗ đứng. Khen vào việc nó đã làm thì cái nhãn không tồn tại, nên bài khó chỉ còn là chỗ để làm tiếp: làm được thì thêm một việc làm được, làm không xong thì cũng chẳng có gì để mất cả.","The reason lies in where that praise sticks. Praise aimed at something given teaches a child that their worth lives inside the label — so from then on every hard task turns into a threat, because failing costs the label, and losing the label costs their standing. Praise aimed at what they actually did creates no label at all, which leaves a hard task as simply more work to be done: finish it and there is one more finished thing, fail at it and there is nothing whatever to lose."]],["Lời khen nào cũng dạy một chuyện về chỗ giá trị nằm ở đâu. Nên câu an toàn nhất là câu tả đúng việc vừa làm — nó không phong cho ai danh hiệu nào để phải giữ.","All praise teaches something about where worth is kept. So the safest sentence describes what was just done — it awards no title that then has to be defended."],['Chỗ dễ nhầm: người lớn khen "con giỏi quá" với ý tốt hoàn toàn, và thấy đứa bé sáng mặt lên nên tưởng đã làm đúng. Cái giá thì không hiện ra hôm ấy — nó hiện ra ở lần sau, lúc đứa bé chọn bài dễ hơn mà không ai hiểu vì sao.','The easy mistake: grown-ups say "you are so clever" with entirely good intentions and see the child light up, so it looks right. The cost does not show that day — it shows next time, when the child picks the easier task and nobody understands why.'],["Hồi bé bố mẹ hay được khen câu gì?","What were you praised for when you were small?"]),n("hiem-ma-ai-cung-so",3,["Biết vì sao cái đầu đếm sai chuyện nguy hiểm","Know why a head miscounts danger"],[["Người ta sợ cá mập và không sợ cái xe máy đi mỗi sáng. Hai nỗi sợ ấy đặt sai chỗ.","People fear sharks and not the motorbike ridden every morning. Both fears are in the wrong place."],["Cái đầu không đếm số lần một chuyện xảy ra — nó không có cách nào đếm được. Nó đo bằng một thứ khác hẳn: nghĩ tới một ví dụ dễ hay khó.","A head does not count how often something happens — it has no way of counting. It measures something else entirely: how easily an example comes to mind."],["Mà cái nghĩ tới dễ hay khó thì lại do việc kể quyết định. Một vụ rơi máy bay được kể trên khắp thế giới suốt một tuần; hàng nghìn chuyến bay hạ cánh yên lành thì không ai kể. Nên trong đầu, máy bay thành nguy hiểm, dù đếm ra thì nó là cách đi lại an toàn nhất loài người từng làm được.","And ease of recall is decided by retelling. One crash is retold across the world for a week; thousands of safe landings are retold by nobody. So inside a head, flying becomes dangerous, though by the count it is the safest way of travelling people have ever built."],["Chỗ này không phải chuyện vặt. Thứ giết nhiều người Việt Nam nhất là tai nạn giao thông, và nó xảy ra ngay ngoài cổng, mỗi ngày, không lên tin. Vì không được kể nên không ai sợ, và vì không ai sợ nên cái mũ bảo hiểm cài lỏng vẫn được coi là đủ. Nỗi sợ đặt đúng chỗ thì cứu được người thật; đặt sai chỗ thì nó chỉ làm mình mệt.","This is not a trivial matter. What kills most people in Vietnam is road traffic, and it happens just outside the gate, every day, and never makes the news. Untold, it is unfeared; unfeared, a loosely fastened helmet passes as enough. Fear placed accurately saves real people; placed wrongly it only tires you out."]],["Muốn biết cái gì nguy hiểm thật thì phải đi tìm con số, vì cảm giác trong đầu đang đo một thứ khác — nó đo mức được kể, không đo mức hay xảy ra.","To learn what is actually dangerous you must go and find the number, because the feeling in your head is measuring something else — how much a thing is retold, not how often it happens."],["Chỗ dễ nhầm: người ta tưởng tin tức cho biết thế giới đang thế nào. Tin tức làm đúng việc ngược lại — nó kể những chuyện HIẾM, vì chuyện thường ngày thì không thành tin, nên xem càng nhiều tin càng đoán sai về xác suất.","The easy mistake: the news is taken for a picture of how the world is. It does the opposite job — it reports what is rare, since the everyday is not news, so the more you watch the worse your sense of probability becomes."],["Bố mẹ sợ nhất chuyện gì, và chuyện ấy hay xảy ra tới mức nào?","What are you most afraid of, and how often does it actually happen?"]),n("vi-sao-lam-theo",3,["Nhận ra lúc mình đang làm theo chỉ vì đông người","Notice when you are going along only because of numbers"],[["Có một thí nghiệm rất đơn giản, và nó nói một chuyện không dễ chịu về tất cả mọi người.","There is a very simple experiment, and it says something uncomfortable about everyone."],["Tám người ngồi một hàng, lần lượt nói xem đường nào trong ba đường dài bằng đường mẫu. Câu trả lời rành rành, nhìn là ra. Bảy người đầu là người của thí nghiệm, và cả bảy cùng nói to một đáp án sai.","Eight people sit in a row and say which of three lines matches a sample. The answer is obvious at a glance. The first seven are in on it, and all seven state the same wrong answer aloud."],["Khoảng ba phần tư người thật nói theo cái sai ít nhất một lần. Nhiều người sau đó kể rằng lúc ấy họ đã thật sự bắt đầu nghi ngờ chính mắt mình — không phải nói dối cho yên, mà là mắt bắt đầu thấy khác đi. Đứng một mình chống lại cả nhóm khó tới mức đo được, và nó khó không phải vì người ta hèn: cái đầu coi việc bị cả nhóm bỏ lại là một mối nguy thật.","About three quarters of real subjects went along at least once. Many said afterwards that they had genuinely begun to doubt their own eyes — not lying for a quiet life, but seeing differently. Standing alone against a group is hard by measurement, and hard not from cowardice: a head treats being left behind by the group as a real danger."],["Nhưng thí nghiệm ấy còn một nửa mà gần như không ai kể lại, và nửa ấy mới là nửa đáng nhớ. Chỉ cần MỘT người trong bảy người kia nói đúng — một người thôi, không cần đông, không cần ai hùng hồn — thì tỷ lệ nói theo cái sai tụt xuống gần như bằng không. Người dám nói khác không chỉ cứu được mình khỏi một câu trả lời sai: họ mở cửa cho tất cả những người đang ngồi im quanh đó, và trong bất cứ căn phòng nào cũng thường có nhiều người đang ngồi im hơn mình tưởng rất nhiều.","But the experiment has a half that is rarely retold. If just one of the seven gives the right answer — one, not a faction — going along collapses almost to nothing. The person willing to differ does not only save themselves: they open the door for everyone still silent, and there are usually more silent people in the room than anyone thinks."]],["Cái đầu dùng phản ứng của người xung quanh làm bằng chứng về sự thật, và trong phần lớn trường hợp thì cách ấy đúng. Nó chỉ hỏng đúng lúc cả nhóm cùng sai — mà lúc ấy thì mình không có cách nào biết được.","A head uses the reactions of others as evidence about the world, and most of the time that works. It fails in exactly one case, when the group is wrong together — and that is the case you cannot detect from inside."],['Chỗ dễ nhầm: ai cũng tin mình thuộc một phần tư kia, và chính niềm tin ấy làm mình không đề phòng. Thứ giúp được không phải là tự tin, mà là biết trước cái bẫy tồn tại, và tập nói ra câu "tớ thấy khác" lúc chuyện còn nhỏ.','The easy mistake: everyone believes they are in the other quarter, and that belief is what removes the guard. What helps is not confidence but knowing in advance that the trap exists, and practising the sentence "I see it differently" while the stakes are still small.'],["Có lần nào cả nhóm nói một đằng mà bố mẹ thấy khác không?","Has there been a time when everyone said one thing and you saw it differently?"]),n("goi-dich-danh",2,["Gọi giúp bằng cách chỉ vào một người","Get help by pointing at one person"],[["Càng đông người thì người gặp nạn càng lâu được giúp. Nghe ngược đời mà đo được.","The more people present, the longer help takes to arrive. It sounds backwards and it is measured."],["Một người đi một mình nhìn thấy ai đó ngã thì gần như chắc chắn ra tay. Ba mươi người cùng nhìn thấy thì việc giúp tới chậm hơn hẳn, và có khi không tới.","A lone passer-by who sees somebody fall almost always acts. Thirty people seeing the same thing produce help far more slowly, and sometimes not at all."],["Không phải vì đám đông vô tâm. Mỗi người đều thấy hai mươi chín người khác đang đứng yên, và đọc cái đứng yên ấy thành bằng chứng: chắc chuyện không nghiêm trọng, hoặc chắc đã có ai gọi rồi. Trách nhiệm bị chia nhỏ ra tới mức không còn ai cầm phần nào.","It is not that crowds are heartless. Each person sees twenty-nine others standing still and reads that stillness as evidence: it cannot be serious, or somebody must have called already. Responsibility divides until nobody is holding any."],['Chỗ này có một cách chữa ngắn tới mức trẻ con học được ngay: đừng hét vào đám đông, hãy chỉ tay vào MỘT người và gọi rõ — "anh áo xanh ơi, gọi cấp cứu giúp em". Việc có chủ thì việc được làm. Cùng một câu ấy dùng được cho chính mình lúc cần giúp: nói với một người, nói tên việc, nói rõ cần gì.','There is a repair short enough for a child to learn at once: do not shout at the crowd, point at one person and name them — "you in the blue jacket, please call an ambulance". A job with an owner gets done. The same sentence works when you need help yourself: one person, the task named, the need stated plainly.']],["Đám đông không tạo ra thêm người giúp, nó chỉ chia mỏng trách nhiệm ra. Chỉ đích danh một người là gộp trách nhiệm lại vào một chỗ, và một chỗ thì đủ.","A crowd does not create more helpers, it only thins responsibility. Naming one person gathers it back into a single place, and a single place is enough."],["Chỗ dễ nhầm: người ta tưởng chỗ đông người thì an toàn hơn chỗ vắng. Về chuyện được giúp thì thường ngược lại, trừ khi có ai đó cắt được cái chờ đợi chung ấy bằng một câu gọi đích danh.","The easy mistake: a crowded place is assumed safer than an empty one. For getting help it is often the reverse, unless somebody cuts through the shared waiting with one named request."],["Bố mẹ có bao giờ đứng nhìn một chuyện rồi chờ người khác ra tay không?","Have you ever stood watching something and waited for somebody else to step in?"])],g=[...e,...i,...a,...o,...c,...s,...r],m=t=>g.find(h=>h.card===t);export{g as GIANG,n as bai,y as demTu,m as giangOf,p as trangCua};
